INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('fd489f71-5e7f-58b4-a7bd-0c64ec3d348f', 'fbc0b213-e26d-5ee3-a8c4-efcee9607e36', 'bd20c533-2484-5d47-a93e-cf9036694542', 7, 20, 'በጥፋት ድንጋይ እንዳትሰነካከል፥'),
  ('6356f8e3-b19f-55e9-ad46-901649026bd3', 'fbc0b213-e26d-5ee3-a8c4-efcee9607e36', 'bd20c533-2484-5d47-a93e-cf9036694542', 8, 21, 'ጠላትህን በምድረ በዳ አትመነው።'),
  ('97019474-b012-56fe-a635-6fd1fb62438b', 'fbc0b213-e26d-5ee3-a8c4-efcee9607e36', 'bd20c533-2484-5d47-a93e-cf9036694542', 9, 22, 'በፈቃድህ የማይሄድ ልጅህን ስንኳ አትመነው።'),
  ('86cd3626-fca0-55fb-ab27-fade7369347f', 'fbc0b213-e26d-5ee3-a8c4-efcee9607e36', 'bd20c533-2484-5d47-a93e-cf9036694542', 10, 23, 'በሠራኸው ሥራ ሁሉ ሰውነትህን ደስ አሰኛት፥'),
  ('6f05ff5a-8e14-501d-ad04-ed6f2de39a02', 'fbc0b213-e26d-5ee3-a8c4-efcee9607e36', 'bd20c533-2484-5d47-a93e-cf9036694542', 11, 24, 'ሕጉን የሚጠብቅ ሰው የመጽሓፉን ትእዛዝ ይሰማል፤'),
  ('757e98a4-1add-5f1b-a0e9-c0535baaf86b', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 1, 1, 'ይፈትኑት ዘንድ ነው እንጂ፥'),
  ('6ef872dc-8aa4-5778-a72f-ab9db7fe6678', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 2, 2, 'ብልህ ሰው መጽሐፍ መስማትን ይወድዳል፤'),
  ('fe61b173-60b6-58f8-af15-37ebafc29531', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 3, 3, 'ብልህ ሰው አምኖ በእግዚአብሔር ሕግ ይገዛል፤'),
  ('ca945f6a-f6c1-5411-ac42-17ef68eec4bb', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 4, 4, 'የምትናገረውን ነገርህን አዘጋጅተህ አድምጥ፤'),
  ('5a0f0567-9634-5865-a2c4-7a99c7c0d07e', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 5, 5, 'የሰነፍ ሰው ልቡና እንደ ሰረገላ መንኰራኵር ነው፤'),
  ('3855b4d0-adee-570b-a055-f6cc8c2d522a', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 6, 6, 'ጮሌ ፈረስ እንደ በጎ ወዳጅ ነው።'),
  ('9f9d8ba1-b97a-5246-ab9a-cbea43b8e76f', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 7, 7, 'የዓመቱ ቀን ሁሉ በፀሐይ ብርሃን ጸንቶ ሲኖር፥'),
  ('20b74621-2c8a-5b18-aa67-7783d4e584e7', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 8, 8, 'ቀኑ ሁሉ በእግዚአብሔር ትእዛዝ ይለያል፤'),
  ('671cf852-cd31-520a-ae30-ecf402ca6d47', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 9, 9, 'ከቀኑም የቀደሰውና ያከበረው አለ።'),
  ('4db52705-1ece-5541-ab2a-d6c278550ccc', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 10, 10, 'እኛ ሁላችን የአዳም ልጆች ከመሬት ተገኘን፤'),
  ('15e68cd0-27dc-5812-add0-be73dfb9192c', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 11, 11, 'እግዚአብሔርም በጥበቡ ብዛት ለያቸው፤'),
  ('ed3f92b1-ec49-57ff-acd5-8a26b9cace39', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 12, 12, 'ከእነርሱም የባረካቸውና ከፍ ከፍ ያደረጋቸው አሉ፤'),
  ('4a662349-9ead-56d5-abdf-ac6ada8964fc', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 13, 13, 'እኛ ሁላችን በእርሱ ዘንድ በሸክላ ሠሪ እጅ እንዳለ ጭቃ፥ ነን፤'),
  ('d22f3294-abff-5a6a-a590-ad15ca1a83ae', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 14, 14, 'የክፋት ተቃራኒዋ በጎነት ናት፤'),
  ('dce53dd4-946f-5c76-ac64-086b7d62e633', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 15, 15, 'ከዚህ ሁሉ ጋር የልዑልን ፍጥረቶች ተመልከት፤'),
  ('1bed8d04-4339-5ba4-aae0-46c467fb2181', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 16, 16, 'እኔ ግን ከሁሉ በኋላ ተነሥቼ ይኽን ነገር አሰብሁት፥'),
  ('5680ba16-c40e-5912-ae4a-2fd013ad60b9', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 17, 17, 'አቤቱ በስምህ የተጠሩ ወገኖችህን ይቅር በል፤'),
  ('dcdc4915-0ff0-5a36-a9a8-a153d1b3fdae', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 18, 18, 'ቅድስት ከተማህን፥'),
  ('36a2bb29-ea5b-5ca5-ad22-8d76e91e17d3', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 19, 19, 'ጽዮንንም የቃልህን በረከት ሙላት፤'),
  ('dbd5a2c9-b954-5e63-a972-d63b6b4c4ffd', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 20, 20, 'አስቀድሞ ለፈጠርሃቸው ሕግህን ስጣቸው፤'),
  ('e33a817b-1ccd-54df-aeb5-a8f7d3051a95', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 21, 21, 'ነቢያትህን ያምኗቸው ዘንድ ተስፋ ላደረጉህ ዋጋቸውን ስጣቸው።'),
  ('16057d0b-f869-5597-a9d7-b08dd63b06bb', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 22, 22, 'የአሮንንም በረከት በሕዝብህ ላይ አሳድር፤'),
  ('2c085422-01a8-5b6a-a385-4236c90ea7d9', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 23, 23, 'እህል ሁሉ ይበላል፤ ወደ ሆድም ይወርዳል፤'),
  ('d83f96c1-2234-5dc8-ad75-2611d7d41227', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 24, 24, 'የእህልን ጣዕም ሁሉ ጕሮሮ ይለየዋል፥'),
  ('8f650603-2384-55ab-afef-5552a9b12f45', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 25, 25, 'ክፉ ልቡና ኀዘንን ያመጣል፤'),
  ('dd14ca27-be4f-5896-a5e2-abffe3e0bfb7', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 26, 26, 'ወንድ ሁሉ ሚስት ያገባል፤'),
  ('a96140e1-d9e6-544e-ac67-3deee7f4b256', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 27, 27, 'የሴት ውበቷ ፊትን ያበራዋል፤'),
  ('c2718a4d-1cb9-5e31-af2e-4f3e4692bedc', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 28, 28, 'የዋህ ብትሆን፥ ቃሏም ያማረ ቢሆን፤'),
  ('890f67da-0cd9-5fbf-a237-ad73562d8e88', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 29, 29, 'ረዳቱ፥ መደገፊያ ምሰሶውም ናትና፥'),
  ('7550e836-d6d5-55c1-a314-6f2c4bd6f597', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 30, 30, 'ቅጥር የሌለው ቤት ገንዘቡ እንዲሠረቅ፥'),
  ('de18f810-8848-52d0-a678-8fe1df7a5240', '7c73631b-8416-54ed-a15f-1667531afba5', '8d465f58-6226-5db0-a3d8-03be36d4f523', 31, 31, 'ከከተማ ወደ ከተማ የሚዞር ሌባን የሚዋሰው ማን ነው?'),
  ('0a0d91c5-14e8-52c6-a328-49e80fe6b0ef', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 1, 1, 'ወዳጅ ያበጀ ሰው ሁሉ እኔም ወዳጁ ነኝ ይላል፤'),
  ('09a96ab5-6bd0-51c2-a4de-7a82b20022ae', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 2, 2, 'በልቡናው ግን እስከሚሞትበት ቀን ድረስ ኀዘን ይኖራል፤'),
  ('47aecbe4-c487-57eb-a0a9-cadf3dfb72ad', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 3, 3, 'ክፉ ምኞት ሆይ! ከወዴት ተገኘሽ፤'),
  ('d354ccb2-b4bd-5450-a523-6431f3fa433e', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 4, 4, 'በደስታህ ጊዜ የሚቀርብህ ወዳጅ አለ፤'),
  ('984d05b7-31fc-5630-afcb-cbe4fc9610a8', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 5, 5, 'በበሽታህ ጊዜ ስለ ሆዱ የሚያዝንልህ ወዳጅ አለ፤'),
  ('0e193bf2-be4c-581e-ad5d-27690fcb87af', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 6, 6, 'በተመቸህ ጊዜ ወዳጅህን አትርሳ፤'),
  ('95b6949f-8f0b-57c2-a6c4-4441066082e0', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 7, 7, 'መካር ሁሉ ምክርን ይመክራል፤'),
  ('99f78a05-3d67-5fdc-a8f7-5aef1dd8555e', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 8, 8, 'ከሚመክርህ ሰው ልቡናህን ጠብቅ፤'),
  ('8700ea28-f0b6-57e5-a70c-93dd7973d679', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 9, 9, 'ገንዘብህን የሚያጠፋብህን ነገር ያመጣብሃል'),
  ('87943a90-c6eb-54f0-a572-9139346e52f4', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 10, 10, 'ከሚጠባበቅህ ሰው ጋራ አትማከር፤'),
  ('b2b4992a-4a81-5e34-a659-29a8a2ca905f', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 11, 11, 'ከሴት ጋር ስለሚያስቀናት ነገር አትናገር፤'),
  ('ec87bc67-adf7-5c11-af1b-94b5f029dbdf', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 12, 12, 'ሃይማኖት እንዳለው ከምታውቀው፥ እግዚአብሔርንም ከሚፈራ፥'),
  ('1739c618-d5d7-587d-a32f-ea2530ff0616', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 13, 13, 'እርስዋ ከሁሉ ይልቅ ታማኝህ ናትና፤'),
  ('abde8164-be67-501c-a0fa-b1d74c2c0635', '3011ba20-50f8-5c65-ab3b-f9609899fc62', '1b85b3b6-0f1f-59b7-a996-3ac1d55bfec3', 14, 14, 'የሰው ልቡና ከሰባት ጠባቂዎች ይልቅ'),
