  ('4cb11fb8-393f-53df-aac2-bcbc43845a69', 'b284ddee-e242-5df5-a645-15d3f3cf3f89', 'e82356db-7479-58c6-ab8b-e74c1ada0555', 2, 2, 'እግዚአብሔር ብዙ ክብርን ሰጥቶአቸዋልና፥')
