  ('d0172e06-a12e-5a46-ae35-f7d94ce67247', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 8, 8, 'አቤቱ ይቅርታህን ዐሰብሁ፥'),
