  ('43ffe1b0-25a6-53bf-a99f-15e25d616cd1', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 12, 12, 'ከሞትም አዳንኸኝ፤ መከራ ከሚመጣበት ቀንም አዳንኸኝ፥'),
