  ('4798801d-9511-5739-a2b9-c7f7af0021fa', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 17, 17, 'በእርሷም ከፍ ከፍ አልሁ፤'),
  ('6143a4f8-9554-52e3-a550-09385a039e67', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 18, 18, 'አደርጋትም ዘንድ ዐሰብሁ፤'),
  ('fa30de63-0a87-5ca2-a08d-29178f1ab193', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 19, 19, 'ሰውነቴም በእርሷ ተበረታታች፤'),
