  ('b2855664-21cd-5c26-ac9a-e90600acd740', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 21, 21, 'ሰውነቴም ለእርስዋ ታወከች፤ መረመረቻትም፤'),
  ('a16cab30-afd2-5f78-aba2-809862dbd2fe', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 22, 22, 'እግዚአብሔርም አንደበትን ዋጋ አድርጎ ሰጠኝ፤'),
  ('55d98705-944c-5a5f-aa6e-697dca8066e3', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 23, 23, 'እናንት አላዋቂዎች፥ ወደ እኔ ቅረቡ፤'),
  ('609c9e79-f7f2-5e83-af68-55ec74d9d70a', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 24, 24, 'እንዴት አጣችኋት? እስኪ ንገሩኝ!'),
  ('6c85796b-c621-5599-addd-7551dc5b4c7a', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 25, 25, 'አፌን ከፍቼ፥ “ያለ ዋጋ ገንዘብ አድርጓት” ብዬ ተናገርሁ።'),
  ('443cc6e8-9a62-5a53-aab7-437d03070e39', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 26, 26, 'አንገታችሁን ዝቅ አድርጉ፤ ቀንበሯንም ተሸከሙ፤'),
  ('dd65657e-65c6-5cb1-a82e-e19afc2c1247', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 27, 27, 'እነሆ፥ ጥቂት ደክሜ በእርሷ ብዙ ዕረፍትን እንዳገኘሁ፥'),
  ('0a85ce96-e915-586f-a756-b6c9294ba872', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 28, 28, 'ከብዙ ብር ይልቅ ጥበብን ምረጧት፤'),
  ('fc2d9393-6792-5ae0-a131-6fb0d80eead6', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 29, 29, 'ሰውነታችሁም በቸርነቱ ደስ ይበላት፤'),
  ('fc23b9b1-1697-5be8-aff7-c7bf4017426d', '6ec9b04f-89d9-5ba6-a4e2-55acf9c7e717', '6fa5c9df-f3ed-5824-af44-90f54d0caec2', 30, 30, 'በጊዜው ዋጋችሁን ይሰጣችሁ ዘንድ፥'),
  ('7be8011c-6d7b-594a-a86f-7576ac9e2bb8', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 1, 1, 'በይሁዳ ነገሥታት በዖዝያንና በኢዮአታም፥ በአካዝና በሕዝቅያስ ዘመን ስለ ይሁዳና ስለ ኢየሩሳሌም ያየው የአሞጽ ልጅ የኢሳይያስ ራእይ።'),
  ('c627c4a3-050f-5bb7-ac54-f6662341fbd7', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 2, 2, 'እግዚአብሔር እንዲህ ብሎ ተናግሮአልና፥ “ሰማይ ስማ፤ ምድርም አድምጪ፤ ልጆችን ወለድሁ፤ አሳደግሁም፤ እነርሱም ዐመፁብኝ።'),
  ('c19b4958-a81a-526c-a3ce-4fa98d28782e', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 3, 3, 'በሬ ገዢውን አህያም የጌታውን ጋጥ ዐወቀ፤ እስራኤል ግን አላወቁኝም፤ ሕዝቤም አላስተዋሉኝም።”'),
  ('05c5277e-095b-5589-abcb-c4aeeff47510', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 4, 4, 'ኀጢአተኛ ወገንና ዐመፅ የተሞላበት ሕዝብ፥ የክፉዎች ዘር፥ በደለኞች ልጆች ሆይ፥ ወዮላችሁ! እግዚአብሔርን ተዋችሁት፤ የእስራኤልንም ቅዱስ አስቈጣችሁት።'),
  ('918b4dd4-f83d-5e46-aee2-0a3738d071c7', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 5, 5, 'እንግዲህ በበደል ላይ በደል እየጨመራችሁ ለምን ትቀሠፋላችሁ? ራስ ሁሉ ለሕማም፥ ልብም ሁሉ ለኀዘን ሆኖአል።'),
  ('4048205c-e653-530f-ab7f-433a73278b01', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 6, 6, 'ከእግር ጫማ አንሥቶ እስከ ራስ ድረስ ጤና የለውም፤ ቍስልና እበጥ የሚመግልም ነው፤ አልፈረጠም፤ አልተጠገነምም፤ በዘይትም አልለዘበም።'),
  ('c58e81f2-869e-5101-ad2d-b1e958f95d33', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 7, 7, 'ምድራችሁ ባድማ ናት፤ ከተሞቻችሁ በእሳት ተቃጠሉ፤ እርሻችሁንም በፊታችሁ ባዕዳን ይበሉታል፤ ጠላትም ያጠፋዋል፤ ባድማም ያደርገዋል።'),
  ('a0ac675e-132b-5932-a54f-0552cc41f3dc', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 8, 8, 'የጽዮንም ሴት ልጅ በወይን ቦታ እንዳለ ዳስ፥ እንደ አዝመራ ጠባቂም ጎጆ፥ እንደ ተከበበችም ከተማ ሆና ቀረች።'),
  ('beccc088-2a26-5563-a39d-06a10efd2e84', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 9, 9, 'የሠራዊት ጌታ እግዚአብሔር ዘርን ባያስቀርልን ኖሮ፥ እንደ ሰዶም በሆንን፥ እንደ ገሞራም በመሰልን ነበር።'),
  ('a0e356d7-30eb-591d-a3a9-77f800f18c79', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 10, 10, 'እናንተ የሰዶም አለቆች ሆይ፥ የእግዚአብሔርን ቃል ስሙ፤ እናንተ የገሞራ ሕዝብ ሆይ፥ የእግዚአብሔርን ሕግ አድምጡ።'),
  ('ecf92591-ffb1-5f96-a4d4-37a781a33b16', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 11, 11, '“የመሥዋዕታችሁ ብዛት ለእኔ ምንድን ነው?” ይላል እግዚአብሔር፤ “የሚቃጠለውን የአውራ በግ መሥዋዕትንና የፍሪዳን ስብ ጠግቤአለሁ፤ የበሬና የአውራ ፍየልም ደም ደስ አያሰኘኝም።'),
  ('f3e14e0f-0e62-5da7-a125-6de829328c67', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 12, 12, 'በእኔ ፊት ልትታዩ ብትመጡ፥ ይህን ከእጃችሁ የሚሻ ማን ነው? እንግዲህ አደባባዬን ደግማችሁ አትረግጡም።'),
  ('6c495c9a-1bcf-5bfe-af24-4622e6998408', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 13, 13, 'መልካሙን የስንዴ ዱቄት ብታመጡ እንኳ ከንቱ ነው፤ ዕጣናችሁ በእኔ ዘንድ አስጸያፊ ነው፤ መባቻዎቻችሁንና ሰንበቶቻችሁን፥ ታላቋን፥ ቀናችሁን፥ ጾማችሁንና ሥራ መፍታታችሁን አልወድም።'),
  ('a660ef29-b0df-51a3-acc3-630fd4fc6558', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 14, 14, 'መባቻችሁንና በዓላቶቻችሁን ነፍሴ ጠልታለች፤ አስጸያፊ ሆናችሁብኛል፤ ኀጢአታችሁንም ይቅር አልልም።'),
  ('9137ddce-72d9-5950-a1a1-c643b486257f', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 15, 15, 'እጃችሁን ወደ እኔ ብትዘረጉ፥ ዐይኖችን ከእናንተ እመልሳለሁ፤ ምህላንም ብታበዙ አልሰማችሁም፤ እጆቻችሁ ደምን ተሞልተዋልና።'),
  ('49d94fe7-f123-5122-a19e-de70bba7eb24', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 16, 16, 'ታጠቡ፤ ንጹሓንም ሁኑ፤ የሰውነታችሁን ክፋት ከዐይኖች ፊት አስወግዱ፤ ክፉ ማድረግንም ተዉ፤'),
  ('c1535106-1537-537e-ac81-557357f77464', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 17, 17, 'መልካም መሥራትን ተማሩ፤ ፍርድን ፈልጉ፤ የተገፋውን አድኑ፤ ለድሃአደጉ ፍረዱለት፤ ስለ መበለቲቱም ተሙአገቱ።”'),
  ('1d68559c-f5f8-5319-ae0d-e77362aa3eed', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 18, 18, '“ኑና እንዋቀስ” ይላል እግዚአብሔር፤ ኀጢአታችሁ እንደ አለላ ቢሆን እንደ በረዶ አነጻዋለሁ፤ እንደ ደምም ቢቀላ እንደ ባዘቶ አጠራዋለሁ።'),
  ('de216445-387a-52a5-a935-ac0d1a4226e7', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 19, 19, 'እሽ ብትሉና ብትሰሙኝ የምድርን በረከት ትበላላችሁ፤'),
  ('b6fdc7db-54da-5cc4-ac29-1efd95c031b2', '88731e41-8111-5090-abcd-dcd2ec08df1c', '4c2c8086-da4c-5001-abc8-32d30c8f9804', 20, 20, 'እንቢ ብትሉና ባትሰሙኝ ግን ሰይፍ ትበላችኋለች፤ የእግዚአብሔር አፍ ይህን ተናግሮአልና።'),
  ('6385fa1b-8c5f-5f42-a456-982ee6ec3eab', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 1, 21, 'ፍርድ መልቶባት የነበረ የታመነችይቱ የጽዮን ከተማ እንዴት ጋለሞታ ሆነች! ጽድቅ አድሮባት ነበር፤ አሁን ግን ወንበዴዎችና ነፍሰ ገዳዮች አሉባት።'),
  ('16412eb0-29fc-5d03-a2cf-840483d42dc7', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 2, 22, 'ወርቅሽና ብርሽ ዛገ፥ የወይን ጠጅ አሳላፊዎችሽም በወይን ጠጅሽ ላይ ውኃን ይደባልቃሉ።'),
  ('6b16124c-a81c-51cf-a795-81cc8dcef332', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 3, 23, 'አለቆችሽ ዐመፀኞችና የሌቦች ባልንጀሮች ሆኑ፤ ሁሉ ጉቦ ይወድዳሉ፤ ፍርድንም ሊያጣምሙ ይፈልጋሉ፤ ለሙት ልጅ አይፈርዱም፤ የመበለቲቱንም አቤቱታ አያዳምጡም።'),
  ('1e8b1589-5d7c-5323-ae5a-ca7f2f941a45', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 4, 24, 'ስለዚህ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “ለእስራኤል ኀያላን ወዮላቸው! በጠላቶች ላይ ቍጣዬ አይበርድም፤ ጠላቶችንም እበቀላለሁ።'),
  ('dde7f1d5-e0ef-598b-aab3-d4e68cce0879', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 5, 25, 'እጄንም በአንቺ ላይ አመጣለሁ፤ አግልሻለሁ፤ ዝገትሽንም አነጻለሁ፤ ቆርቆሮሽንም ሁሉ አስወግዳለሁ፤ ዐመፀኞችን አጠፋለሁ፤ ሕገ ወጦችንም ከአንቺ አስወግዳለሁ፤ ትዕቢተኞችንም አዋርዳለሁ።'),
  ('0b51fafc-bb47-5d6a-aa0c-ab9c4fc7b2fe', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 6, 26, 'ፈራጆችሽንም እንደ ቀድሞ፥ አማካሪዎችሽንም እንደ መጀመሪያ ጊዜ አስነሣለሁ፤ ከዚያም በኋላ የጽድቅ ከተማ፥ የታመነችም ጽዮን ርእሰ ከተማ ተብለሽ ትጠሪያለሽ።'),
  ('c324a98a-a3ac-54eb-a5b7-7819ce043848', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 7, 27, 'ምርኮኞችሽ በእውነትና በምጽዋት ይድናሉ።'),
  ('c51a0c0f-592f-57f8-af4a-c9d52b2b4017', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 8, 28, 'በደለኞችና ኀጢአተኞች ግን በአንድነት ይቀጠቀጣሉ፤ እግዚአብሔርንም የሚተዉት ሁሉ ይጠፋሉ።'),
  ('e316131a-90bd-5fa8-a885-a30ca901ccd6', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 9, 29, 'በወደዱአቸው ጣዖታት ያፍራሉና፥ በፈለጉአቸውም የአድባር ዛፎች ዕፍረት ይይዛቸዋልና፤'),
  ('05ce2822-a073-5a27-ab35-d2861c001228', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 10, 30, 'ቅጠልዋ እንደ ረገፈ የጠርቤንቶስ ዛፍ፥ ውኃም እንደሌለበት የአትክልት ቦታ ይሆናሉና።'),
  ('44c97dda-f508-5cf5-a77d-4fcee1999ac9', '88731e41-8111-5090-abcd-dcd2ec08df1c', '0c201873-6cf3-50f5-aba6-3957035378ed', 11, 31, 'ኀይላቸውም እንደ መቃ መስዬ፥ ሥራቸውም እንደ ጠለሸት ይሆናል፤ ኃጥአንና ዐማፅያንም አብረው ይቃጠላሉ፤ እሳቱንም የሚያጠፋላቸው ያጣሉ።”'),
  ('d6543b69-12f3-5538-aa06-0e2ee1943472', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 1, 1, 'ስለ ይሁዳና ስለ ኢየሩሳሌም ወደ አሞፅ ልጅ ወደ ኢሳይያስ የመጣ ቃል።'),
  ('2860f8cb-914e-5540-a2a6-a11adcce1c82', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 2, 2, 'በኋላ ዘመን እንዲህ ይሆናል፤ የእግዚአብሔር ቤት በተራሮች ራስ ላይ ይታያል፤ ከኮረብቶችም በላይ ከፍ ከፍ ይላል፤ አሕዛቡም ሁሉ ወደ እርሱ ይመጣሉ።'),
  ('b096a7e3-8d37-542b-a0a2-200a7992d9fa', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 3, 3, 'ሕግ ከጽዮን፥ የእግዚአብሔርም ቃል ከኢየሩሳሌም ይወጣልና ብዙዎች አሕዛብ መጥተው፥ “ኑ፤ ወደ እግዚአብሔር ተራራ፥ ወደ ያዕቆብ አምላክ ቤት እንውጣ፤ እርሱም መንገዱን ያስተምረናል፤ በጎዳናውም እንሄዳለን” ይላሉ።'),
  ('d9ca4fc8-4972-570e-ae38-aea044f1f404', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 4, 4, 'በአሕዛብም መካከል ይፈርዳል፤ ብዙ አሕዛብንም ይዘልፋቸዋል፤ ሰይፋቸውንም ማረሻ፥ ጦራቸውንም ማጭድ ለማድረግ ይቀጠቅጣሉ፤ ሕዝብም በሕዝብ ላይ ሰይፍን አያነሣም፤ ሰልፍንም ከእንግዲህ ወዲህ አይማሩም።'),
  ('6fdfc737-7b2d-5191-a9b1-f995086543c4', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 5, 5, 'አሁንም የያዕቆብ ቤት ሆይ፥ ኑ፤ በእግዚአብሔር ብርሃን እንመላለስ።'),
  ('a4489851-7400-5743-a73c-8f92c630810b', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 6, 6, 'ሕዝቡን የያዕቆብን ቤት ትቶአልና፤ ምድራቸው እንደ ቀድሞው እንደ ፍልስጥኤማውያን ምድር በሟርት ተሞልቶአልና፤ እንደ ባዕድ ልጆችም ሆነዋልና፤ ብዙ እንግዶች ልጆችም ተወልደውላቸዋልና።'),
  ('5f73f090-88cb-580e-a04c-3ad15e0e6bd6', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 7, 7, 'ምድራቸውም በብርና በወርቅ ተሞልታለች፤ ለመዛግብቶቻቸውም ቍጥር የለውም፤ ምድራቸውም ደግሞ በፈረሶች ተሞልታለች፤ ለሰረገሎቻቸውም ቍጥር የለውም።'),
  ('7a81fd35-eff3-5164-a7ea-e0ab65a016af', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 8, 8, 'ምድራቸውም በእጆቻቸው በሠሩአቸው ጣዖታት ተሞልታለች፤ በጣቶቻቸውም ለሠሩአቸው ይሰግዳሉ።'),
  ('5ec006b0-90a2-53e8-a352-5967356034e0', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 9, 9, 'ታናሹም ሰው ዝቅ ብሎአል፤ ታላቁም ሰው ተዋርዶአል፤ ኀጢአታቸውንም ይቅር አልላቸውም።'),
  ('d23eb883-b016-5b19-a651-dd86b47c305b', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 10, 10, 'አሁንም ምድርን ያነዋውጣት ዘንድ በተነሣ ጊዜ እግዚአብሔርን ከመፍራትና ከግርማው ክብር የተነሣ ወደ ድንጋይ ዋሻ ግቡ፤ በመሬት ውስጥም ተሸሸጉ።'),
  ('c4e883a0-130b-5f0a-a899-3971fc93249f', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 11, 11, 'የትዕቢተኞች ሰዎች ዐይኖች ይዋረዳሉ፤ የሰዎችም ኵራት ትወድቃለች፥ በዚያም ቀን እግዚአብሔር ብቻ ከፍ ከፍ ይላል።'),
  ('9c768705-c80e-58c5-ae5f-abf9da5cda88', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 12, 12, 'የሠራዊት ጌታ የእግዚአብሔር ቀን በትዕቢተኛውና በኵራተኛው ሁሉ ላይ ከፍ ባለውም ላይ ይሆናል፤ እነርሱም ይዋረዳሉ፤'),
  ('90e83f35-d670-5eeb-a024-8e047cae2a43', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 13, 13, 'ደግሞም በረጅሙ ከፍ ባለውም በሊባኖስ ዝግባ ሁሉ ላይ፥ በባሳንም ዛፍ ሁሉ ላይ፥'),
  ('e520f33a-4818-5a06-a91c-6a0d7f76afcc', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 14, 14, 'በረጅሙም ተራራ ሁሉ ላይ፥ ከፍ ባለውም ኮረብታ ሁሉ ላይ፥'),
  ('6599ddd9-6434-50b7-aafe-7a7d6851a401', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 15, 15, 'በረጅሙም ግንብ ሁሉ ላይ፥ በተመሸገውም ቅጥር ሁሉ ላይ፥'),
  ('102da5be-2667-5d72-ac43-95e7bd782744', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 16, 16, 'በባሕሩም መርከብ ሁሉ ላይ፥ በተጌጡ ጣዖታትም ምስል ሁሉ ላይ ይሆናል።'),
  ('0cc07344-e7ab-57f0-a0d0-e30e191c6057', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 17, 17, 'ሰውም ሁሉ ይዋረዳል፤ የሰውም ኵራት ይወድቃል፤ በዚያም ቀን እግዚአብሔር ብቻ ከፍ ከፍ ይላል።'),
  ('e2847cfb-0d10-506c-afd5-562b42d97cb6', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 18, 18, 'በእጅ የተሠሩ ጣዖታትን ሁሉ ይሰውራሉ፤'),
  ('6a695ee3-8f0a-5c59-a03d-c8848af7d9c8', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 19, 19, 'እግዚአብሔርም ምድርን ያናውጥ ዘንድ በተነሣ ጊዜ እግዚአብሔርን ከመፍራትና ከግርማው ክብር የተነሣ ወደ ድንጋይ ዋሻና ወደ ምድር ንቃቃት ውስጥ ያገቡአቸዋል።'),
  ('978c7915-c1e6-55e2-a168-895534e4dbee', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 20, 20, 'በዚያም ቀን ሰው ይሰግድላቸው ዘንድ ያበጁአቸውን የብሩንና የወርቁን ጣዖቶቹን ለፍልፈልና ለሌሊት ወፍ ይጥላል።'),
  ('dcd9d702-4e65-57ef-a61d-6b01fe1428f7', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 21, 21, 'እግዚአብሔርም ምድርን ያናውጥ ዘንድ በተነሣ ጊዜ እግዚአብሔርን ከመፍራትና ከግርማው ክብር የተነሣ ወደ ድንጋይ ዋሻና ወደ ተሰነጠቁ ዓለቶች ውስጥ ያገባሉ።'),
  ('7f0afd71-a0b2-507b-a26c-e4d24b9a45c8', '98f65e6d-34a2-5471-ac7d-18916bc2fe9f', '2243e039-c619-5520-aede-e2949b930443', 22, 22, 'እስትንፋሱ በአፍንጫው ያለበትን ሰው ተዉት፤ እርሱ ስለ ምን ይቈጠራል?'),
  ('62e0aa0e-bb41-5eae-a333-debadb1d4830', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 1, 1, 'እነሆ፥ የሠራዊት ጌታ እግዚአብሔር ከኢየሩሳሌምና ከይሁዳ ኀይለኛውን ወንድና ኀይለኛዋን ሴት፥ የእንጃራን ኀይል ሁሉ፥ የውኃውንም ኀይል ሁሉ ያስወግዳል፤'),
  ('fe86b1cc-c930-5d8f-a054-cba66965a1a1', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 2, 2, 'ኀያሉንም፥ ተዋጊውንም፥ ፈራጁንም፥ ነቢዩንም፥ ዐዋቂውንም፥ ሽማግሌውንም፥'),
  ('99b1856a-7e55-5268-a1a1-95c26ac175da', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 3, 3, 'የአምሳ አለቃውንም፥ የተከበረ አማካሪውንም፥ ጠቢቡንም፥ የአናጢዎቹንም አለቃ፥ አስተዋይ አድማጩንም ያስወግዳል።'),
  ('fd30c440-1a5c-51f8-a51b-0b52ce0b52ac', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 4, 4, 'በእነርሱ ላይ አለቆቻቸው እንዲሆኑ ጐልማሶችን እሾምባቸዋለሁ፤ ዘባቾችም ይገዙአቸዋል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5a8508e4-ea7d-5ef5-a7d3-4d6a29e2e5f2', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 5, 5, 'ሕዝብ በሕዝብ ላይ፥ ሰው በሰው ላይ፥ ሰውም በባልንጀራው ላይ ይገፋፋል፤ ብላቴናውም በሽማግሌው ላይ፥ የተጠቃውም በከበርቴው ላይ ይታበያል።'),
  ('c4faa00a-28d7-5115-a523-ee02ea467d73', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 6, 6, 'ሰውም በአባቱ ቤተ ሰብእ ውስጥ ወንድሙን ይዞ፥ “አንተ ልብስ አለህ፥ አለቃም ሁንልን፥ ምግባችንም ከእጅህ በታች ትሁን” ቢለው፥'),
  ('7b508e9a-a0dd-5a91-ac9d-bf11806aaa20', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 7, 7, 'በዚያ ቀን ድምፁን ከፍ አድርጎ፥ “እኔ በቤቴ ውስጥ እንጀራ ወይም ልብስ የለኝምና ለሕዝቡ አለቃ አልሆንም” ብሎ መለሰለት።'),
  ('80a4f866-8eb4-5464-a9a3-2be9fdc21b8a', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 8, 8, 'ኢየሩሳሌም ተፈትታለችና፥ ይሁዳም ወድቃለችና፥ አንደበታቸውም ዐመፅን ስለሚናገር ለእግዚአብሔር አልታዘዙም።'),
  ('c8ce5c90-b213-5795-a8ef-1636cdf2be63', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 9, 9, 'ዛሬም ክብራቸው ተዋርዷልና፥ ፊታቸውም አፍሯልና ኀጢአታቸው እንደ ሰዶምና እንደ ገሞራ ኀጢአት ተቃወመቻቸው፤ በላያቸውም ተገልጣ ታወቀች።'),
  ('71e13257-5aee-5320-a6ff-91fc4b2bdc5e', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 10, 10, 'ክፉ ምክርን መክረዋልና ለነፍሳቸው ወዮላት! እንዲህም አሉ፥ “ጻድቁን እንሻረው፤ ሸክም ሆኖብናልና፤” ስለዚህ የእጃቸውን ሥራ ፍሬ ይበላሉ።'),
  ('a001a0d8-5e0d-5258-aa20-c2b027372dae', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 11, 11, 'እንደ እጁ ሥራ ፍዳው ይደረግበታልና ለበደለኛ ወዮ! ክፉም ይደርስበታል።'),
  ('836acf42-15bc-52cc-a27e-81a3475cd6ac', '2e52af04-81b4-57b2-ab27-5791b773ee03', '5ce706cd-4446-542e-aa76-bcc6c48445c0', 12, 12, 'ሕዝቤ ሆይ፥ ገዥዎቻችሁ ያስጨንቁአችኋል፤ አስጨናቂዎች ሴቶችም በላያችሁ ይሠለጥኑባችኋል። ሕዝቤ ሆይ፥ የሚያመሰግኑአችሁ ያስቱአችኋል፤ የምትሄዱበትንም መንገድ ያጠፋሉ።'),
  ('07783b4b-3670-5af3-ace9-d612e4315331', '2e52af04-81b4-57b2-ab27-5791b773ee03', '60c8fca4-bfdc-5e30-ada4-dba003ffc6d5', 1, 13, 'ነገር ግን እግዚአብሔር ዛሬ ለፍርድ ይነሣል፤ በሕዝቡም ላይ ሊፈርድ ይነሣል።'),
  ('9a7be4f7-d9d1-5487-a19a-3f0d07cc563a', '2e52af04-81b4-57b2-ab27-5791b773ee03', '60c8fca4-bfdc-5e30-ada4-dba003ffc6d5', 2, 14, 'እግዚአብሔር ከሕዝቡ ሽማግሌዎችና ከአለቆቻቸው ጋር ለፍርድ ይመጣል፤ እንዲህም ይላል፥ “ወይኔን አቃጥላችኋል፤ ከድሃው የበዘበዛችሁትም በቤታችሁ አለ፤'),
  ('8a9baa58-89c3-5b63-ad2c-87c11f2c19bd', '2e52af04-81b4-57b2-ab27-5791b773ee03', '60c8fca4-bfdc-5e30-ada4-dba003ffc6d5', 3, 15, 'ሕዝቤንስ ለምን ትገፋላችሁ? የድሃውን ፊትስ ለምን ታሳፍሩታላችሁ?”'),
  ('19e4d446-f582-5f4e-a2f4-f90cbcb85ada', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 1, 16, 'እግዚአብሔር እንዲህ አለ፥ “የጽዮን ቆነጃጅት ኰርተዋልና፥ አንገታቸውን እያሰገጉ በዐይናቸውም እያጣቀሱ፥ በእግራቸውም እያረገዱ፥ ልብሳቸውንም እየጐተቱ፥ በእግራቸውም እያማቱ ይሄዳሉና፤'),
  ('88449aae-ad8a-5f0f-aac0-6e2222e2dc0f', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 2, 17, 'ስለዚህ ጌታ የጽዮን ታላላቅ ሴቶች ልጆችን ያዋርዳቸዋል። እግዚአብሔርም በዚያ ቀን ልብሳቸውን ይገልጣል።'),
  ('ba9c541d-0f49-5535-a455-44d25059e4eb', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 3, 18, 'በዚያም ቀን እግዚአብሔር የእግር አልቦውን ክብር፥ መርበቡንም፥ ጨረቃ የሚመስለውንም ጌጥ፥'),
  ('b1a8af09-902d-5f57-a0dc-bef1ab092d6d', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 4, 19, 'የጆሮ እንጥልጥሉንም፥ አንባሩንም፥ መሸፈኛውንም፥ ቀጸላውንም፥'),
  ('af76561f-197b-5dbb-a40f-42475c89687e', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 5, 20, 'ሰንሰለቱንም፥ መቀነቱንም፥ የሽቱውንም ዕቃ፥ አሸንክታቡንም፥'),
  ('c542053d-7c8c-54b8-abb6-940f40fcea32', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 6, 21, 'የእጅና የአፍንጫ ቀለበቱንም፥'),
  ('1fd42fc9-022b-5922-ab44-a29fc7c879c8', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 7, 22, 'የዓመት በዓልንም ልብስ፥ መጐናጸፊያውንም፥ ልግምበገላውንም፥ ከረጢቱንም፥'),
  ('76b0ea66-94cf-57c1-aeac-774ef0ce28f8', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 8, 23, 'መስተዋቱንም ከጥሩ በፍታ የተሠራውንም ልብስ፥ ራስ ማሰሪያውንም፥ ዐይነ ርግቡንም ያስወግዳል።'),
  ('e6264141-af2b-5430-a090-eb060f52edea', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 9, 24, 'እንዲህም ይሆናል፤ ስለ ሥራሽ ክፋት በሽቱ ፋንታ ትቢያ ይሁንብሽ፤ በወርቅ መታጠቂያሽም ፋንታ ገመድ ታጠቂ፤ በራስ ወርቅ ቀጸላሽም ፋንታ ቡሃነት ይውጣብሽ፤ በሐር መጐናጸፊያሽ ፋንታ ማቅ ልበሽ።'),
  ('a1f71b39-777a-5372-a5c0-3c5f65e109a1', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 10, 25, 'የምትወጂው ትልቁ ልጅሽ በሰይፍ ይወድቃል፤ ኀያላንሽም በውጊያ ይወድቃሉ።'),
  ('d3da54f8-2613-5fe2-a6e5-a8dbf12168f6', '2e52af04-81b4-57b2-ab27-5791b773ee03', '6771a434-252c-58f3-a3ed-6eed9e20aaab', 11, 26, 'የጌጦችሽም ሣጥኖች ያለቅሳሉ፤ ይዋረዳሉም፤ ብቻሽንም ትቀሪያለሽ፤ ከምድርም ጋር ትቀላቀያለሽ።”'),
  ('8e9a6cc8-9177-5f8f-ab66-c66adb1b0475', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', 'b42db7f5-4628-5739-a662-598681c3d428', 1, 1, 'በዚያም ቀን ሰባት ሴቶች፥ “የገዛ እንጀራችንን እንበላለን፤ የገዛ ልብሳችንንም እንለብሳለን፤ ስምህ ብቻ በእኛ ላይ ይጠራ፤ መሰደባችንንም አርቅልን” ብለው አንዱን ወንድ ይይዙታል።'),
  ('9415081d-487d-51c0-ac51-f0cf41084746', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', '25316f18-fbf5-5acd-aa26-22e5814ca5de', 1, 2, 'በዚያም ቀን እግዚአብሔር ከእስራኤል የተረፉትን ያከብርና ከፍ ያደርግ ዘንድ በጌትነቱ ምክር በምድር ላይ ያበራል።'),
  ('3edbba3b-233a-5639-ae48-69338d70a415', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', '25316f18-fbf5-5acd-aa26-22e5814ca5de', 2, 3, 'በጽዮን የቀሩ፥ በኢየሩሳሌምም የተረፉ፥ በኢየሩሳሌም ለሕይወት የተጻፉ ሁሉ፥ ቅዱሳን ይባላሉ።'),
  ('7c2a1152-83f9-5edc-a6bb-975b599621d8', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', '25316f18-fbf5-5acd-aa26-22e5814ca5de', 3, 4, 'እግዚአብሔር የጽዮንን ሴቶች ልጆችና ወንዶች ልጆች እድፍ ያጥባልና፥ በፍርድ መንፈስና በሚያቃጥል መንፈስም ከመካከላቸው ደምን ያነጻልና።'),
  ('01f1b142-fc0e-5bbd-aa44-832adc4b78d2', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', '25316f18-fbf5-5acd-aa26-22e5814ca5de', 4, 5, 'እግዚአብሔርም ይመጣል፤ በጽዮን ተራራ ላይ ባለ ቦታ ሁሉ፥ በዙሪያውም ላይ ደመና በቀን እንደ ጢስ፥ በሌሊትም እንደሚቃጠል የእሳት ብርሃን ይጋርዳል፤ በክብርም ሁሉ ላይ መጋረጃ ይሆናል።'),
  ('2b3f8f00-2512-5592-a290-eca21c85ac6d', '6992e497-adf1-5bb5-a22b-f62870b2bcf5', '25316f18-fbf5-5acd-aa26-22e5814ca5de', 5, 6, 'ከሙቀት ለጥላ፥ ከዐውሎ ነፋስና ከዝናብም ለመጠጊያና ለመሸሸጊያ ጎጆ ይሆናል።'),
  ('347c91c6-681e-56ff-ae52-d3f442ac3305', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 1, 1, 'አሁን የወይኔን ቦታ በተመለከተ የወዳጄን መዝሙር ለወዳጄ እዘምራለሁ። ለወዳጄ በፍሬያማው ቦታ ላይ የወይን ቦታ ነበረው።'),
  ('7c100891-35fc-5786-a660-6a68ea74a88f', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 2, 2, 'አጥር አጠርሁ፤ በዙሪያውም ቈፈርሁ፤ ድንጋዮችንም ለቅሜ አወጣሁ፤ ምርጥ የሆነውንም ወይን ተከልሁ፤ በመካከሉም ግንብ ሠራሁ፤ ደግሞም የመጥመቂያ ጕድጓድ ማስሁለት፤ ወይንንም ያፈራ ዘንድ ጠበቅሁት፤ ዳሩ ግን እሾህን አፈራ።'),
  ('34053638-e19a-57cf-a91a-ae8fefd07b91', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 3, 3, 'አሁንም እናንተ በኢየሩሳሌም የምትኖሩና የይሁዳ ሰዎች ሆይ፥ በእኔና በወይኑ ቦታዬ መካከል እስኪ ፍረዱ።'),
  ('8690da58-49ba-54ea-aa55-915b7ca060d6', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 4, 4, 'ለወይኔ ያላደረግሁለት፥ ከዚህ ሌላ አደርግለት ዘንድ የሚገባኝ ምንድን ነው? ወይንን ያፈራል ብዬ ጠበቅሁት፤ ነገር ግን እሾህን አፈራ።'),
  ('92f058ca-f063-523d-ab37-45ae0e5bb235', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 5, 5, 'አሁንም በወይኔ ላይ የማደርገውን እነግራችኋለሁ፤ አጥሩን እነቅላለሁ፤ ለብዝበዛም ይሆናል፤ ቅጥሩንም አፈርሳለሁ፤ ለመራገጫም ይሆናል።'),
  ('4080962a-3368-5e7f-a652-5d8aa7c05857', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 6, 6, 'ባድማ አደርገዋለሁ፤ አይገረዝም፤ አይኰተኰትም፤ እንደ ጠፍ ቦታ ኵርንችትና እሾህ ይበቅልበታል፤ ዝናብንም እንዳያዘንቡበት ደመናዎችን አዝዛለሁ።'),
  ('4f528588-816c-53b1-a37c-4dc2dd42f30d', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 7, 7, 'የሠራዊት ጌታ የእግዚአብሔር ወይን ቦታ እርሱ የእስራኤል ቤት ነው፤ ተወዳጁ አዲስ ተክልም የይሁዳ ሰዎች ናቸው፤ ፍርድን ያደርጋል ብየ እጠብቅ ነበር፤ እነሆም፥ ዐመፅን አደረገ፤ ጽድቅንም አይደለም፥ ጩኸትን እንጂ።'),
  ('13f01368-1fc0-5424-ab6b-b27498c57b8c', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 8, 8, 'ከጎረቤቶቻቸው እርሻ ይወስዱ ዘንድ፥ ምድርንም ለብቻቸው ይይዟት ዘንድ፥ ቤትን ከቤት ጋር ለሚያያይዙ፥ እርሻንም ከእርሻ ጋር ለሚያቀራርቡ ወዮላቸው!'),
  ('337a6087-df57-5154-ada5-0f2f3d12bee6', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 9, 9, 'ይህ በሠራዊት ጌታ በእግዚአብሔር ጆሮ ተሰምቶአልና፦ ቤቶች ቢሠሩ ባድማ ይሆናሉ፤ ታላላቅና የሚያምሩ ቤቶችም የሚቀመጥባቸው አይኖርም።'),
  ('a9e69d36-1c96-5ada-acb7-fb5ccf6f6fc6', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 10, 10, 'ዐሥር ጥማድ በሬ ካረሰው የወይን ቦታ አንድ ፊቀን ወይን ጠጅ ይወጣል፤ ስድስት መስፈሪያ የዘራ ሦስት መሥፈሪያ ብቻ ያገባል።'),
  ('d6b110a6-df6a-54eb-a590-bdd2bf3724cd', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 11, 11, 'በጥዋት ወደ መሸታ ቤት ለሚገሠግሡና በመጠጥ ቤት ለሚውሉ ወዮላቸው! ወይኑ ያቃጥላቸዋልና።'),
  ('6289a0a4-4805-5139-ad35-e8e9e7db1a25', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 12, 12, 'በመሰንቆና በበገና፥ በከበሮና በእምቢልታም እየዘፈኑ የወይን ጠጅን ይጠጣሉ፤ የእግዚአብሔርን ሥራ ግን አልተመለከቱም፤ የእጁንም ሥራ አላስተዋሉም።'),
  ('15aa5017-b839-543c-a0b0-524939761409', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 13, 13, 'ስለዚህም ሕዝቤ ወደ ምርኮ ሄዱ፤ እግዚአብሔርን አላወቁትምና፤ ብዙዎቹ በረኃብና በውኃ ጥም ሞቱ፤'),
  ('539a25a0-6640-572d-a016-52ed72091f73', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 14, 14, 'ሲኦልም ሆድዋን አስፍታለች፤ አፍዋንም ያለ ልክ ከፍታለች፤ የተከበሩና ታላላቅ ሰዎች ባለጠጎቻቸውና ድሆቻቸውም ወደ እርስዋ ይወርዳሉ።'),
  ('7c69a738-999d-5ab3-ab45-e153f4b39f97', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 15, 15, 'ታናሹ ሰውም ይጐሰቍላል፤ ታላቁ ሰውም ይዋረዳል፤ የትዕቢተኞችም ዐይኖች ይዋረዳሉ፤'),
  ('d6338729-e764-5fd6-a306-26f69458d4e7', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 16, 16, 'የሠራዊት ጌታ እግዚአብሔር ግን በፍርድ ከፍ ከፍ ይላል፤ ቅዱሱም አምላክ በጽድቅ ይከብራል።'),
  ('fdfbddd7-f91a-5d86-aa7c-17f7f7b6b680', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 17, 17, 'የተማረኩ እንደ በሬዎች ይሰማራሉ፤ የተረሱትም ምግባቸውን ሲፈልጉ እንደ በግ ጠቦቶች በማሰማርያቸው ይሰማራሉ።'),
  ('ad8bb57f-57b9-5f14-aaa2-3a4f1d343f00', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 18, 18, 'በደልን እንደ ረዥም ገመድ ለሚስቡ፥ ኀጢአትንም እንደ በሬ ቀንበር ለሚያስሩ ወዮላቸው!'),
  ('1cc63916-a3bb-5303-a30f-a951789bb647', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 19, 19, '“እናይ ዘንድ፥ ሥራውን ያፋጥን፤ እናውቃትም ዘንድ የእስራኤል ቅዱስ ምክር፥ ትምጣ” ለሚሉ ወዮላቸው!'),
  ('03e23edc-0315-52b3-aec9-250d22dfaaa0', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 20, 20, 'ክፉውን መልካም መልካሙንም ክፉ ለሚሉ፥ ጨለማውን ብርሃን ብርሃኑንም ጨለማ ለሚያደርጉ፥ ጣፋጩን መራራ መራራውንም ጣፋጭ ለሚያደርጉ ወዮላቸው!'),
  ('12aeab1f-b74a-5384-aafa-e4cb6ee1d0e5', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 21, 21, 'ለክፋት ጥበበኞች ለሆኑ፥ እኛ ጠቢባን ነን ለሚሉም ወዮላቸው!'),
  ('40e4a01b-f607-520f-a7d7-e16c5a0201f1', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 22, 22, 'የወይን ጠጅ ለሚጠጡ ኀያላን፥ የሚያሰክረውንም መጠጥ ለሚደባልቁ ጽኑዓን ወዮላቸው!'),
  ('02cb5a33-83ce-5646-a7fd-a299c4b982fe', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 23, 23, 'በደለኛውን ስለ ጉቦ ጻድቅ ለሚያደርጉ፥ የጻድቁንም ጽድቅ ለሚያስወግዱበት ወዮላቸው!'),
  ('093ce451-1331-520d-a61a-b450b004bc9a', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 24, 24, 'ስለዚህ ገለባ በእሳት ፍም እንደሚቃጠል፥ በነበልባልም እንደሚበላ፥ እንዲሁ የእነርሱ ሥር የበሰበሰ ይሆናል፤ አበባቸውም እንደ ትቢያ ይበንናል፤ የሠራዊት ጌታ የእግዚአብሔርን ሕግ ጥለዋልና፤ የእስራኤልም ቅዱስ የተናገረውን ቃል አቃልለዋልና።'),
  ('dc4ac94c-3d64-5540-a72a-66c75dd5c972', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 25, 25, 'ስለዚህ የሠራዊት ጌታ እግዚአብሔር በሕዝቡ ላይ ታላቅ ቍጣን ተቈጣ፤ እጁንም በላያቸው ዘርግቶ መትቶአቸዋል፤ ተራሮችም ተንቀጠቀጡ፤ ሬሳቸውም በመንገድ መካከል እንደ ጕድፍ ሆኖአል። በዚህም ሁሉ እንኳ ቍጣው አልተመለሰችም፤ ነገር ግን እጁ ገና ተዘርግታ ትኖራለች።'),
  ('5218e670-f308-5b22-a8cb-6540a67ac43c', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 26, 26, 'በሩቅ ላሉ አሕዛብም ምልክትን ያቆማል፤ ከምድርም ዳርቻ በፉጨት ይጠራቸዋል፤ እነሆም፥ እየተጣደፉ ፈጥነው ይመጣሉ።'),
  ('4fc7691f-98f7-5b5a-a06e-1b86051d106c', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 27, 27, 'አይራቡም፤ አይጠሙምም፤ አይደክሙም፤ አይተኙም፤ የወገባቸውን መታጠቂያ አይፈቱም፤ የጫማቸውም ማዘቢያ አይበጠስም።'),
  ('e29c5c9a-dc15-5d70-a485-482fde70bbd3', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 28, 28, 'ፍላጾቻቸው ተስለዋል፤ ቀስቶቻቸውም ሁሉ ተለጥጠዋል፤ የፈረሶቻቸውም ኮቴ እንደ ቡላድ፥ የሰረገሎቻቸውም መንኰራኵር እንደ ዐውሎ ነፋስ ይቈጠራል።'),
  ('96c37743-b99e-5288-ac73-ebe5e5b956c6', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 29, 29, 'ጩኸታቸው እንደ አንበሳ ነው፤ እንደ አንበሳ ደቦሎችም ይቆማሉ፤ ከጕድጓዱ እንደሚወጣ አውሬም ይነጥቃሉ፤ ይጮሃሉ፤ የሚድንም የለም።'),
  ('b18d945b-98ab-593a-aee6-2738425218f6', 'da42c90e-52d1-5f6a-a100-e7c02017823e', '9fee1072-cf34-58d6-a7de-b1057d77be0c', 30, 30, 'በዚያም ቀን እንደ ባሕር መትመም ይተምሙባቸዋል፤ ወደ ምድርም ይመለከታሉ፤ ድቅድቅ ጨለማን ያያሉ፤ ይጨነቃሉም።'),
  ('734523b0-fc80-5d4e-a1c2-673dac8b18db', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 1, 1, 'ከዚህም በኋላ ንጉሡ ዖዝያን በሞተበት ዓመት እግዚአብሔርን በረዥምና ከፍ ባለ ዙፋን ላይ ተቀምጦ አየሁት፤ ምስጋናውም ቤቱን ሞልቶት ነበር።'),
  ('985a91ed-566f-55ce-a714-9af7f323cc7b', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 2, 2, 'ሱራፌልም በዙሪያው ቆመው ነበር፤ ለእያንዳንዱም ስድስት ክንፍ ነበረው፤ በሁለቱ ክንፎቻቸው ፊታቸውን ይሸፍኑ ነበር፤ በሁለቱም ክንፎቻቸው እግሮቻቸውን ይሸፍኑ ነበር፤ በሁለቱም ክንፎቻቸው ይበርሩ ነበር።'),
  ('c7764a5d-f96b-54a9-ac24-e495aa769e75', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 3, 3, 'አንዱም ለአንዱ፥ “ቅዱስ፥ ቅዱስ፥ ቅዱስ፥ የሠራዊት ጌታ እግዚአብሔር፤ ምድር ሁሉ ከክብሩ ተሞልታለች” እያለ ይጮኽ ነበር።'),
  ('f66e0b8b-a2b4-5514-a59c-6d21228d95f0', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 4, 4, 'የመድረኩም መሠረት ከጩኸታቸው ድምፅ የተነሣ ተናወጠ፤ ቤቱንም ጢስ ሞላበት።'),
  ('be463b95-dc35-53e2-a9fa-069ad9b52c9c', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 5, 5, 'እኔም፥ “ከንፈሮች የረከሱብኝ ሰው በመሆኔ፥ ከንፈሮቻቸው በረከሱባቸው ሕዝብ መካከል በመቀመጤ ዐይኖች የሠራዊትን ጌታ ንጉሡን እግዚአብሔርን ስለ አዩ ጠፍቻለሁና ወዮልኝ!” አልሁ።'),
  ('c38d61ef-d6c2-57cb-a1ff-035631e06c62', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 6, 6, 'ከሱራፌል አንዱ ወደ እኔ ተላከ፤ በእጁም ከመሠዊያው በጕጠት የወሰደው ፍም ነበረ።'),
  ('4b69fdf8-030d-57a7-a3d8-8bded9747a00', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 7, 7, 'አፌንም ዳሰሰበትና፥ “እነሆ፥ ይህ ከንፈሮችህን ነክቶአል፤ በደልህም ከአንተ ተወገደ፤ ኀጢአትህም ተሰረየልህ” አለኝ።'),
  ('44d02002-a56a-5fd4-ab54-6a5a88872e71', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 8, 8, 'የጌታንም ድምፅ፥ “ማንን እልካለሁ? ማንስ ወደዚያ ሕዝብ ይሄድልናል?” ሲል ሰማሁ? እኔም፥ “እነሆኝ፥ ጌታዬ፥ እኔን ላከኝ” አልሁ።'),
  ('efb1d447-3b69-52f0-aa78-31b43c9bfec4', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 9, 9, 'እርሱም፥ “ሂድ፤ ይህን ሕዝብ፦ መስማትን ትሰማላችሁ፥ አታስተውሉምም፤ ማየትንም ታያላችሁ፥ አትመለከቱምም” በላቸው አለኝ።'),
  ('bbc72824-339e-5d6b-a5c3-b0be03d4f4df', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 10, 10, 'እነዚህ ሕዝቦች በዐይናቸው እንዳያዩ፥ በጆሮአቸውም እንዳይሰሙ፥ በልባቸውም እንዳያስተውሉ ተመልሰውም እንዳልፈውሳቸው፥ ልባቸውን አደንድነዋልና፥ ጆሮአቸውንም ደፍነዋልና፥ ዐይኖቻቸውንም ጨፍነዋልና።'),
  ('ac3c3ae4-b864-5fc9-ad53-719da5cf4908', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 11, 11, 'እኔም፥ “ጌታዬ ሆይ፥ እስከ መቼ ድረስ ነው?” አልሁ። እርሱም መልሶ እንዲህ አለኝ፥ “ከተሞች የሚኖርባቸውን አጥተው እስኪፈርሱ ድረስ፥ ቤቶችም ሰው አልቦ እስኪሆኑ፥ ምድርም ፈጽሞ ባድማ ሆና እስክትቀር ድረስ ነው፤”'),
  ('f844dd34-665d-550b-a27a-afee3e9ba74c', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 12, 12, 'ከዚያም በኋላ እግዚአብሔር ሰዎችን ያርቃል፤ በምድርም የቀሩት ይበዛሉ።'),
  ('a552efe7-6674-589d-a09e-0ad341d8f40e', '366d30aa-7571-5141-ab4b-e734fb2f658d', '4b7ec0ef-2333-574f-a921-10b532078303', 13, 13, 'በእርስዋም ዘንድ ዐሥረኛ እጅ ቀርቶ እንደ ሆነ እርሱ ደግሞ ይቃጠላል፤ ቅጠሎቻቸውም በረገፉ ጊዜ እንደ ግራርና እንደ ኮምበል ዛፍ ሁነው ይቀራሉ።'),
  ('4fe9647f-515b-514a-a1c0-8b4381555fee', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 1, 1, 'እንዲህም ሆነ፤ በይሁዳ ንጉሥ በዖዝያን ልጅ በኢዮአታም ልጅ በአካዝ ዘመን የአራም ንጉሥ ረአሶን፥ የእስራኤልም ንጉሥ የሮሜልዩ ልጅ ፋቁሔ ኢየሩሳሌምን ሊወጉ ወጡ፤ ሊይዙአትም አልቻሉም።'),
  ('00b1a5af-5a92-56b0-a494-690b48363688', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 2, 2, 'ለዳዊት ቤትም፥ “አራም ከኤፍሬም ጋር ተባብረዋል” የሚል ወሬ ተነገረ፤ የእርሱም ልብ የሕዝቡም ልብ የዱር ዛፍ በነፋስ እንደሚናወጥ ተናወጠ።'),
  ('8333538d-4cf0-5122-a670-9a3f3dc1d4af', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 3, 3, 'እግዚአብሔርም ኢሳይያስን አለው፥ “አንተና ልጅህ ያሱብ አካዝን ትገናኙት ዘንድ በልብስ አጣቢው እርሻ መንገድ ወዳለው ወደ ላይኛው መታጠቢያ ቦታ ውጡ፤'),
  ('7967e8df-7912-5214-af68-35de85ff2649', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 4, 4, 'እንዲህም በለው፥ “ተጠበቅ፥ ዝምም በል፤ አትፍራ፤ ከእነዚህ ከሚጤሱ ሁለት የእንጨት ጠለሸቶች፥ የተነሣ ልብህ አይደንግጥ፤ ከተቈጣሁ በኋላ ይቅር እላለሁና።'),
  ('1c2d9108-b6af-5122-ab2a-befacd3653b5', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 5, 5, 'የአራም ልጅና የሮሜልዩ ልጅ ፋቁሔ፦ ክፉ ምክርን ተማከሩብህ እንዲህ ብለው፦'),
  ('5fee0d81-8677-552c-a68f-222609783d75', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 6, 6, 'ወደ ይሁዳ እንውጣና እንነጋገራቸው፤ ወደ እኛም እንመልሳቸው፤ የጣብኤልንም ልጅ እናንግሥባቸው፤”'),
  ('8f343b17-0b1f-5db0-a6ed-3f0fbfe3ea80', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 7, 7, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “ይህ ምክር አይጸናምና አይሆንም።'),
  ('3546a9f6-e1d2-5294-a35e-68a29adc4013', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 8, 8, 'የአራም ራስ ደማስቆ ነው፤ የደማስቆም ራስ ረአሶን ነው፤ በስድሳ አምስት ዓመት ውስጥ የኤፍሬም መንግሥት ከሕዝብ ይጠፋል፤'),
  ('f00050a0-5954-525b-a248-38d247337e2d', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7d457c3c-ddce-5f44-a992-5550f8982a42', 9, 9, 'የኤፍሬምም ራስ ሳምሮን ነው፤ የሳምሮንም ራስ የሮሜልዩ ልጅ ፋቁሔ ነው። ባታምኑ አትጸኑም።”'),
  ('1fa04f25-db5b-5642-ae7c-2b45b47d765f', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 1, 10, 'እግዚአብሔርም ደግሞ አካዝን እንዲህ ብሎ ተናገረው፦'),
  ('3a4ee23d-cb71-5a1b-a22e-28f7473d908e', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 2, 11, '“ከጥልቁ ወይም ከከፍታው ቢሆን ከአምላክህ ከእግዚአብሔር ምልክትን ለአንተ ለምን።”'),
  ('ea6e5e59-c982-5d42-aee7-10a93b08cb16', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 3, 12, 'አካዝም፥ “አልለምንም፤ አምላኬ እግዚአብሔርንም አልፈታተንም” አለ።'),
  ('a913acd5-a1d5-5b5f-a4e1-3456f72f202f', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 4, 13, 'እርሱም አለ፥ “እናንተ የዳዊት ቤት ሆይ፥ ስሙ፤ በውኑ ሰውን ማድከማችሁ ቀላል ነውን? እግዚአብሔርን ታደክማላችሁ፤'),
  ('01eb3c19-8447-5d03-ab22-fbd0016230aa', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 5, 14, 'ስለዚህ ጌታ ራሱ ምልክት ይሰጣችኋል፤ እነሆ፥ ድንግል ትፀንሳለች፤ ወንድ ልጅንም ትወልዳለች፤ ስሙንም አማኑኤል ብላ ትጠራዋለች።'),
  ('8348b402-fd9c-5659-af43-a98e9a7c0a73', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 6, 15, 'ሕፃኑ ክፉን ለመጥላት መልካሙንም ለመምረጥ ሳያውቅ ቅቤና ማር ይበላል።'),
  ('78519d14-8eb2-500a-a51b-9f3d2286fa91', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 7, 16, 'ሕፃኑ ክፉን ለመጥላት፥ መልካሙን ለመምረጥ ሳያውቅ፥ የፈራሃቸው የሁለቱ ነገሥታት ሀገር ባድማ ትሆናለች።'),
  ('e160e85d-215f-5d49-ad6d-2298371fb7cd', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 8, 17, 'እግዚአብሔርም ኤፍሬም ከይሁዳ ከተለየበት ቀን ጀምሮ ያልመጣውን ዘመን በአንተና በሕዝብህ በአባትህም ቤት ላይ ያመጣል፤ እርሱም የአሦር ንጉሥ መምጣት ነው።”'),
  ('21d75777-52a1-56de-a288-84c40e9fbba5', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 9, 18, 'በዚያም ቀን እንዲህ ይሆናል፤ እግዚአብሔር በግብፅ ወንዝ ዳርቻ ያለውን ዝንብ፥ በአሦርም ሀገር ያለውን ንብ በፉጨት ይጠራል።'),
  ('1fad9bb5-5771-5e36-a16b-fa8a0b1c41b6', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 10, 19, 'ይመጡማል፤ እነርሱም ሁሉ በሸለቆ፥ በመንደሮች፥ በምድር ጕድጓድ፥ በድንጋይም ዋሻ ውስጥ በጫካ ሁሉ ላይ ይሰፍራሉ።'),
  ('0cacdd79-231c-5834-a235-0ca8c902e73d', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 11, 20, 'በዚያም ቀን እግዚአብሔር ከወንዙ ማዶ ባመጣው ታላቅ ምላጭ በአሦር ንጉሥ የራሱንና የእግሩን ጠጕር ይላጨዋል፤ ምላጩም ጢሙን ደግሞ ይላጫል።'),
  ('26e01d3f-aac7-5dc4-abfd-e2ab3af123b9', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 12, 21, 'በዚያም ቀን እንዲህ ይሆናል፤ ሰው ከላሞቹ አንዲት ጊደርንና ሁለት በጎችን ያሳድጋል፤ የአንዲት በግ ወተትም ሁለት ሰዎችን ያጠግባል።'),
  ('5f9f2e68-731d-5506-ad82-d3d872867cdc', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 13, 22, 'ወተትም ይበዛል፤ በሀገሪቱ መካከል የቀረ ሁሉ ቅቤና ማር ይበላል።'),
  ('cadf31be-c24e-5e7e-ae31-422eb48c3bbf', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 14, 23, 'በዚያም ወራት እንዲህ ይሆናል፤ ወይን በሀገሩ ሁሉ የበጀ ይሆናል፤ የአንድ ሺህ የወይን ዳስ ዋጋ አንድ ሺህ የብር ሰቅል ይሆናል። ከዚህ በኋላ ዳግመኛ ምድር ሁሉ ትጠፋለች፤ እሾህንና ኵርንችትንም ትሞላለች፤ ፍርሀትም ይመጣል።'),
  ('e917a0a6-c64a-5dff-ae4e-338edc6581cb', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 15, 24, 'በፍላጻና በቀስት ይገቡባታል፤ ምድሪቱ ሁሉ ትጠፋለችና፥ እሾህንና ኵርንችትንም ትሞላለችና።'),
  ('3d6bb256-0251-56b9-a64e-b908fe0b0c9d', 'b8356400-5094-5e17-ae13-0f2edfc989b1', '7c72c29d-2b32-523c-a8b5-22ab90ef09c3', 16, 25, 'በሚታረሰውም ተራራ ሁሉ ላይ ፍርሀት ይመጣል፤ የበጎች መሰማርያ ይሆናል፤ በሬዎችም ይረግጡታል፤ እሾህና ኵርንችትም ያጠፋዋል።'),
  ('9eb3afb8-db41-5b10-a0cb-a34a2badd6b2', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 1, 1, 'እግዚአብሔርም አለኝ፥ “ታላቅ አዲስ ሰሌዳ ወስደህ፦ ‘ቸኩለህ ማርክ፤ ፈጥነህም በዝብዝ’ ብለህ በሰው ብርዕ ጻፍበት።'),
  ('50cb55fa-408b-58ae-abf8-4e98ebd1071a', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 2, 2, 'የታመኑትን ሰዎች ካህኑን ኦርያንና የበራክዩን ልጅ ዘካርያስን ምስክሮች አድርግልኝ፤ የእግዚአብሔር መንፈስ አድሮባቸዋልና፤”'),
  ('198f4012-161a-59f6-a5e9-b4335d6c8d25', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 3, 3, 'ወደ ነቢዪቱም ቀረብሁ፤ እርስዋም ፀነሰች፤ ወንድ ልጅም ወለደች። እግዚአብሔርም አለኝ፥ “ስሙን ‘ቸኩለህ ማርክ፤ ፈጥነህም በዝብዝ’ ብለህ ጥራው።'),
  ('2ac4aead-8710-535f-a494-c7fd36e4e3a9', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 4, 4, 'ሕፃኑ አባቱንና እናቱን መጥራት ሳያውቅ የደማስቆን ሀብትና የሰማርያን ምርኮ በአሦር ንጉሥ ፊት ይወስዳልና።”'),
  ('672f50ce-a165-5061-a30c-0da15aa408c4', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 5, 5, 'እግዚአብሔርም ደግሞ ተናገረኝ፤ እንዲህም አለኝ፦'),
  ('fa379323-c1fd-588a-a953-edfdacb63376', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 6, 6, '“እኒህ ሕዝብ በቀስታ በሚሄደው በሰሊሆም ውኃ ቍርጥ ምክርን መከሩ፤ ረአሶንንና የሮሜልዩን ልጅ ያነግሡላቸው ዘንድ ይወዳሉና።'),
  ('f12cc670-dc84-5e5d-a3c6-ae8ff4ca2e9d', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 7, 7, 'ስለዚህ፥ እነሆ፥ እግዚአብሔር ብርቱና ብዙ የሆነውን የወንዝ ውኃ፥ የአሦርን ንጉሥና ክብሩን ሁሉ ያመጣባቸዋል፤ ወንዙም ሞልቶ ይወጣል፤ በዳሮቻቸውም ሁሉ ላይ ይፈስሳል፤'),
  ('23e4c590-aa4a-59ea-a08a-ef2ef558eef5', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 8, 8, 'ከይሁዳ ወንድ ሰውን ሁሉ ያጠፋል፤ ኀያላኑንም ይጨርሳል፤ ሰፈሩም በሰፊው ምድርና በሀገሮቻቸው ሁሉ ይሞላል፤” እግዚአብሔር ከእኛ ጋር ነውና።'),
  ('011859b4-f542-54e6-ac85-827b099c2bef', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 9, 9, 'አሕዛብ ሆይ፥ ዕወቁና ደንግጡ፤ እስከ ምድር ዳርቻም ስሙ፤ ኀያላን! ድል ሁኑ፤ ዳግመኛም ብትበረቱ እንደ ገና ድል ትሆናላችሁ።'),
  ('6f4b0285-1110-506c-a240-f6688e4d556b', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 10, 10, 'ምክርን ብትመክሩም እግዚአብሔር ምክራችሁን ይለውጣል፤ የተናገራችሁትም ነገር አይሆንላችሁም። እግዚአብሔር ከእኛ ጋር ነውና።'),
  ('ad6360dc-abee-583d-a106-1c34b10aeed8', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 11, 11, 'የሠራዊት ጌታ እግዚአብሔር በጽኑ እጅ እንዲህ ተናገረኝ፤ በዚህም ሕዝብ መንገድ እንዳልሄድ አስጠነቀቀኝ፤'),
  ('5706b44a-4b00-519e-a705-912093712dee', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 12, 12, 'እንዲህም አለኝ፥ “ይህ ሕዝብ፦ ከባድ ነው የሚለውን ሁሉ፦ ከባድ ነው አትበሉ፤ መፈራታቸውንም አትፍሩ፤ አትደንግጡም።'),
  ('5ab9b420-b6f9-5b08-a2ba-bc209ef128b6', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 13, 13, 'ነገር ግን የሠራዊትን ጌታ እግዚአብሔርን ቀድሱት፤ የሚያስፈራችሁና የሚያስደነግጣችሁም እርሱ ይሁን።'),
  ('f040acc5-d1db-5659-a57a-941878ffe27a', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 14, 14, 'ብታምንበት ይቀድስሃል፤ እንደ ድንጋይ ዕንቅፋትም አያደናቅፍህም፤ እንደሚያድጥ ዓለትም አይሆንብህም፤ ሁለቱ የያዕቆብ ቤቶች ግን በኢየሩሳሌም በወጥመድና በአሽክላ ተይዘው ይኖራሉ።'),
  ('71e1d820-377d-5e0d-ab08-f58ae55ce10b', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 15, 15, 'ስለዚህም ከእነርሱ ብዙዎች በእርሱ ይሰናከላሉ፤ ይወድቁማል፤ ይሰበሩማል፤ ይጠመዱማል፤ ይያዙማል።”'),
  ('932af3a0-fb58-5134-a8f5-fc129818b82d', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 16, 16, 'እንዳይማሩአት ሕግን የሚያጠፉአት ሰዎች ያንጊዜ ይገለጣሉ።'),
  ('7f420f40-2e7e-5fc4-a930-48d7410f3334', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 17, 17, 'ከያዕቆብም ቤት ፊቱን የመለሰውን እግዚአብሔርን እጠብቃለሁ፥ እተማመንበትማለሁ።'),
  ('8fa0e1a5-0e11-54f5-a130-b7db366e43ca', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 18, 18, 'እነሆ፥ እኔና እግዚአብሔር የሰጠኝ ልጆች ለእስራኤል በጽዮን ተራራ ከሚኖረው ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ ምልክትና ተአምራት ነን።'),
  ('9eac970a-ebe5-5466-a707-92ee7f91ebee', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 19, 19, 'እነርሱም፥ “ድምፃቸውን ዝቅ አድርገው የሚናገሩትን መናፍስት ጠሪዎችንና ጠንቋዮችን ጠይቁ” ባሉአችሁ ጊዜ፥ ሕዝቡ ከአምላኩ መጠየቅ አይገባውምን? ወይስ ለሕያዋን ሲሉ ሙታንን ይጠይቃሉን?'),
  ('b2cac0dc-275c-5584-a36d-fafe49004689', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 20, 20, 'ነገሩ እንዲህ አይደለም ይሉ ዘንድ፥ ለእርሱም ግብር እንዳይሰጡ ሕግን ለርዳታ ሰጥቶአልና።'),
  ('5c0ce0b4-480b-5312-a67e-b826a7f7d5ca', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 21, 21, 'በዚህም በርግጥ ጽኑ ረኃብ ይመጣባችኋል፤ በተራባችሁም ጊዜ ትጨነቃላችሁ፤ በአለቆችና በመኳንንቱም ላይ ክፉ ትናገራላችሁ፤ ወደ ላይ ወደ ሰማይ ትመለከታላችሁ።'),
  ('e778b7bc-3537-5152-a742-1ab5c709ee5a', 'd184db3c-dfa3-5bdb-a3ee-5eb64cfd61dc', '3171a005-1bca-50e0-af7b-f2f5a18c465e', 22, 22, 'ወደ ታችም ወደ ምድር ትመለከታላችሁ፤ ድቅድቅ ጨለማንም ታያላችሁ፤ ታላቅ መከራንም ትቀበላላችሁ፤ ትጨነቃላችሁ፤ ትቸገራላችሁም፤ በፊታችሁም ጨለማ ይሆናል፤ አታዩምም፤ በመከራም ያለ ጊዜው እስኪደርስ አይድንም።'),
  ('2e8787f4-b6d9-53cb-a4ef-f836761b269b', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 1, 1, 'የዚህም ጊዜው እስከሚደርስ የተቸገረው ሁሉ አያመልጥም፤ በመጀመሪያው ዘመን የዛብሎንንና የንፍታሌምን ምድር አቃለለ፤ በኋለኛው ዘመን ግን በዮርዳኖስ ማዶ በባሕር መንገድ ያለውን የአሕዛብን ገሊላ ያከብራል።'),
  ('03e2d27c-defe-59bc-ac49-257c99100eb6', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 2, 2, 'በጨለማ የሄደ ሕዝብ ታላቅ ብርሃን አየ፤ በሞት ጥላና በጨለማ ሀገርም ለነበሩ ብርሃን ወጣላቸው።'),
  ('b80e47d8-9164-5a25-abb9-f9bc87791a9d', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 3, 3, 'ብዙ ሕዝብን በደስታ አወረድህ፤ በመከር ደስ እንደሚላቸው፥ ምርኮንም እንደሚካፈሉ በፊትህ ደስ ይላቸዋል።'),
  ('e328e7dd-eb87-598d-a1bb-53bc7caebb23', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 4, 4, 'በምድያም ጊዜ እንደ ሆነ በላያቸው የነበረው ቀንበር ተነሥቶአልና፥ በጫንቃቸው የነበረውንም፥ የአስጨናቂዎችንም በትር መልሶአልና።'),
  ('5dc407a0-79b1-5e01-abf3-df7b93d7380a', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 5, 5, 'በደም የተለወሰ ልብስ በእሳት ከሚቃጠል በቀር ለምንም አይጠቅምም።'),
  ('1ded2a3a-532c-5b30-a1c6-75e5d6a5b9fd', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 6, 6, 'ሕፃን ተወልዶልናልና፥ ወንድ ልጅም ተሰጥቶናልና፤ አለቅነትም በጫንቃው ላይ ይሆናል፤ ስሙም ድንቅ መካር፥ ኀያል አምላክ፥ የዘለዓለም አባት፥ የሰላም አለቃ ተብሎ ይጠራል፤'),
  ('5076e2c6-cc86-567f-aaf6-b8ed4251e570', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 7, 7, 'ለአለቆች ሰላምን ለእርሱም ሕይወትን አመጣለሁና፤ ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ በፍርድና በጽድቅ ያጸናውና ይደግፈው ዘንድ ግዛቱ ታላቅ ይሆናል፤ በዳዊት ዙፋን መንግሥቱ ትጸናለች፤ ለሰላሙም ፍጻሜ የለውም። የሠራዊት ጌታ የእግዚአብሔር ቅንዐት ይህን ያደርጋል።'),
  ('e14d01b8-02ab-5f2c-a115-5826a4e71a40', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 8, 8, 'ጌታ በያዕቆብ ላይ ሞትን ላከ፤ በእስራኤልም ላይ ወደቀ።'),
  ('735d8c8e-6651-52e8-aa57-1582cad9d71b', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 9, 9, 'የኤፍሬም ሕዝብ ሁሉና በሰማርያ የሚኖሩ ያውቃሉ፤ በትዕቢትና በልብ ኵራትም እንዲህ ይላሉ፦'),
  ('b5648231-abf7-5d65-a107-c718f19e370c', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 10, 10, '“ጡቡ ወደቀ፤ ነገር ግን ኑ፥ ድንጋይ እንውቀር፤ ሾላው ነቀዘ፤ ነገር ግን ፅድን እንቍረጥ፤ ለራሳችንም ግንብን እንሥራ።”'),
  ('fc53a032-95b6-5165-a373-c6cb52f81f9b', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 11, 11, 'ስለዚህ እግዚአብሔር በጽዮን ተራራ ላይ እርሱን በመቃወም የሚነሡትን ይበትናቸዋል።'),
  ('1453edd0-322a-5981-a299-42237d08b1f3', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 12, 12, 'ጠላቶቹን ሶርያውያንንም ከምሥራቅ፥ አረማውያንንም ከምዕራብ ያንቀሳቅስበታል፤ እስራኤልንም በተከፈተ አፍ ይበሉታል። በዚህም ሁሉ እንኳ ቍጣው አልተመለሰችም፤ ነገር ግን እጁ ገና ተዘርግታ ትኖራለች።'),
  ('aeb08964-67f6-5211-a937-439b2839d937', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 13, 13, 'ሕዝቡ ግን እስከተቀሠፉ ድረስ አልተመለሱም፤ የሠራዊትንም ጌታ እግዚአብሔርን አልፈለጉም።'),
  ('edb51878-2bbe-54b3-a9f1-6c79e3892f5f', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 14, 14, 'ስለዚህ እግዚአብሔር ራስንና ጅራትን፥ ታላቁንና ታናሹን በአንድ ቀን ከእስራኤል ይቈርጣል።'),
  ('3fd6bb58-ae69-5182-ac91-ba736ba420f9', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 15, 15, 'ሽማግሌውና ለፊት የሚያደላው እርሱ ራስ ነው፤ ዐመፅንም የሚያስተምር ነቢይ እርሱ ጅራት ነው።'),
  ('00455aed-178d-5c8b-aae7-54ef06ab83a4', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 16, 16, 'ይህን ሕዝብ የሚያመሰግኑ ያስቱአቸዋል፤ ይበሉአቸውም ዘንድ ያስቱአቸዋል፤'),
  ('bc55b7fc-c2e7-5c8c-a04e-f40a99dc13b7', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 17, 17, 'ሰው ሁሉ ክፉና በደለኛ ነውና፥ አፍም ሁሉ ዐመፅን ይናገራልና፥ ስለዚህ ጌታ በጐልማሶቻቸው ደስ አይለውም፤ ለሙት ልጆቻቸውና ለመበለቶቻቸውም አይራራም። በዚህ ሁሉ እንኳ ቍጣው አልተመለሰችም፤ ነገር ግን እጁ ገና ተዘርግታ ትኖራለች።'),
  ('0b781d01-fb2b-5636-adc4-61e75d8be79b', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 18, 18, 'ኀጢአት እንደ እሳት ይነድዳል፤ እሳት እንደ በላችው ደረቅ ሣር ይቃጠላል፤ እንደ ዱር ሣርም ይቃጠላል፤ በተራራዎች ዙሪያ ያለው ሁሉ አብሮ ይቃጠላል።'),
  ('7f71425b-ba17-507d-af97-b9355a8f212b', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 19, 19, 'በእግዚአብሔር ቍጣ ምድር ሁሉ ትቃጠላለች፤ ሕዝቡም እሳት እንደሚበላው እንጨት ሆኖአል፤ ሰውም ለወንድሙ አይራራም።'),
  ('9481c37d-6a15-5f4a-a1b0-7b7eaa262a43', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 20, 20, 'ነገር ግን ሰው ወደ ቀኙ ይመለሳል፤ ይራባልና፤ በግራም በኩል ይበላል፤ አይጠግብምም፤'),
  ('af97d283-762e-56db-a7da-e1e93f0ff527', '0f9dfa26-8ee9-5241-a8f6-f465c38d7fd8', '31ab6d2b-9081-5199-a503-cc9c563e790b', 21, 21, 'እያንዳንዱም የክንዱን ሥጋ ይበላል፤ ምናሴ ኤፍሬምን፥ ኤፍሬምም ምናሴን ይበላል፤ እነርሱ በአንድነት የይሁዳ ጠላቶች ይሆናሉና። በዚህም ሁሉ እንኳ ቍጣው አልተመለሰችም፤ ነገር ግን እጁ ገና ተዘርግታ ትኖራለች።'),
  ('83ba4864-8928-516e-a2bd-87163adc9934', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 1, 1, 'ክፉንም ጽሕፈት ለሚጽፉ ወዮላቸው!'),
  ('5a6604cf-8b45-5a52-a15b-e836bb84599d', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 2, 2, 'መበለቶች ቅሚያቸው እንዲሆኑ፥ የሙት ልጆችንም ብዝበዛቸው እንዲያደርጉ፥ የድሃውን ፍርድ ያጣምሙ ዘንድ፥ የችግረኛውንም ሕዝቤን ፍርድ ያጐድሉ ዘንድ የግፍን ትእዛዛት ለሚያዝዙ ወዮላቸው!'),
  ('ff7508f9-44af-5824-a3fc-46032628b97e', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 3, 3, 'በተጐበኛችሁበት ቀን፥ ምን ታደርጉ ይሆን? መከራ ከሩቅ ይመጣባችኋልና፥ ለረድኤትስ ወደ ማን ትሸሻላችሁ?'),
  ('8f3ded49-6c97-50ef-ac1c-d81f2dbe6fb2', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 4, 4, 'በሐሣር እንዳትወድቁ፥ ክብራችሁን ወዴት ትተዉታላችሁ? በዚህም ሁሉ እንኳ ቍጣው አልተመለሰችም፤ ነገር ግን እጁ ገና ተዘርግታ ትኖራለች።'),
  ('7b369a5d-e343-5ad1-a1ef-5dd9a3f2e67c', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 5, 5, 'ለቍጣዬ በትር ለሆኑ፥ ለመዓቴም ጨንገር በእጃቸው ላለ ለአሦራውያን ወዮላቸው!'),
  ('7a2185c5-d546-5477-a14c-42977dbd89d4', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 6, 6, 'ቍጣዬን በኀጢአተኛ ሕዝብ ላይ እልካለሁ፤ ይማርኳቸውና ይበዘብዙአቸው ዘንድ፥ ከተሞችንም ይረግጡአቸውና እንደ ትቢያ ያደርጓቸው ዘንድ ሕዝቤን አዝዛለሁ።'),
  ('89bff5a9-9546-5c18-ab34-ecdd128903ea', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 7, 7, 'እርሱ በልቡ እንዲህ አይመስለውም፤ እንዲህም አያስብም፤ ነገር ግን ማጥፋት፥ ጥቂት ያይደሉትንም አሕዛብ መቍረጥ በልቡ አለ።'),
  ('5e1e1117-0290-5acc-a107-bea2739757b3', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 8, 8, '“አንተ ብቻህን አለቃ ነህን?” ቢሉትም፥ የሔማትን መንደር ወሰድሁ ይላል።'),
  ('c05eab15-edeb-5e36-aafb-1b6a8f5aca82', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 9, 9, 'እንደ ሔማት አርፋድ፥ እንደ አርፋድ ሴፋሩሔም፥ እንደ ሴፋሩሔም ካሌና፥ እንደ ካሌናም ደማስቆ፥ እንደ ደማስቆም ሰማርያ አይደለችምን?'),
  ('1a64e489-b8fe-511a-ae97-8a1e1b81af4a', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 10, 10, 'ይሁዳንም እንዲሁ አደርጋታለሁ፤ በኢየሩሳሌምና በሰማርያ የሚያድን ጣዖት አለን?'),
  ('67c29d9d-0ccb-5fee-a271-4a256612f570', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 11, 11, 'በሰማርያና በጣዖቶችዋም እንዳደረግሁ፥ እንዲሁ በኢየሩሳሌምና በጣዖቶችዋ አደርጋለሁ።'),
  ('fd296129-431f-5e27-a8d4-83e564ef9e63', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 12, 12, 'ስለዚህ እንዲህ ይሆናል፤ ጌታ ሥራውን ሁሉ በጽዮን ተራራና በኢየሩሳሌም ላይ በፈጸመ ጊዜ የአሦርን ንጉሥ የኵሩ ልብን ፍሬ፥ የዐይኑንም ከፍታ ትምክሕት ይቀጣል።'),
  ('248d49bc-f5ec-5cd1-a14f-8f6a88c8d533', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 13, 13, 'እርሱ እንዲህ ብሎአልና፥ “በኀይሌ አደርጋለሁ፤ በማስተዋል ጥበቤም የአሕዛብን ድንበሮች አርቃለሁ፤ ሀብታቸውንም እዘርፋለሁ፤'),
  ('55c5c10a-1728-50f8-a4e1-c062a8181111', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 14, 14, 'የሚቀመጡባቸውንም ከተሞች አናውጣለሁ። በእጄም ዓለምን ሁሉ እንደ ወፍ ቤት እሰበስባለሁ፤ እንደ ተተወ እንቍላልም እወስዳቸዋለሁ፤ ከእኔም የሚያመልጥ የለም፤ የሚቃወመኝም የለም።'),
  ('6d782e8d-25d5-5394-a4ce-fa4f91b52b3f', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 15, 15, '“በውኑ መጥረቢያ በሚቈርጥበት ሰው ላይ ይነሣልን? ወይስ መጋዝ በሚስበው ሰው ላይ ይጓደዳልን? ይህም ዘንግ በሚመቱበት ላይ እንደ መነሣት፥ በትርም ዕንጨት አይደለሁም እንደ ማለት ነው።”'),
  ('ad40040b-943f-5593-abac-3f1ecc47e162', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 16, 16, 'ስለዚህም የሠራዊት ጌታ እግዚአብሔር በክብርህ ላይ ውርደትን፥ በጌጥህ ላይም የሚነድና የሚያቃጥል እሳትን ይሰድዳል።'),
  ('1b7332ae-ff2b-5b64-ad2a-5cbb1d9726b4', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 17, 17, 'የእስራኤልም ብርሃን እንደ እሳት ይሆናል፤ በሚነድድ እሳትም ይቀድሰዋል፤ ዛፉንም እንደ ሣር ያቃጥለዋል።'),
  ('2ba2a505-c0cd-5e9c-a32c-cdc32934048f', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 18, 18, 'ያንጊዜ ተራሮችና ኮረብቶች፥ ዛፎችም ይጠፋሉ። ነፍስና ሥጋንም ይበላል፤ የሚሸሽም ከሚነድድ የእሳት ነበልባል እንደሚሸሽ ይሆናል።'),
  ('762721f0-8106-5d9d-a176-94c19ea68d98', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'cf118c0b-51e6-5ca6-a48d-434a1578c623', 19, 19, 'የቀሩትም የዱር ዛፎች በቍጥር ጥቂት ይሆናሉ፤ ታናሽ ብላቴናም ይጽፋቸዋል።'),
  ('06ec41f5-31a0-57f3-a029-68f160f1134f', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 1, 20, 'በዚያም ጊዜ እንዲህ ይሆናል፤ የእስራኤል ቅሬታ ከያዕቆብም ቤት የዳኑት ከእንግዲህ ወዲህ በአቈሰሉአቸው ላይ አይደገፉም፤ ነገር ግን በእስራኤል ቅዱስ በእግዚአብሔር ላይ በእውነት ይደገፋሉ።'),
  ('480a65a9-897b-59df-a22d-d69c0e8811d8', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 2, 21, 'የያዕቆብም ቅሬታ በኀያሉ እግዚአብሔር ይጸናሉ።'),
  ('4964af2f-8597-5d94-a9e6-0d7c8b9aa761', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 3, 22, 'የእስራኤልም ሕዝብ ቍጥር እንደ ባሕር አሸዋ ቢሆን የቀሩት ይድናሉ።'),
  ('f605adca-2fa6-58a2-a3f0-919d983f49fc', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 4, 23, 'የሠራዊት ጌታ እግዚአብሔርም ያለቀና የተቈረጠ ነገርን በዓለም ሁሉ በእውነት ይፈጽማል።'),
  ('9b879a3c-3e09-57ab-a6b7-1dcb100df616', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 5, 24, 'ስለዚህ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “በጽዮን የምትኖር ሕዝቤ ሆይ፥ ከአሦር የተነሣ አትፍራ፤ በበትር ይመቱሃልና፥ የግብፅንም መንገድ ታይ ዘንድ መቅሠፍቴን አመጣብሃለሁና።'),
  ('a856a7a8-7d22-5cd7-a08b-2583fac88dc9', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 6, 25, 'ለጥቂት ጊዜ ቍጣዬ ይበርዳል፤ ነገር ግን መዓቴ በምክራቸው ላይ ይሆናል።”'),
  ('fb5bd2e8-13d0-558c-a644-f7934a08afb8', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 7, 26, 'እግዚአብሔርም ምድያምን በመከራው ቦታ እንደ መታው ጅራፍን ያነሣበታል፤ ቍጣውም በባሕሩ መንገድና በግብፅ መንገድ በኩል ይሆናል።'),
  ('367a1be6-e760-52e3-a973-cccf7dcc2d4f', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 8, 27, 'በዚያም ቀን ቀንበሩ ከጫንቃህ፥ ፍርሀቱም ከአንተ ላይ ይወርዳል፤ ቀንበሩም ከጫንቃህ ወርዶ ይሰበራል።'),
  ('3b145886-d587-53e7-a733-1598a21c436b', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 9, 28, 'ወደ አንጋይ ከተማ ይመጣል፤ በመጌዶን በኩል ያልፋል፤ በማክማስም ውስጥ ዕቃውን ያኖራል፤'),
  ('fabde84e-bc59-5cd5-a847-e20d9a0bcb2c', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 10, 29, 'በቆላ ያልፋል፤ ወደ አንጋይም በደረሰ ጊዜ ሬማትና የሳኦል ከተማ ገባዖን ይፈራሉ፤'),
  ('aef5ae74-8718-50ff-a22b-51f00d75fd42', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 11, 30, 'የጋሊም ልጅ ትሸሻለች፤ ላይሳም ትሰማለች፤ አናቶትም ትሰማለች።'),
  ('dc6b9c5f-2d98-5b41-ab3f-4ffdbac0402e', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 12, 31, 'መደቤናና በጌቤር የሚኖሩ ይደነግጣሉ።'),
  ('705f85b6-3837-58c0-ad63-d48627abb205', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 13, 32, 'ዛሬ በእጁ እንዲኖሩ በመንገዱ ለምኑ፤ የጽዮን ልጅ ተራራንና የኢየሩሳሌምን ኮረብቶች አጽኑ።'),
  ('47626138-d919-5958-a8e4-d29d1d194612', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 14, 33, 'እነሆ፥ የሠራዊት ጌታ እግዚአብሔር ክቡራንን በኀይል ያውካቸዋል፤ ታላላቆችንም በሐሣር ይቀጠቅጣቸዋል፤ ከፍ ያሉትም ይዋረዳሉ።'),
  ('45cd2c4b-6bef-5027-abcb-11127b4d4ef3', '26cd8ca4-f057-5bf9-a428-09699d96bf38', 'c674cec2-855e-50c6-a687-e29883a2659f', 15, 34, 'ታላላቆችም በሰይፍ ይወድቃሉ፤ ሊባኖስም ከረዣዥም ዛፎች ጋር ይወድቃል።'),
  ('98e3b06b-9566-50b8-a93b-48ea88afd0b1', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 1, 1, 'ከእሴይ ሥር በትር ትወጣለች፤ አበባም ከግንዱ ይወጣል።'),
  ('7c9eeac5-153e-5c95-a411-408ed0565ec1', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 2, 2, 'የእግዚአብሔር መንፈስ፥ የጥበብና የማስተዋል መንፈስ፥ የምክርና የኀይል መንፈስ፥ የዕውቀትና የእውነት መንፈስ ያርፍበታል።'),
  ('fce72a64-f01a-55c0-af64-b0e35b4b2632', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 3, 3, 'እግዚአብሔርን የመፍራት መንፈስ ይሞላበታል፤ በፍርድ አያዳላም፤ በነገርም አይከራከርም፤'),
  ('e7d01771-681b-5f52-a1b9-deb947e805b6', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 4, 4, 'ነገር ግን ለድሆች በጽድቅ ይፈርዳል፤ ለምድርም የዋሆች በቅንነት ይበይናል፤ በአፉም ቃል ምድርን ይመታል፤ በከንፈሩም እስትንፋስ ኀጢአተኛውን ያጠፋዋል።'),
  ('34762061-5e07-56f1-a3cf-03a1395190cf', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 5, 5, 'ወገቡን በጽድቅ ይታጠቃል፤ እውነትንም በጎኑ ይጐናጸፋል።'),
  ('69052904-664d-5dfa-a457-e3a1536d6489', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 6, 6, 'ተኵላ ከበግ ጠቦት ጋር ይሰማራል፤ ነብርም ከፍየል ጠቦት ጋር ይተኛል፤ ጥጃና በሬ የአንበሳ ደቦልም በአንድነት ይሰማራሉ፤ ታናሽም ልጅ ይመራቸዋል።'),
  ('5e2fe887-aa66-5710-a5f3-bb5f28ac3d13', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 7, 7, 'ላምና ድብ አብረው ይሰማራሉ፤ ግልገሎቻቸውም በአንድነት ያድጋሉ፤ አንበሳም እንደ በሬ ገለባ ይበላል።'),
  ('5f047330-25e5-52ee-a1bb-a48e258dbf65', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 8, 8, 'የሚጠባውም ሕፃን በእባብ ጕድጓድና በእፉኝት ቤት ላይ እጁን ይጭናል።'),
  ('1e12f56b-831e-5173-ab74-3fe40af586d8', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', '9d7942c0-e7d4-5534-a3e6-2532033edfba', 9, 9, 'እነርሱም አይጐዱትም፤ በተቀደሰው ተራራዬ ሁሉ ላይ ማንንም አይጐዱም፤ አያጠፉምም፤ ብዙ ውኃ ባሕርን እንደሚሸፍን ምድር እግዚአብሔርን በማወቅ ትሞላለችና።'),
  ('39f2b161-a7f3-5927-a8a9-dea3ba0a587c', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 1, 10, 'በዚያም ቀን የእሴይ ሥር ይቆማል፤ የተሾመውም የአሕዛብ አለቃ ይሆናል፤ አሕዛብም በእርሱ ተስፋ ያደርጋሉ፤ ማረፊያውም የተከበረ ይሆናል።'),
  ('44eb9f06-04f8-527c-a815-db881442904e', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 2, 11, 'በዚያም ቀን እንዲህ ይሆናል፤ ከአሦርና ከግብፅ፥ ከባቢሎንና ከኢትዮጵያ፥ ከኤላሜጤን፥ ከምሥራቅና ከምዕራብ ለቀሩት ለሕዝቡ ቅሬታ ይቀና ዘንድ እግዚአብሔር እንደ ገና እጁን ይገልጣል።'),
  ('c4f2ce1c-8bf4-50cc-af74-8ca432317987', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 3, 12, 'ለአሕዛብም ምልክትን ያቆማል፤ ከእስራኤልም የቀሩትን ይሰበስባል፤ ከይሁዳም የተበተኑትን ከአራቱ የምድር ማዕዘኖች ያከማቻል።'),
  ('777341bd-7e52-54af-aeb1-61d2615b3137', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 4, 13, 'የኤፍሬምም ቅናት ይሻራል፤ የይሁዳም ጠላቶች ይጠፋሉ፤ ኤፍሬምም በይሁዳ አይቀናም፤ ይሁዳም ኤፍሬምን አያስጨንቅም።'),
  ('c667f066-7073-5463-a757-92a384242b6b', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 5, 14, 'በባሕርም በኩል በፍልስጥኤማውያን መርከቦች ላይ እየበረሩ ይወርዳሉ፤ የምሥራቅ ሰዎችንና ኤዶምያስን በአንድነት ይዘርፋሉ፤ በሞዓብ ላይ ቀድመው እጃቸውን ይዘረጋሉ፤ የአሞንም ልጆች ቀድመው ለእነርሱ ይታዘዛሉ።'),
  ('015e00ca-7ceb-5c36-a0ca-3d9561f67b92', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 6, 15, 'እግዚአብሔርም የግብፅን ባሕር ያደርቃል፤ በኀይለኛም ነፋስ እጁን በወንዙ ላይ ያነሣል፤ ሰባት ፈሳሾችንም ይመታል፤ ሰዎችም በጫማቸው እንዲሻገሩ ያደርጋቸዋል።'),
  ('abbbcf91-ba2f-53a1-a860-104487ea5d32', '3bcdc7df-724b-58e4-a551-2e29fdc9fb68', 'd2a52fbb-0856-52fc-a69d-21d6794dbaad', 7, 16, 'ከግብፅም በወጣ ጊዜ ለእስራኤል እንደ ነበረ፥ በአሦር ለቀረው ለሕዝቡ ጎዳና ይሆናል።'),
  ('542a0d3b-cf93-530d-ade6-c5774ce0583f', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 1, 1, 'በዚያም ቀን እንዲህ ትላለህ፥ “አቤቱ፥ ተቈጥተኸኛልና፥ ቍጣህንም ከእኔ መልሰሃልና፥ ዳግመኛም ይቅር ብለኸኛልና አመሰግንሃለሁ።'),
  ('41d9105d-1b6e-5c09-a6b6-eccf678dff8c', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 2, 2, 'እነሆ፥ አምላኬ መድኀኒቴ ነው፤ ጌታ እግዚአብሔር ክብሬና ዝማሬዬ ነው፤ መድኀኒቴም ሆኖአልና በእርሱ ታምኜአለሁ፤ አልፈራምም።”'),
  ('d30cd6c8-1767-5c12-a7ae-c4b187bd615e', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 3, 3, 'ውኃውንም ከሕይወት ምንጮች በደስታ ትቀዳላችሁ።'),
  ('1be850b7-923a-570c-acab-845f924eee9a', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 4, 4, 'በዚያም ቀን እንዲህ ትላላችሁ፥ “እግዚአብሔርን አመስግኑ፤ ስሙንም ጥሩ፤ በአሕዛብ መካከል ክብሩን አስታውቁ፤ ስሙ ከፍ ያለ እንደ ሆነ አስታውሱ።'),
  ('4a5255f1-af85-556b-a6d2-5b09ab4583ae', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 5, 5, 'ታላቅ ሥራ ሠርቶአልና ለእግዚአብሔር ስም ዘምሩ፤ ይህንም በምድር ሁሉ ላይ አስታውቁ።'),
  ('914fc97c-e461-5b3e-a743-fdcbb14d271a', 'f1cb2282-f9d5-506b-a82a-b32b8b2f4e44', 'c38b34d6-b315-52e4-ae82-9fe0604498c2', 6, 6, 'አንቺ የጽዮን ልጅ ሆይ፥ ደስ ይበልሽ፤ ሐሤትም አድርጊ፤ የእስራኤል ቅዱስ በመካከልሽ ከፍ ከፍ ብሎአልና።”'),
  ('7400ac77-0b62-5743-a4ac-08836af0ae8a', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 1, 1, 'የአሞጽ ልጅ ኢሳይያስ በባቢሎን ላይ ያየው ራእይ።'),
  ('bdad00c9-6307-5c20-a3da-27f2cd02e73d', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 2, 2, 'ምድረ በዳ በሆነ ተራራ ላይ ምልክትን አቁሙ፤ ድምፃችሁንም ከፍ አድርጉባቸው፤ አለቆች በእጅ ጥቀሱ። በሮችንም ክፈቱ።'),
  ('855b881f-aa9a-5226-a67e-b4e0dbcd1f00', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 3, 3, 'እኔ አዝዤ ቅዱሳኔን አመጣቸዋለሁ፤ ኀያላኔንም አመጣቸዋለሁ፤ ደስ እያላቸውም ይመጣሉ፤ ቍጣዬንም ይፈጽማሉ፤ ያዋርዱአቸዋልም።'),
  ('bf888e02-901e-5f83-ae40-e0970405748e', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 4, 4, 'በተራሮች ላይ እንደ ታላቅ ሕዝብ ድምፅ የሆነ የብዙ ሰው ድምፅ አለ። የተሰበሰቡ ነገሥታትና የአሕዛብ ድምፅም አለ። የሠራዊት ጌታ እግዚአብሔር ተዋጊዎች አሕዛብ ይመጡ ዘንድ አዘዘ።'),
  ('45294acf-7ca3-5526-ad21-9d9412cb0d9f', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 5, 5, 'እግዚአብሔርና የቍጣው ሠራዊት ዓለምን ያጠፉአት ዘንድ ከሩቅ ሀገር ከሰማይ ዳርቻ ይመጣሉ።'),
  ('c403bc75-de23-58c1-ad46-94c5d7280bc1', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 6, 6, 'የእግዚአብሔር ቀን ቀርቦአልና አልቅሱ፤ ጥፋትም ከእግዚአብሔር ዘንድ ይመጣል።'),
  ('8783abac-95e7-526e-a964-dd5500562ead', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 7, 7, 'ስለዚህ እጅ ሁሉ ትዝላለች፤ ሰውም ሁሉ ይደነግጣል፤'),
  ('4ccff440-3620-5d32-a29b-34a223658c97', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 8, 8, 'ሽማግሎች ይደነግጣሉ፤ እንደምትወልድ ሴትም ምጥ ይይዛቸዋል፤ እርስ በርሳቸውም ይገዳደላሉ፤ ይደነቃሉ፤ ፊታቸውም እንደ እሳት ይንበለበላል።'),
  ('d18fd6c7-1294-538c-aae5-6261284ad16e', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 9, 9, 'እነሆ፥ ምድሪቱን ባድማ ሊያደርግ፥ ኀጢአተኞችዋንም ከእርስዋ ዘንድ ሊያጠፋ በመዓትና በጽኑ ቍጣ ተሞልቶ የእግዚአብሔር ቀን ይመጣል።'),
  ('0976f572-55c3-5490-ad44-9b7157f235bf', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 10, 10, 'የሰማይም ከዋክብትና ኦሪዎን፥ የሰማይ ሠራዊትም ሁሉ ብርሃናቸውን አይሰጡም፤ ፀሐይም በወጣች ጊዜ ትጨልማለች፤ ጨረቃም በብርሃኑ አያበራም።'),
  ('2cbcff1a-70eb-5bbe-aad3-3423e74c9573', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 11, 11, 'በዓለም ሁሉ ላይ ክፋትን አዝዛለሁ፤ የኀጢአተኞችንም ኀጢአት እጐበኛለሁ፤ የትዕቢተኞችንም ኵራት እሽራለሁ፤ የጨካኞቹንም ኵራት አዋርዳለሁ።'),
  ('a6e01015-52b1-55ee-a32e-943bc517dad9', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 12, 12, 'የተረፉትም ከጥሩ ወርቅ ይልቅ የከበሩ ይሆናሉ፤ ሰውም ከሰንፔር ዕንቍ ይልቅ የከበረ ይሆናል።'),
  ('d3cf6893-f265-5721-a739-4125bb39782b', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 13, 13, 'ስለዚህ በሠራዊት ጌታ በእግዚአብሔር መዓት በጽኑ ቍጣው ቀንም ሰማያት ይንቀጠቀጣሉ፤ ምድርም ከመሠረቷ ትናወጣለች።'),
  ('4febc5aa-6f73-5fbc-a694-a0f97cb6397e', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 14, 14, 'የተረፉትም ሁሉ እንደ ተባረረ ሚዳቋ፥ እንደ ባዘነ በግም ይሆናሉ። የሚሰበስባቸውም የለም፤ እንዲሁም ሰው ሁሉ ወደ ወገኑ ይመለሳል፤ ሁሉም ሰው ወደ ሀገሩ ይሸሻል።'),
  ('32a90286-7b95-5d58-ae5f-9608124d67fb', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 15, 15, 'የተበተኑት ሁሉ ይሞታሉ፤ የተሰበሰቡትም ሁሉ በጦር ይወድቃሉ።'),
  ('c218d94c-4e6a-54b2-ad61-8d8236d1f9cc', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 16, 16, 'ሕፃኖቻቸውንም በፊታቸው ይጨፈጭፋሉ፤ ቤቶቻቸውንም ይበዘብዛሉ፤ ሚስቶቻቸውንም ያስነውራሉ።'),
  ('e1fdb0fb-54ab-5d02-ac34-2a60382d57e9', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 17, 17, 'እነሆ፥ ብር የማይሹትን፥ ወርቅም የማያምራቸውን ሜዶናውያንን በእናንተ ላይ አስነሣለሁ።'),
  ('383fbad9-d940-5092-a37f-8d46aac363f3', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 18, 18, 'ፍላጾቻቸውም ጐበዞችን ይጨፈጭፋሉ፤ ሕፃኖቻችሁንም አይምሩም፤ ዐይኖቻቸውም ለልጆቻችሁ አይራሩም።'),
  ('94290df5-c02d-5449-a4aa-9bb0466bb918', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 19, 19, 'የመንግሥታት ክብር፥ የከለዳውያንም የትዕቢታቸው ትምክሕት የሆነች ባቢሎንም እግዚአብሔር እንደ ገለበጣቸው እንደ ሰዶምና እንደ ገሞራ ትሆናለች።'),
  ('f68778c7-4063-570a-a49e-3d05fdb4cd4e', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 20, 20, 'ለዘለዓለም የሚቀመጥባት አይገኝም፤ ከትውልድም እስከ ትውልድ ድረስ ሰው አይኖርባትም፤ ዓረባውያንም በእርሷ አያልፉም፤ እረኞችም በውስጥዋ አያርፉም።'),
  ('f7398db0-f667-5b3e-a4ea-cafb86912ccc', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 21, 21, 'በዚያም የምድረ በዳ አራዊት ያርፋሉ፤ ጕጕቶችም በቤቶቻቸው ይሞላሉ፤ ሰጎኖችም በዚያ ይኖራሉ፤ በዚያም አጋንንት ይዘፍናሉ።'),
  ('2a691553-2dcd-5646-a76d-49a1f69a125c', 'd401d396-1a96-5eb3-a40b-48c9b31f2447', '0317e243-bb82-5057-a772-73ac669e6c51', 22, 22, 'ተኵላዎችም በዚያ ያድራሉ፤ ቀበሮዎችም በሚያማምሩ አዳራሾቻቸው ይዋለዳሉ፤ ይህም ሁሉ ፈጥኖ ይሆናል፤ አይዘገይምም።'),
  ('80bdd606-b4bd-5d3b-a7a7-06bab562d29c', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 1, 1, 'እግዚአብሔርም ያዕቆብን ይምረዋል፤ እስራኤልንም ደግሞ ይመርጠዋል፤ በሀገራቸውም ያርፋሉ፤ መጻተኞችም ከእነርሱ ጋር አንድ ይሆናሉ፤ ከያዕቆብም ቤት ጋር ይጨመራሉ።'),
  ('bf32e479-74e5-5490-a6f9-736227bf970f', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 2, 2, 'አሕዛብም ይዘው ወደ ስፍራቸው ያመጡአቸዋል፤ የእስራኤልም ወገኖች ይካፈሏቸዋል፤ በዚያም ሀገር ይበዛሉ፤ በዚያም ወንዶች ባሮችና ሴቶች ባሮች ይሆናሉ። ማርከው የወሰዷቸውም ለእነርሱ ምርኮኞች ይሆናሉ፤ የገዙአቸውም ይገዙላቸዋል።'),
  ('5b7a72c6-7ec7-5fe3-a64a-635544ff4007', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 3, 3, 'በዚያም ቀን እንዲህ ይሆናል፤ እግዚአብሔር ከኀዘንህና ከመከራህ፥ ከተገዛህለትም ከጽኑ ባርነት ያሳርፍሃል።'),
  ('16435fb1-bcf2-594c-a647-a26ca45d5c3f', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 4, 4, 'ይህንም ሙሾ በባቢሎን ንጉሥ ላይ ታነሣለህ፤ እንዲህም ትላለህ፥ “አስጨናቂ እንዴት ዐረፈ! አስገባሪም እንዴት ጸጥ አለ!'),
  ('3123db2d-3ee5-5a1f-afc9-c84293cd6585', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 5, 5, 'እግዚአብሔር የኀጢአተኞችን ቀንበርና የአለቆችን ቀንበር ሰብሮአልና።'),
  ('c8346c47-5cc9-5c0a-aa75-4deecf27e67b', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 6, 6, 'እግዚአብሔር በቍጣው መቅሠፍት አሕዛብን ገርፎአቸዋልና፥ ከቍጣውም መቅሠፍት አልራራላቸውምና።'),
  ('e62d44de-99f2-58f1-ae93-139b9977f8e8', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 7, 7, 'ምድርም ሁሉ ዐርፋ በጸጥታ ተቀምጣለች፤ እልልም ብላለች።'),
  ('96862f2e-b137-5d8e-a75f-7930139bb100', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 8, 8, 'የሊባኖስ ዛፎች፦ አንተ ከተዋረድህ ጀምሮ ማንም ይቈርጠን ዘንድ አልወጣብንም ብለው በአንተ ደስ አላቸው።'),
  ('597ab629-fc95-57cb-a202-622c9d1ca5bd', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 9, 9, '“ሲኦልም በመምጣትህ ልትገናኝህ በታች ታወከች፤ የአሕዛብን ነገሥታት ሁሉ ከዙፋናቸው ያስነሡ፥ ምድርን የገዙአት አርበኞች ሁሉ በአንድነት በአንተ ላይ ተነሡ።'),
  ('1bbb3fcb-227f-561d-aaee-797942e7d6ee', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 10, 10, 'እነዚህ ሁሉ፦ አንተ ደግሞ እንደ እኛ ተይዘሃል፤ እንደ እኛም ተቈጥረሃል።'),
  ('9d3145ce-a828-5201-aa80-976c01f1f889', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 11, 11, 'ከክብርህ ወደ ሲኦል ወደቅህ፤ በበታችህም ብል ተነጥፎአል፤ ትልም መደረቢያህ ሆኖአል” ብለው ይመልሱልሃል።'),
  ('255c9aad-35b5-546f-ad6c-79d0d439b7dc', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 12, 12, '“አንተ በንጋት የሚወጣ የአጥቢያ ኮከብ ሆይ፥ እንዴት ከሰማይ ወደቅህ! ወደ አሕዛብም መልእክትን የላክህ አንተ ሆይ፥ እንዴት እስከ ምድር ድረስ ተቀጠቀጥህ!'),
  ('fed26f47-92a4-5e64-ad65-ad242e3b526b', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 13, 13, 'አንተም በልብህ፦ ወደ ሰማይ ዐርጋለሁ፤ ዙፋኔንም ከሰማይ ከዋክብት በላይ ከፍ ከፍ አደርጋለሁ፤ በሰሜንም ዳርቻ በረዣዥም ተራሮች ላይ እቀመጣለሁ፤'),
  ('d5e40ec9-88a4-53ce-a439-784a4c837404', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 14, 14, 'ከደመናዎች ከፍታ በላይ ዐርጋለሁ፤ በልዑልም እመሰላለሁ አልህ።'),
  ('b3d2f43b-8854-5d40-aa20-e15c53bcabbb', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 15, 15, 'ዛሬ ግን ወደ ሲኦል ትወድቃለህ፤ ወደ ምድር ጥልቅም ትወርዳለህ።'),
  ('64b3ea03-aa3f-500c-a2b2-90872d5f81b2', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 16, 16, 'የሚመለከቱህም ይደነቃሉ፤ እንዲህም ይላሉ፦ በውኑ ምድርን ያንቀጠቀጠ፥ መንግሥታትንም ያናወጠ፥'),
  ('7ef6260e-29e9-5353-a1e9-84a33d628ef1', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 17, 17, 'ዓለሙን ሁሉ ባድማ ያደረገ፥ ከተሞችንም ያፈረሰ፥ ምርኮኞቹንም ወደ ቤታቸው ያልሰደደ ሰው ይህ ነውን?'),
  ('4faadea6-308a-5fd3-a395-9aba12ab2c42', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 18, 18, '“የአሕዛብ ነገሥታት ሁሉ በየቤታቸው በክብር አንቀላፍተዋል።'),
  ('ba19f80c-8f5c-5968-ab84-afd92c4f59b5', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 19, 19, 'አንተ ግን በጦር ተወግተው ወደ መቃብር ከሚወርዱ ብዙ ሙታን ጋር እንደ ረከሰ ሬሳ በተራሮች ላይ ትጣላለህ።'),
  ('50b8d428-d5f6-5b98-ad71-089c661f8229', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 20, 20, 'ንጹሕ እንዳልሆነና በደም እንደ ረከሰ ልብስ አንተም ንጹሕ አይደለህም። ምድሬን አጥፍተሃልና፥ ሕዝቤንም ገድለሃልና ክፉ ዘር አንተ እንግዲህ ለዘለዓለም አትኖርም።'),
  ('8e8892d1-3db2-5df0-a04d-26bdc2368673', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 21, 21, 'እንዳይነሡም፥ ምድርንም እንዳይወርሱ፥ የዓለሙንም ፊት በጦርነት እንዳይሞሉ በአባቶቻቸው በደል ይገድሉአቸው ዘንድ ልጆችህን አዘጋጅ።”'),
  ('3761ed7c-682c-5c7b-ac06-8779013fe480', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 22, 22, '“በእነርሱ ላይ እነሣለሁ” ይላል የሠራዊት ጌታ እግዚአብሔር፤ “ስምንና ቅሬታን፥ ዘርንና ትውልድንም አጠፋለሁ” ይላል እግዚአብሔር።'),
  ('8d28153b-939e-5895-a332-39f0991a4b23', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '77bae1f5-8416-5314-aabf-51ace188ae9a', 23, 23, '“ባቢሎንን የወፎች መኖሪያ አደርጋታለሁ፤ እንደ ኢምንትም ትሆናለች፤ በጥፋትም እንደ ረግረግ ጭቃ አደርጋታለሁ” ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('11bb55a7-66d6-5d99-a35f-6c3cea143884', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '8bb7a48b-6ecc-5e91-a599-5c6394d73ef1', 1, 24, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ብሎ ምሎአል፥ “እንደ ተናገርሁ በእርግጥ ይሆናል፤ እንደ መከርሁም እንዲሁ ይጸናል።'),
  ('98fb0eb0-8d9f-54a7-a161-c39b3b2af99c', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '8bb7a48b-6ecc-5e91-a599-5c6394d73ef1', 2, 25, 'አሦርን በምድሬ ላይ እሰብረዋለሁ፤ በተራራዬም ላይ እረግጠዋለሁ፤ ቀንበሩም ከእነርሱ ላይ ይነሣል፤ ሸክሙም ከጫንቃቸው ላይ ይወገዳል።”'),
  ('096336b6-1cda-5003-a64a-2e35a8d45d2e', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '8bb7a48b-6ecc-5e91-a599-5c6394d73ef1', 3, 26, 'በምድር ሁሉ ላይ እግዚአብሔር ያሰበው ዐሳብ ይህ ነው፤ በአሕዛብም ሁሉ የተዘረጋች እጅ ይህች ናት።'),
  ('b5a635c8-acbf-57bd-a2ed-ecc477cc7c57', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', '8bb7a48b-6ecc-5e91-a599-5c6394d73ef1', 4, 27, 'ቅዱስ እግዚአብሔር ይህን መክሮአል፤ የእግዚአብሔርን ምክር የሚመልስ ማን ነው? የተዘረጋች እጁንስ የሚመልሳት ማን ነው?'),
  ('9dc2b843-67bc-5d8b-a8bb-6f50d0277933', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', 'e3d96225-83dd-5e46-acf9-6c227314417c', 1, 28, 'ንጉሡ አካዝ በሞተበት ዓመት ይህ ነገር ሆነ።'),
  ('7b4f958b-5a99-5fde-aaf2-0a61f5d0c853', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', 'e3d96225-83dd-5e46-acf9-6c227314417c', 2, 29, 'ፍልስጥኤም ሆይ፥ ከእባቡ ዘር እፉኝት ይወጣልና፥ ፍሬውም የሚበርርና እሳት የሚመስል እባብ ይሆናልና፥ የኀይላችሁ ቀንበር ተሰብሮአልና ሁላችሁም ደስ አይበላችሁ።'),
  ('00e741f4-22aa-584e-a96c-ef11ca3b9b8b', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', 'e3d96225-83dd-5e46-acf9-6c227314417c', 3, 30, 'ድሆችም በውስጣችሁ ይሰማራሉ፤ ድሆች ሰዎችም በሰላም ያርፋሉ፤ ዘራችሁንም ረኃብ ያጠፋቸዋል፤ ከእናንተም የቀሩት ያልቃሉ።'),
  ('e477eb5d-a014-5a35-a9e3-a8184d68f411', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', 'e3d96225-83dd-5e46-acf9-6c227314417c', 4, 31, 'እናንተ የከተሞች በሮች ሆይ፥ ወዮ በሉ፤ እናንተም ከተሞች ሆይ፥ ደንግጡ፥ ጩኹም፤ ፍልስጥኤማውያን ሆይ፥ ሁላችሁም ቀልጣችኋል፤ ጢስ ከሰሜን ይወጣልና፥ እንግዲህም አትኖሩምና።'),
  ('89868884-4685-5100-a471-27065c6f9d1c', '8afbfdc4-0e08-5dd8-abdb-29c0beb0693a', 'e3d96225-83dd-5e46-acf9-6c227314417c', 5, 32, 'የአሕዛብ ነገሥታት ምን ይመልሳሉ? እግዚአብሔር ጽዮንን መሠረታት፤ ትሑታን የሆኑትንም ሕዝብ አዳናቸው።'),
  ('c84a962f-38e2-5e35-a735-dccfe31ab008', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 1, 1, 'ስለ ሞዓብ የተነገረ ቃል። ሞዓብ በሌሊት ትጠፋለች፤ የሞዓብም ምሽግ በሌሊት ይፈርሳል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f5baea2a-0c4f-5796-a0af-04c945f6798c', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 2, 2, 'ለራሳችሁ እዘኑ፤ ጣዖታችሁና መሠዊያችሁ ያሉባት ዲቦን ትጠፋለችና፤ ወደዚያም ወጥታችሁ በሞዓብ ናባው አልቅሱ፤ ወዮም በሉ፤ ራስ ሁሉ በራ ይሆናል፤ ክንድም ሁሉ ይቈረጣል።'),
  ('b3df3f93-d2aa-5dbc-ab65-c315c9140bf4', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 3, 3, 'በየመንገድዋ ማቅ ታጠቁ፤ በየሰገነቶችዋም አልቅሱ፤ በየአደባባዮችዋም እንባን እጅግ እያፈሰሳችሁ ወዮ በሉ።'),
  ('1a0192b6-8c8d-5594-a130-818acdaf9779', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 4, 4, 'ሐሴቦንና ኤልያሊ ጮኹ፤ ድምፃቸውም እስከ ያሳ ድረስ ይሰማል፤ ስለዚህ የሞዓብ ወገብ ይታመማል።'),
  ('0cdd9b8f-a580-5ea2-a181-7b81665b3353', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 5, 5, 'ሞዓብ ራሷን ይዛ ትጮኻለች፤ ለልቧም ይረዳታል፤ እስከ ሴጎርም ድረስ ብቻዋን ታለቅሳለች። ሞዓብ እንደ ሦስት ዓመት ጥጃ ናትና በሉሒት ዐቀበት ትጮኻለች። በአሮሜዎን መንገድም ይመለሳሉ፤ ይጮኻሉም፥ ጥፋትና መናወጥም ይሆናል።'),
  ('73e1f51d-b3fc-51c6-aa9e-324b40c5bcd7', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 6, 6, 'የኔምሬም ውኃ ይነጥፋል፤ ሣሯም ይደርቃል፤ በውስጧም ልምላሜ አይገኝም።'),
  ('73579df0-d569-5825-ab2e-ba22587b63ee', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 7, 7, 'ስለዚህ ሞዓብ ይድናልን? ዐረባውያንን ወደ ሸለቆው አመጣቸዋለሁና፤ እነርሱም ይወስዷታል።'),
  ('d95eb8fe-e92c-5324-acc0-87a3c36536f9', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 8, 8, 'ጩኸት የሞዓብን ዳርቻ ሁሉ ዞረ፤ ልቅሶዋም ወደ ኤግላይምና ወደ ኢሊም ጕድጓድ ደረሰ።'),
  ('8f32eddf-7418-53f3-ae13-99300eb4ceff', '3587832c-59fb-5d6d-afc8-f42310e51db0', '154d5043-1d7e-57d5-a0dc-603dde20c1c6', 9, 9, 'የዲሞንም ውኃ ደም ተሞልታለች፤ በዲሞን ላይ ዐረባውያንን አመጣለሁና፤ የሞዓብንና የአርያልን ዘር፥ ከኤዶምያስም የተረፉትን ወስጄ እንደ አራዊት በምድር ላይ እሰድዳቸዋለሁ።'),
  ('d44497e4-b306-5356-a417-e57ba1557e50', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 1, 1, 'የጽዮን ሴት ልጅ ተራራ ምድረ በዳ አይደለችምን?'),
  ('a1aea4d9-5581-546f-a1e4-b5c4be1baad0', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 2, 2, 'ጫጩቶችዋን አሳድጋ እንደ ተወች ወፍ ሆናለችና፤ የሞዓብ ሴት ልጅም እንደ ሰባ የበግ ጠቦት ሆነች።'),
  ('4d5b0ba2-3c98-5daa-a9a1-52dfa0cad312', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 3, 3, 'አርኖንም በምትኖርበት ምሽግ መጠለያን ትሠራ ዘንድ ብዙ ትመክራለች፤ በቀትር ጊዜ እንደ ሌሊት ደንግጠው ይሸሻሉ፤ ወደ እናንተም አታስገቡአቸው።'),
  ('5f81b7a8-5d54-52bc-a92f-fe760f8ebae7', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 4, 4, 'ከሚከቧችሁ ጋር ጠላቶች እንዳይሆኗችሁ ከሞዓብ የተሰደዱትን ከእናንተ ጋር አታስቀምጡ፤ ሰልፈኞች አልቀዋልና፤ በሀገሪቱ ሁሉ የነበረውም አለቃ ጠፍቶአልና።'),
  ('3dd4c9d8-f6d8-5e88-a5c0-bf5f4eb00a2d', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 5, 5, 'ዙፋን በምሕረት ይጸናል፥ በዚያም ላይ በዳዊት ቤት ፍርድን የሚሻ ጽድቅንም የሚያፋጥን ፈራጅ በእውነት ይቀመጣል፤ ይፈርዳልም።'),
  ('211a34e8-cca2-5623-acd4-d19d98165d54', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 6, 6, 'የሞዓብን ትዕቢትና እጅግ መኵራቱን ሰምተናል፤ ትዕቢቱንም አስወገድሁ፤ ጥንቈላህ እንዲህ አይደለምና፥ እንዲህም አይደለም፤'),
  ('15ebce41-c93a-5db8-a939-9a0259ff4a3b', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 7, 7, 'ሞዓብ ዋይ በሉ፤ ሁሉም በሞዓብ ዋይ ይላሉና፤ በዴሴት የሚኖሩም አያመልጡም፤ ጠብን ያጭራሉ፤ ያፍራሉም።'),
  ('4922cced-f44a-5dff-ae99-866c19785827', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 8, 8, 'የሐሴቦን እርሻዎችና የሴባማ ወይን ግንዶች አዝነዋል። የአሕዛብ አለቆች የሰባበሩአቸው ቅርንጫፎች እስከ ኢያዜር ደርሰው ወደ ምድረ በዳ ወጥተው ነበር፤ ቍጥቋጦቹም ተዘርግተው ባሕርን ተሻግረው ነበር።'),
  ('dc00bd99-9142-5501-a0b5-321dc5ee59c0', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 9, 9, 'ስለዚህ በኢያዜር ልቅሶ ስለ ሴባማ ወይን ግንድ አለቅሳለሁ፤ ሐሴቦንና ኤልያሊ ሆይ፥ ዛፎችሽ ወድቀዋል፤ የዛፍሽን ፍሬና የወይንሽን መከር እረግጣለሁ፤ ተክሎችሽ ሁሉ ይወድቃሉ።'),
  ('27bf5db3-a7b9-51d5-a432-52530b5952b7', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 10, 10, 'ደስታና ሐሤትም ከወይን ቦታሽ ተወስዶአል፤ በወይንሽም ቦታዎች ፈጽመው ደስ አይላቸውም፤ በመጥመቂያውም ወይንን አይረግጡም፤ ረጋጮቹን አጥፍቻለሁና።'),
  ('db5842e2-1369-5bdc-aa4a-2d549fd84735', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 11, 11, 'ስለዚህ ልቤ ስለ ሞዓብ እንደ መሰንቆ ትጮኻለች። አጥንቶችም እንደ ተመረገ ግድግዳ ይሆናሉ።'),
  ('839beef6-12e5-5b4d-a0f9-fdf1bcab4882', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 12, 12, 'ለኀፍረት ይሆንብሃል፤ ሞዓብ በመሠዊያዎችዋ ደክማለችና፤ ለጸሎትም ወደ ጣዖቶችዋ ትሄዳለች፤ ሊያድኑአትም አይችሉም።'),
  ('9aac11a2-53fb-50e9-a920-cbd5ea35802e', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 13, 13, 'እግዚአብሔር በሞዓብ ላይ በድሮ ዘመን የተናገረው ነገር ይህ ነው።'),
  ('e37be88e-5e18-5eda-a314-b3251383ca62', '3661bc40-4e3a-5a4a-a9bd-44e48fd4e710', 'e7b7bae6-8cd0-5df6-af2f-af57dab9c5ec', 14, 14, 'አሁንም እንዲህ እላለሁ፤ በሦስት ዓመት ውስጥ እንደ ምንደኛ ዓመት የሞዓብ ክብር ከብዙ ሀብትዋ ጋር ይዋረዳል፤ በቍጥርም ጥቂት ይቀራል፤ ክብርዋም አይገኝም።'),
  ('7be93718-a5f9-57e2-adeb-657bf53de731', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 1, 1, 'ስለ ደማስቆ የተነገረ ቃል። “እነሆ፥ ደማስቆ ከከተሞች መካከል ተለይታ ትጠፋለች፤ ትፈርሳለችም።'),
  ('ab336d94-02d8-57b0-ac32-8194dd936a5e', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 2, 2, 'ለዘለዓለም የተፈታች ትሆናለች፤ ለመንጋ ማሰማርያም ትሆናለች፤ የሚያሳድዳቸውም የለም።'),
  ('0f3cde2c-3a39-51cd-ad68-01a9a1c62416', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 3, 3, 'ኤፍሬም የሚጠጋበት ምሽግ አይኖርም፤ ከእንግዲህም ወዲያ ንጉሥ በደማስቆ አይነግሥም። የሶርያ ቅሬታ ሆይ፥ ከእስራኤል ልጆች ከክብራቸው የምትሻል አይደለህም” ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('48c089f5-def3-5c07-a27a-d230f243ba08', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 4, 4, '“በዚያም ቀን እንዲህ ይሆናል፤ የያዕቆብ ክብር ይደክማል፤ የሚበዛ የክብሩ ብልጽግናም ይነዋወጣል።'),
  ('98c57601-b647-5cb4-a466-45bf36b6a67b', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 5, 5, 'አጫጅ የቆመውን እህል ሰብስቦ ዛላውን እንደሚያጭድ ይሆናል፤ በሸለቆ እሸትን እንደሚሰበስብም እንዲሁ ይሆናል።'),
  ('12e86cf7-68bf-5d15-a5c3-a6cadf79a488', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 6, 6, 'ወይራ በተመታ ጊዜ ሁለት ወይም ሦስት ፍሬ በራሱ ላይ እንደሚቀር፥ አራት ወይም አምስት በዛፊቱ ጫፍ እንደሚገኝ፥ በእርሱ ዘንድ ቃርሚያ ይቀራል” ይላል የእስራኤል አምላክ እግዚአብሔር።'),
  ('01ec6371-e96b-55c7-a096-b04d4eb1c621', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 7, 7, 'በዚያም ቀን ሰው በፈጣሪው ይታመናል፤ ዐይኖቹም ወደ እስራኤል ቅዱስ ያያሉ።'),
  ('68ff8a22-a372-5ace-a018-e438f9c98eb7', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 8, 8, 'በጣዖታቸውና ጣቶቻቸው በሠሩአቸው የእጃቸው ሥራዎች አይተማመኑም፤ ለርኵሰታቸውም ዛፎችን አይቈርጡም።'),
  ('e680173b-7561-565a-a07d-36c79d6034cf', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 9, 9, 'በዚያም ቀን በእስራኤል ልጆች ፊት የአሞራውያንና የኤዌዎያውያን ከተሞች እንደ ተፈቱ፥ እንዲሁ ከተሞችህ ይፈታሉ፤ ባድማም ይሆናሉ።'),
  ('35ec8c85-1a52-5a34-ae7c-0ebaf5fed9c3', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 10, 10, 'አዳኝህ እግዚአብሔርን ትተኸዋልና፥ ረዳትህ እግዚአብሔርንም አላስብኸውም፤ ስለዚህ የሐሰትን ተክል ተክለሃል፤ የሐሣርንም ዘር ዘርተሃል።'),
  ('cafc8258-f907-5a84-a73f-715f9995e6fe', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 11, 11, 'ተክልን በተከልህበት ቀን ትበድላለህ፤ የዘራኸውም በበነጋው በምታወርስበት ቀን ይበቅላል፤ አባትም ለልጁ እንደሚያወርስ አንተም ለልጆችህ ታወርሳለህ።'),
  ('86126d16-9255-5e9a-ab8f-b7289cc705ff', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 12, 12, 'እንደ ውኃ ለሞሉ፥ ከተራራ በመከታተል እንደሚወርድ የውኃ ፈሳሽ ለሆኑም ብዙዎች አሕዛብ ወዮላቸው!'),
  ('7ae20070-bbaa-52b7-ab38-1d6d6f104f52', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 13, 13, 'ብዙዎች አሕዛብ እንደ ብዙ ውኃ ናቸው፤ ከፏፏቴ ውስጥ በኀይል እንደሚወርድ እንደ ብዙ ውኃ ፈሳሽ ይጮኻሉ፤ ያጠፉታልም፤ እነርሱም ከሩቅ ይወርዳሉ፤ በተራራም ላይ እንዳለ እብቅ፥ በነፋስ ፊት ዐውሎ ነፋስ እንደሚያዞረው እንደ መንኰራኵር ትቢያም ይበተናሉ።'),
  ('85c98921-e230-5e31-af23-42d81e9d9ac7', 'fcf38295-db38-534e-aef5-bec3459e5d90', 'fabbeb16-3c85-555f-aa97-0a83b48d1867', 14, 14, 'በመሸም ጊዜ ሳይነጋ ያለቅሳሉ፤ ያንጊዜም የይሁዳ ወገኖች “ይህ የወራሾች ርስት ነው፤ የበዘበዙንም ዕድል ፋንታ ይህ ነው” ይላሉ።'),
  ('0ee15d81-85ec-57c3-a0f9-31e3ef026f19', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 1, 1, 'በኢትዮጵያ ወንዞች ማዶ ላለች፥ ክንፍ ያላቸው መርከቦች ላሉባት ምድር ወዮላት!'),
  ('27bc664f-c8ca-5da8-afc5-081c36ad1348', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 2, 2, 'መልእክተኞችን በባሕር ላይ፥ ደብዳቤዎችንም በውኃ ላይ ይልካል። ፈጣኖች መልእክተኞች ወደ ረዥምና ወደ ባዕድ፥ ወደ ክፉም ሕዝብ ይሄዳሉና፤ ተስፋ የቈረጡና የተረገጡ ሕዝብ እነማን ናቸው? ዛሬ ግን የምድር ወንዞች ሁሉ፥ ሰዎች እንደሚኖሩባት ሀገር ይኖራሉ።'),
  ('a7ae2dc2-a12b-51ca-a6ad-aae56935ca52', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 3, 3, 'በየሀገራቸው ይቀመጣሉ፤ ከተራሮች ራሶችም እንደ ዓላማ ይይዙታል፤ እንደ መለከት ድምፅም ይሰማል።'),
  ('5094353c-9099-59d7-a0f7-05c7f93721c2', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 4, 4, 'እግዚአብሔር፥ “እንደ ቀትር ብርሃን፥ በአጨዳም ወራት እንደ ጠል ደመና በማደሪያዬ ጸጥታ ይሆናል” ብሎኛልና።'),
  ('03fdf384-dae2-5721-ae90-1626ec78464b', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 5, 5, 'እርሱ ከመከር በፊት አበባ በረገፈ ጊዜ የወይንም ፍሬ ጨርቋ ሲይዝ የወይኑን ቀጫጭን ዘንግ በማጭድ ይቈርጣል፤ ጫፎቹንም ይመለምላል፤ ያስወግድማል።'),
  ('ce2dee79-8673-5756-a85e-19578498236d', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 6, 6, 'ለሰማይ ወፎችና ለምድር አውሬዎችም በአንድነት ይቀራሉ፤ የሰማይ ወፎችና የምድር አውሬዎችም ሁሉ ይሰበሰቡባቸዋል።'),
  ('6f9f7712-61ef-5d60-a0f8-6e64c9aa5780', '278bc5ec-b29b-5f96-a9f7-adda9143f9cd', '5577e8d3-3409-5bc8-a71c-b4f8af10f7f7', 7, 7, 'በዚያ ዘመን ለሠራዊት ጌታ ለእግዚአብሔር፥ ከተዋረደና ከደከመ ሕዝብ፥ ከዛሬ እስከ ዘለዓለም ታላቅ ከሆነ ወገን፥ ተስፋ ከሚያደርግና ከሚረገጥ፥ በሀገሩ ወንዝ ዳር ከሚኖር ሕዝብ ዘንድ የሠራዊት ጌታ የእግዚአብሔር ስም በተጠራበት በደብረ ጽዮን እጅ መንሻ ይቀርባል።'),
  ('d364de55-1f11-532f-af9b-fb6c8bab64ec', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 1, 1, 'ስለ ግብፅ የተነገረ ራእይ። እነሆ፥ እግዚአብሔር በፈጣን ደመና ተቀምጦ ወደ ግብፅ ይመጣል፤ የግብፅም የእጆቻቸው ሥራዎች በፊቱ ይዋረዳሉ፤ የግብፃውያንም ልብ በውስጣቸው ይቀልጣል።'),
  ('02975b02-fc23-5a2d-ad90-b25464dbc760', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 2, 2, '“ግብፃውያን በግብፃውያን ላይ ይነሣሉ፤ ወንድምም ወንድሙን፥ ሰውም ባልንጀራውን ይገድላል፤ ከተማም ከተማን፥ መንግሥትም መንግሥትን ይወጋል።'),
  ('ebadbe9c-fe11-5113-a88e-a38061962aee', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 3, 3, 'የግብፅም መንፈስ በውስጣቸው ትደነግጣለች፤ ምክራቸውን አጠፋለሁ፤ እነርሱም አማልክቶቻቸውንና ጣዖቶቻቸውን፥ ድምፃቸውን ዝቅ አድርገው የሚናገሩትን መናፍስት ጠሪዎቻቸውንም ይጠይቃሉ።'),
  ('e52662f6-59b7-5646-abb6-508453269af6', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 4, 4, 'ግብፃውያንንም በጨካኝ ጌቶች እጅ አሳልፌ እሰጣለሁ፤ ጨካኞች ነገሥታትም ይገዟቸዋል” ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('c827118e-3348-5706-a662-c3983642ce9b', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 5, 5, 'ግብፃውያን ከባሕር ውኃን ይጠጣሉ፤ ወንዙም ያንሳል፤ ደረቅም ይሆናል።'),
  ('bf536eb3-8ee3-526e-a48d-20213109033e', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 6, 6, 'ወንዞችም ይነጥፋሉ። ቦዮችና መስኖች ያንሳሉ፤ ይደርቃሉም፤ ደንገልና ቄጤማ ይጠወልጋሉ።'),
  ('55253123-5f5b-5c86-a184-7dbe1d38f95b', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 7, 7, 'በዓባይ ወንዝ ዳር ያለው መስክ፥ በዓባይም ወንዝ አጠገብ የተዘራ እርሻ ሁሉ በነፋስ ይመታል፤ ይደርቃልም፤'),
  ('e05b3070-f71b-54d4-a281-40b6e4521724', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 8, 8, 'ዓሣ አጥማጆቹ ያዝናሉ፤ በዓባይም ወንዝ መቃጥን የሚጥሉት ሁሉ ያለቅሳሉ፤ በውኆችም ላይ መረብ የሚዘረጉት ያለቅሳሉ።'),
  ('281207d8-6ea4-5b87-a134-f70cb8bc677d', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 9, 9, 'የተቈራረጠውንም መረብ የሚጠግኑ፥ ነጩንም ልብስ የሚሠሩ ሸማኔዎች ያፍራሉ።'),
  ('b4912e59-1e23-52f0-a62a-421140aaf49d', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 10, 10, 'በእነርሱም የሚሠሩ ይሠቃያሉ፤ በሐር ኩብ የሚነግዱ ሁሉ ይቀልጣሉ፤ ልቡናቸውም ያዝናል።'),
  ('50f77733-8182-51da-ab20-77ba18fab949', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 11, 11, 'የጣኔዎስ አለቆች ሰነፎች ይሆናሉ፤ ነገሥታትን የሚመክሩ ጥበበኞችም ምክራቸው ስንፍና ትሆናለች። ንጉሥን፥ “እኛ የጥበበኞች ልጆች፥ የቀደሙ ነገሥታትም ልጆች ነን እንዴት ትሉታላችሁ?”'),
  ('1d3ddc3f-23b5-592b-a396-fb391b469cc0', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 12, 12, 'አሁን ጥበበኞችህ የት አሉ? አሁን ያብስሩህ፤ የሠራዊት ጌታ እግዚአብሔር በግብፅ ላይ ያሰበውን እስኪ ይንገሩህ።'),
  ('add0fd90-ff48-5e4f-a3ec-77c7b03f0836', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 13, 13, 'የጣኔዎስ አለቆች አለቁ፤ የሜምፎስም አለቆች ከፍ ከፍ አሉ፤ ግብፃውያን በየወገናቸው ተሳሳቱ።'),
  ('59dc6301-9a9e-5bf9-a2ea-bffec35063af', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 14, 14, 'እግዚአብሔር የሚያስት መንፈስን ልኮባቸዋልና፤ ሰካርም፥ ደም ያዞረውም እንዲስት እንዲሁ ግብፃውያን በሥራቸው ሁሉ ሳቱ።'),
  ('3b4e80e5-8aae-56e8-aa83-fe2401d6a20c', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 15, 15, 'ለግብፃውያን ራስ ወይም ጅራት፥ መጀመሪያ ወይም መጨረሻ ያለው ሥራ የላቸውም።'),
  ('7a69c24d-c25d-56c3-ae47-cf75d5678967', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 16, 16, 'በዚያም ቀን የሠራዊት ጌታ እግዚአብሔር ከሚያወርድባቸው ፍርሀትና መንቀጥቀጥ የተነሣ ግብፃውያን እንደ ሴቶች ይሆናሉ።'),
  ('c774964b-03b6-59fe-ad72-8a507742ce6e', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 17, 17, 'የይሁዳም ምድር ግብፅን የምታስደነግጥ ትሆናለች፤ የሠራዊት ጌታ እግዚአብሔር ከመከረባት ምክር የተነሣ ስምዋን የሚሰማ ሁሉ ይፈራል።'),
  ('ada4f860-a91d-536c-a980-f424ae9087c2', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 18, 18, 'በዚያ ቀን አምስት የግብፅ ከተሞች በከነዓን ቋንቋ ይናገራሉ፤ በሠራዊት ጌታ በእግዚአብሔርም ስም ይጠሩ ዘንድ ከተሞች አንድ ይሆናሉ፤ ከእነዚህም አንዲቱ የጽድቅ ከተማ ተብላ ትጠራለች።'),
  ('c3463b23-30f8-589d-aaba-df095c9654f0', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 19, 19, 'በዚያ ቀን በግብፅ ምድር መካከል አንዲቱ ከተማ ለእግዚአብሔር መሠዊያ ትሆናለች፤ በዳርቻዋም ለእግዚአብሔርዐምድ ይሆናል።'),
  ('275fea75-3504-5ba2-adeb-2603b0c917a0', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 20, 20, 'ይህም ለሠራዊት ጌታ ለእግዚአብሔር በግብፅ ምድር ለዘለዓለም ምልክት ይሆናል፤ ከሚያስጨንቋቸው የተነሣ ወደ እግዚአብሔር ይጮኻሉና፥ እርሱም የሚያድናቸውን ሰው ይልክላቸዋል፤ ይፈርዳል፤ ያድናቸዋልም።'),
  ('b466cc17-44be-5e17-a473-7ce696708741', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 21, 21, 'በዚያም ቀን እግዚአብሔር በግብፅ የታወቀ ይሆናል፤ በዚያም ጊዜ ግብፃውያን እግዚአብሔርን ያውቃሉ፤ መሥዋዕትም ያቀርቡለታል፤ ለእግዚአብሔርም ስእለት ይሳላሉ፤ መባኡንም ያገባሉ።'),
  ('9bb376c5-2bc0-57f8-a94c-a01fd6a91eb4', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 22, 22, 'እግዚአብሔርም ግብፅን በታላቅ መቅሠፍት ይመታታል፤ ይፈውሳታልም፤ ከዚያም በኋላ ወደ እግዚአብሔር ይመለሳሉ፤ እርሱም ይሰማቸዋል፤ ይፈውሳቸውማል።'),
  ('e919375b-16de-5c47-a833-8c99be0a7059', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 23, 23, 'በዚያም ወራት ከግብፅ ወደ አሦር መንገድ ይሆናል፤ አሦራዊውም ወደ ግብፅ፥ ግብፃዊውም ወደ አሦር ይገባል፤ ግብፃውያንም ለአሦራውያን ይገዛሉ።'),
  ('0370730d-8ba7-54a8-a17f-d20346024fff', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 24, 24, 'በዚያም ወራት እስራኤል ለግብፅና ለአሦር ሦስተኛ ይሆናል፤ በምድርም መካከል በረከት ይሆናል።'),
  ('aedd1eaa-90f2-578e-ad50-5f5e44be0f5a', '3be87156-4d5a-54e8-abdb-90f1b3f8fb09', '0114999d-41cb-5113-a715-be5a68db325c', 25, 25, 'የሠራዊት ጌታ እግዚአብሔር፥ “በግብፅ ውስጥ ያለ ሕዝቤ፥ በአሦር መካከልም ያለ ሕዝቤ፥ ርስቴም እስራኤል የተባረከ ይሁን” ብሎ ይባርካቸዋልና።'),
  ('b9d65399-2225-5ee7-a16a-5288ac1082dd', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 1, 1, 'የአሦር ንጉሥ አርና ጣንታንን በሰደደ ጊዜ፥ እርሱም ወደ አዛጦን በመጣ ጊዜ፥ አዛጦንንም ወግቶ በያዛት ጊዜ፥'),
  ('b8888dce-8cab-5642-a04d-3a01d410693e', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 2, 2, 'በዚያ ዓመት እግዚአብሔር የአሞጽን ልጅ ኢሳይያስን፥ “ሂድ፥ ማቅህን ከወገብህ አውጣ፤ ጫማህንም ከእግርህ አውልቅ፤ ያለጫማም በባዶ እግርህ ሂድ” ብሎ ተናገረው። እንዲህም አደረገ፤ ራቁቱንም ያለ ጫማ ሄደ።'),
  ('db2fe4ed-935b-5d78-a0ea-0f1f6c3e0e81', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 3, 3, 'እግዚአብሔርም አለ፥ “ባሪያዬ ኢሳይያስ ሦስት ዓመት ራቁቱን በባዶ እግሩ እንደ ሄደ፥ እንዲሁ በግብፅና በኢትዮጵያ ላይ ሦስት ዓመት ምልክትና ተአምራት ይደረጋል።'),
  ('c1f166c3-67ef-5e6e-ab6b-219e76a3ed48', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 4, 4, 'እንዲሁ የአሦር ንጉሥ የግብፅንና የኢትዮጵያን ምርኮ፥ ጐበዛዝቱንና ሽማግሌዎቹን ራቁታቸውንና ባዶ እግራቸውን አድርጎ፥ ገላቸውንም ገልጦ ለግብፅ ኀፍረት ይነዳቸዋል።'),
  ('22a987e3-7d0e-57e0-ab20-aae9906eca52', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 5, 5, 'ግብፃውያን ከኢትዮጵያውያን ጋር ይሸነፋሉ፤ ግብፃውያንም ከታመኑባቸው ጋር ይፈራሉ፤ ያፍሩማል።'),
  ('ea79807c-a245-58f9-a41a-33ca47ab9ddf', '89e007ea-2dd8-57cc-aa0e-f9399236c2a3', 'b77b5803-dc3e-5936-a7eb-61961eecbe47', 6, 6, 'በዚያም ቀን በዚች ደሴት የሚቀመጡ፦ እነሆ፥ ለርዳታ ወደ እነርሱ የሸሸንበት ተስፋችን ይህ ነበረ፤ ከአሦር ንጉሥ ራሳቸውን ያላዳኑ እኛን እንዴት ያድኑናል?” ይላሉ።'),
  ('99616832-60b9-528b-a04a-d5d860dbd354', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 1, 1, 'ስለ ምድረ በዳ የተነገረ ቃል፤ ዐውሎ ነፋስ በምድረ በዳ እንደሚያልፍ፥ እንዲሁ ከሚያስፈራ ሀገር ከምድረ በዳ ይመጣል።'),
  ('8225d508-e07f-58a1-a8be-97a9f078f6a0', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 2, 2, 'ከባድ ራእይ ተነገረኝ፤ ወንጀለኛው ይወነጅላል፤ በደለኛውም ይበድላል። የኤላም ሰዎችና የሜዶን መልእክተኛ በእኔ ላይ ይመጣሉ። ዛሬ ግን እጨነቃለሁ፤ እረጋጋለሁም።'),
  ('38a0f87b-85ba-59d1-a81b-f22c076b3bca', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 3, 3, 'ስለዚህም ወገቤ ሕማም ተሞላ፤ እንደምትወልድ ሴትም ምጥ ያዘኝ፤ ከሕማሜ የተነሣ አልሰማም፤ ከድንጋጤም የተነሣ አላይም።'),
  ('35c225c9-374d-556b-ab43-3a8efea6c87b', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 4, 4, 'ልቤ ሳተ፤ ኀጢአቴም አሰጠመኝ፤ ሰውነቴም ደነገጠብኝ።'),
  ('2b34d3e5-03dc-510c-a36a-8580adae4b70', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 5, 5, 'ማዕዱን አዘጋጁ፤ ብሉ፤ ጠጡ፤ እናንተ አለቆች ሆይ፥ ተነሡ፤ ጋሻውንም አዘጋጁ።'),
  ('9e24ecdb-5430-554e-af9f-364e14fdecbe', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 6, 6, 'እግዚአብሔር እንዲህ ብሎኛልና፥ “ፈጥነህ ሂድ፤ ጕበኛንም አቁም፤ የሚያየውንም ይናገር፤ የሚሰማውንም ያውራ።'),
  ('7c94c90a-4eee-5c1d-a38a-24c4f987feae', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 7, 7, 'ሁለት ፈረሰኞችን ሲጋልቡ አየሁ፤ አንዱ በአህያ ላይ፥ ሁለተኛውም በግመል ላይ ተቀምጦ ነበር፤ ድምፃቸው ግን እንደ ብዙዎች ፈረሰኞች ድምፅ ነበረ።”'),
  ('0ada919b-8995-5961-a628-3a0a2d3247e7', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 8, 8, 'የእግዚአብሔር ጕበኛ ኦርያስ ተጠራ፤ እርሱም፥ “እነሆ እኔ አለሁ፤ መላ መዓልቱንና መላ ሌሊቱን በማማ ላይ ቆሜ አለሁ።'),
  ('be77a5ad-0421-5949-aa9a-353fc46b238c', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 9, 9, 'እነሆም፥ በፈረሶች የሚቀመጡ፥ ሁለት ሁለት ሆነው የሚሄዱ ፈረሰኞች ይመጣሉ” ብሎ ጮኸ፤ እርሱም መልሶ፥ “ባቢሎን ወደቀች! ወደቀች! ጣዖቶችዋም ሁሉ፥ የእጆችዋም ሥራዎች ሁሉ በምድር ላይ ተጥለው ደቀቁ” አለ።'),
  ('8f218cc9-d344-50d6-a0f3-521582f0fa01', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 10, 10, 'እናንተ የተረፋችሁና መከራ የምትቀበሉ ሆይ፥ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር የነገረኝንና የሰማሁትን ስሙ።'),
  ('353148c1-5630-50f2-a78b-272cbbc045ce', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 11, 11, 'ስለ ኤዶምያስ የተነገረ ነገር። አንዱ ከሴይር፥ “ጕበኛ ሆይ፥ ሌሊቱ ምን ያህል ነው? ጕበኛ ሆይ፥ ሌሊቱ ምን ያህል ነው?” ብሎ ጠራኝ።'),
  ('20a0de94-97a0-5727-a70d-8f49236492b4', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 12, 12, 'ጕበኛውም፥ “ይነጋል፤ ደግሞም ይመሻል፤ ትጠይቁ ዘንድ ብትወድዱ ጠይቁ፤ ተመልሳችሁም ኑ፥” አለ።'),
  ('a494cfbd-fc2f-595c-a0fe-870242b636b9', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 13, 13, 'ሌሊትም በዲዳናውያን ጎዳና በዛፎች ውስጥ ታድራለህ፤'),
  ('772923cd-2588-57a8-a55c-61d905d9cddb', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 14, 14, 'በቴማን የምትኖሩ ሆይ፥ ወደ ተጠሙት ሰዎች ውኃ አምጡ፤'),
  ('c7606827-9d28-5d6d-abc3-137c43e5b4d7', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 15, 15, 'እንጀራ ይዛችሁ ከሰልፍ ከሸሹ ከብዙ ሰዎችና በጦር ከጠፉ ከብዙ ሰዎች፥ ፍላጻ ከያዙ ከብዙ ሰዎችና ጦር ከያዙ ከብዙ ሰዎች፥ ቀስቶቻቸው ከተሳቡና በሰልፍ ከወደቁ ከብዙ ሰዎች ያመለጡትን ተቀበሏቸው።'),
  ('7f64f932-c366-5736-a8f5-50246c861f94', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 16, 16, 'እግዚአብሔር እንደ ገና እንዲህ ብሎኛልና፥ “እንደ ምንደኛ ዓመት በአንድ ዓመት ውስጥ የቄዳር ልጆች ክብር ሁሉ ይጠፋል፤'),
  ('61092961-bb92-5fb5-aa5f-919a4135b31d', 'c1416443-ef11-5594-a80f-f073135ad968', 'a5578f7a-a6a4-5586-aeaa-c3a6398e108d', 17, 17, 'ከቀስተኞች ቍጥር የቀሩት፥ የቄዳር ልጆች ኀያላን፥ ያንሳሉ፤” የእስራኤል አምላክ እግዚአብሔር ይህን ተናግሮአልና።'),
  ('3f4076f1-7d69-5d80-a0e9-3067fc35672b', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 1, 1, 'ስለ ጽዮን ሸለቆ የተነገረ ቃል። እናንተ ሁላችሁ፥ ዛሬ ወደ ሰገነት በከንቱ መውጣታችሁ ምን ሆናችኋል?'),
  ('173f6ff4-8429-59eb-ad8b-b9ef4796e804', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 2, 2, 'ጩኸትና ፍጅትም የተሞላብሽ ከተማ ሆይ፥ ቍስለኞችሽ በሰይፍ የቈሰሉ አይደሉም፤ በአንቺ ውስጥ የተገደሉትም በሰልፍ የተገደሉ አይደሉም።'),
  ('51c88cf7-dcd5-59bc-ab68-5ba081a87dd5', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 3, 3, 'ነገር ግን አለቆችሽ ሁሉ በአንድነት ሸሹ፤ የተማረኩትንም በእግር ብረት አሠቃዩአቸው፤ ኀይለኞችሽም ርቀው ሸሹ።'),
  ('6a345bda-e1d3-5f19-a831-ec4e92e2ca2d', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 4, 4, 'ስለዚህ፥ “ተዉኝ እኔ መራራ ልቅሶ አለቅሳለሁ፤ ስለ ሕዝቤ ሴት ልጅ ጥፋትም ታጽናኑኝ ዘንድ አትድከሙ፥” አልሁ።'),
  ('24ade22c-7201-5b7b-af93-e8b6de391856', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 5, 5, 'ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ የሁከትና የጥፋት፥ የመረገጥና የስብራትም ቀን በጽዮን ሸለቆ ውስጥ ሆኖአል። ታናሹና ታላቁም ሸሽተው በተራራ ላይ ይቅበዘበዛሉ።'),
  ('eb0b6a66-6af9-5d79-a398-038c8f81118a', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 6, 6, 'የኤላምም ሰዎች አፎታቸውን ተሸከሙ፤ በፈረስ የተቀመጡና አርበኞች ሰዎች፥ የአርበኞችም ሠራዊት ነበሩ።'),
  ('81b467f2-76e0-5562-a909-a6fc6bde91d6', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 7, 7, 'መልካሞቹን ሸለቆችሽንም ሰረገሎች ሞሉባቸው፤ ፈረሰኞችም መቆሚያቸውን በበሮችሽ ላይ አደረጉ።'),
  ('f610e94b-30f3-524f-ae92-ae737c6a9fce', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 8, 8, 'የይሁዳንም በሮች ይከፍታሉ፤ በዚያም ቀን የከተማይቱን መኳንንት ቤቶች ይበረብራሉ። የዳዊት ቤት መዛግብትንም ይከፍታሉ።'),
  ('02d81a12-5d4d-5d25-a532-3e39f321669e', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 9, 9, 'የዳዊትም ከተማ ፍራሾች እንደበዙ አይታችኋል፤ የታችኛውንም ኵሬ ውኃ በከተማ አከማችታችኋል፤'),
  ('983f2b70-06ff-55a6-a147-5f2553455d5e', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 10, 10, 'የኢየሩሳሌምንም ቤቶች ቈጠራችሁ፤ ቅጥሩንም ለማጽናት ቤቶችን አፈረሳችሁ።'),
  ('e1c2e97d-c1a9-590b-afb9-aaa958151c42', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 11, 11, 'በአሮጌው ኵሬ ላለው ውኃ በሁለቱ ቅጥር መካከል መከማቻ ሠራችሁ፤ ይህን ያደረገውን ግን አልተመለከታችሁም፤ ቀድሞ የሠራውንም አላያችሁም።'),
  ('a720b08e-6b3a-55bf-a794-44517690067a', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 12, 12, 'በዚያም ቀን የሠራዊት ጌታ እግዚአብሔር ልቅሶንና ዋይታን፥ ራስን መንጨትንና ማቅን መልበስን ጠራ።'),
  ('c64e713d-0b60-55d4-abab-f1d7058c0cea', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 13, 13, 'እነሆም፥ በዓልን፥ ደስታንና ሐሴትን አደረጋችሁ፤ በሬዎችንና በጎችንም አረዳችሁ፤ “ነገ እንሞታለን፤ እንብላ፤ እንጠጣም፤” እያላችሁ ሥጋን በላችሁ፤ ወይንንም ጠጣችሁ።'),
  ('c5f8a428-0944-514d-a741-32d0ec671b9b', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 14, 14, 'ይህም ነገር በሠራዊት ጌታ በእግዚአብሔር ጆሮ ተሰማ፥ “እስክትሞቱ ድረስ ይህ በደል በእውነት አይሰረይላችሁም” ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('8fd4b60c-0897-52da-a546-456d0a9ed2be', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 15, 15, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ አለኝ፥ “ወደ ገንዘብ ጠባቂው ወደ ሳምናስ ሂድ እንዲህም በለው፦'),
  ('7b3629d5-836a-5c80-af72-895a1967d5d7', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 16, 16, 'መቃብር በዚያ ያስወቀርህ፥ ከፍ ባለው ስፍራ መቃብር ያሠራህ፥ በድንጋይም ውስጥ ለራስህ መኖርያ ያሳነጽህ ወደዚህ ለምን መጣህ? ለምንስ በዚህ ተደፋፈርህ?'),
  ('2f5309d6-56f5-5ae8-a51d-28839ab6eb69', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 17, 17, 'እነሆ የሠራዊት ጌታ እግዚአብሔር በኀይል ወርውሮ ይጥልሃል፤ ያጠፋሃልም፤ ልብስህንና የክብር አክሊልህንም ይገፍሃል፤'),
  ('018a42ed-69e0-54d3-a8d6-68f73b2a4aa7', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 18, 18, 'ወደ መከራ ሀገር ይጥልሃል፤ በዚያም ትሞታለህ፤ ያማረ ሰረገላህንም ያጐሰቍለዋል፤ የአለቃህም ቤት ይረገጣል።'),
  ('fc212ddf-e0f1-5027-a32b-21254a1593a2', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 19, 19, 'ከአዛዥነት ሥራህና ከሥልጣንህ ትሻራለህ።'),
  ('291d79ba-89a0-5325-a8e7-d834f1a615ef', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 20, 20, 'በዚያም ቀን ባሪያዬን የኬልቅዩን ልጅ ኤልያቄምን እጠራዋለሁ፤'),
  ('cc6bd7a2-d75a-5d15-a891-eeace26566ab', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 21, 21, 'መጐናጸፊያህንም አለብሰዋለሁ፤ አክሊልህንም እሰጠዋለሁ፤ ሹመትህንም በእጁ አሳልፌ እሰጠዋለሁ፤ በኢየሩሳሌምም ለሚኖሩና በይሁዳም ለሚኖሩ አባት ይሆናል።'),
  ('66967a9f-72e1-5bd0-af42-774b87372bdc', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 22, 22, 'የዳዊትንም ክብር እሰጠዋለሁ፤ ይገዛል፤ በአገዛዝም የሚበልጠው የለም። የዳዊትንም ቤት መክፈቻ በጫንቃው ላይ አኖራለሁ፤ እርሱም ይከፍታል፤ የሚዘጋም የለም፤ እርሱም ይዘጋል የሚከፍትም የለም።'),
  ('af0ce087-0bfe-5401-a7e2-fde0425c2c40', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 23, 23, 'በታመነ ስፍራ እንደ ችንካር እተክለዋለሁ፤ በአባቱም ቤት የክብር ዙፋን አስቀምጠዋለሁ።'),
  ('c59e5de7-788f-587d-ad54-9e83d9583ae5', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 24, 24, 'የአባቱንም ቤት ክብር ሁሉ፥ ልጆቹንም፥ የልጅ ልጆቹንም፥ ከጽዋ ዕቃ ጀምሮ እስከ ማድጋ ዕቃ ድረስ፥ ታናናሹንና ታላላቁን ሁሉ ይሰቅሉበታል።'),
  ('91c8c09a-0da4-5f91-a6e7-28c338f5df05', '7131b0f8-f477-57ba-a686-21b138f69f9c', '7b9bdaee-b9af-59d4-aa7c-34be108ed0ea', 25, 25, 'በዚያ ቀን፥ ይላል የሠራዊት ጌታ እግዚአብሔር፥ በታመነው ስፍራ የተተከለው ችንካር ይወልቃል፤ ተሰብሮም ይወድቃል፤ በእርሱም ላይ የተሰቀለው ሸክም ይጠፋል፤” እግዚአብሔር እንዲህ ተናግሮአልና።'),
  ('622b7d22-57dc-5b97-a87b-9eae68480c28', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 1, 1, 'ስለ ጢሮስ የተነገረ ትንቢት። የኬልቀዶን መርከቦች ሆይ፥ አልቅሱ፤ ጠፍተዋልና፤ እንግዲህም ከኬጤዎን ሀገር አይመጡምና ማርከውም ይወስዱአቸዋልና።'),
  ('c08426bd-0512-540a-a3a5-2d62ece29835', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 2, 2, 'በደሴት የሚኖሩ በባሕር የሚሻገሩ የፊኒቄ ስደተኞች ምን ይመስላሉ?'),
  ('fd3b3fb3-73f3-5fdc-a794-26048953ffbc', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 3, 3, 'የገቡ ስደተኞች አሕዛብ በመከር ጊዜ እንደሚለወጥ ዘር ናቸው።'),
  ('cf2a58ae-3fe4-5859-ad8b-96688e731a4b', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 4, 4, 'ሲዶና ሆይ፥ ባሕር፥ የባሕር ምሽግ፥ “አላማጥሁም፥ አልወለድሁም፤ ጐበዛዝትንም አላሳደግሁም፥ ደናግልንም አላሳደግሁም” ብሎ ተናግሮአልና እፈሪ።'),
  ('b1f0a436-9c6a-557f-a883-c902d7aae709', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 5, 5, 'ወሬዋ ወደ ግብፅ በደረሰ ጊዜ ስለ ጢሮስ ምጥ ይይዛቸዋል።'),
  ('10803d69-fe6c-5fb8-ad82-f7d65920a345', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 6, 6, 'ወደ ኬልቄዶን ተሻገሩ፤ እናንተ በደሴት የምትኖሩ፥ አልቅሱ።'),
  ('05273332-ee2c-52ba-aa60-5401f522e30f', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 7, 7, 'ተማርካችሁ ሂዱ እንጂ ይህች ዕረፍት የእናንተ አይደለችም።'),
  ('81adb2e2-bb1e-5569-ad70-d6e03adf9116', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 8, 8, 'በጢሮስ ላይ ይህን የመከረ ማን ነው? እርስዋ ከሁሉ የምትሻልና የምትበልጥ አይደለችምን? ነጋዴዎችዋ የከበሩ የምድር አለቆች ናቸው።'),
  ('3c4cfd0f-5f7e-5f56-a4c3-657e57a15b11', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 9, 9, 'የክቡራንን ትዕቢት ይሽር ዘንድ፥ የምድርንም ክቡራን ሁሉ ያዋርድ ዘንድ የሠራዊት ጌታ እግዚአብሔር ወስኖታል።'),
  ('95d23695-515f-59b0-a1f1-17efd5a25792', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 10, 10, 'ምድርህን እረስ፤ እንግዲህ መርከቦች ከኬልቀዶን አይመጡምና።'),
  ('13dde892-5bd0-5e19-adb2-7282752de695', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 11, 11, 'ነገሥታቱን ያበሳጨቻቸው የባሕር ሰዎች እጃቸው ትደክማለች፤ የሠራዊት ጌታ እግዚአብሔርም የከነዓንን ኀይል ያጠፉ ዘንድ አዘዘ።'),
  ('6712ace2-1605-506e-abba-39b46c5a2647', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 12, 12, 'እርሱም፥ “አንቺ የተበደልሽ የሲዶና ድንግል ልጅ ሆይ፥ ከእንግዲህ ወዲህ ደስ አይበልሽ፤ ተነሥተሽ ወደ ኪቲም ተሻገሪ፤ በዚያም ደግሞ አታርፊም” አለ።'),
  ('1e7166b0-ded3-5b0e-a4da-359277783571', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 13, 13, 'እነሆ፥ የከለዳውያንን ሀገር አሦራውያን አጥፍተዋታልና፤ ግንብዋም ወድቆአል፤'),
  ('16024e39-303a-56fd-aec2-0aca798a7053', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 14, 14, 'እናንተ የኬልቀዶን መርከቦች ሆይ፥ ምሽጋችሁ ፈርሶአልና ዋይ በሉ።'),
  ('1986957c-42c7-58b5-afff-64fd1307935e', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 15, 15, 'በዚያም ቀን እንዲህ ይሆናል፤ ጢሮስ እንደ አንድ ንጉሥ ዘመን ወይም እንደ አንድ ሰው ዘመን ሰባ ዓመት ያህል የተረሳች ትሆናለች፤ ከሰባ ዓመት በኋላ ግን ለጢሮስ በጋለሞታ ዘፈን እንደሚሆን እንዲሁ ይሆናል።'),
  ('2382b33e-4827-5760-a443-d97935ff2030', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 16, 16, 'አንቺ የተረሳሽ ጋለሞታ ሆይ፥ መሰንቆ ያዢ፤ በከተማ ላይም ዙሪ፤ መታሰቢያም ይሆንልሽ ዘንድ ዜማን አሳምሪ፤ ዘፈንሽንም አብዢ።'),
  ('7892359a-f7f6-5b47-ac1b-1ebcaa9beff9', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 17, 17, 'ከሰባ ዓመትም በኋላ እግዚአብሔር ጢሮስን በይቅርታ ይጐበኛታል፤ ወደ ጥንቷም ትመለሳለች፤ ደግሞም ለዓለም መንግሥታት ሁሉ መናገሻና መናገጃ ትሆናለች።'),
  ('ccbd129d-4fea-5acc-aa92-4f06ad6f7363', '2a317e37-a9f3-5ab6-a309-6b14c837f877', 'c0f66bc5-d6bb-52cc-aff1-503f26c5e4c0', 18, 18, 'ንግድዋና ዋጋዋ ለእግዚአብሔር የተቀደሰ ይሆናል፤ ንግድዋም በእግዚአብሔር ፊት ለሚኖሩ ለመብላትና ለመጠጣት፥ ለመጥገብም፥ በእግዚአብሔርም ፊት ለመታሰቢያ ይሆናል እንጂ ለእነርሱ አይሰበሰብም።'),
  ('8389a10c-e77f-546c-a464-66be05d72337', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 1, 1, 'እነሆ፥ እግዚአብሔር ዓለምን ያጠፋታል፤ ባድማም ያደርጋታል፤ ይገለብጣትማል፤ በእርስዋም የተቀመጡትን ይበትናል።'),
  ('1eaa9f85-fa4b-53a3-aa0a-3b41a871f927', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 2, 2, 'ሕዝቡ እንደ ካህኑ፥ ባሪያውም እንደ ጌታው ባሪያይቱም እንደ እመቤቷ፥ የሚሸጠውም እንደሚገዛው፥ ተበዳሪውም እንደ አበዳሪው፥ ዕዳ ከፋዩም እንደ ዕዳ አስከፋዩ ይሆናል።'),
  ('63e577e5-6bfd-5e5a-a564-da81203601f9', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 3, 3, 'እነሆ፥ ምድር መፈታትን ትፈታለች፤ ፈጽማም ትበረበራለች፤ የእግዚአብሔር አፍ እንዲህ ተናግሮአልና።'),
  ('167e539f-f976-555c-a5c3-116e53a27687', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 4, 4, 'ምድርም አለቀሰች፤ ጠፋችም፤ ዓለም ተገለበጠች፤ የምድርም ታላላቆች አለቀሱ።'),
  ('ed648525-bf5c-5335-a418-811e47c72c2f', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 5, 5, 'ምድርም በሚቀመጡባት ሰዎች ምክንያት በደለች፤ ሕጉን ተላልፈዋልና፥ ሥርዐቱንም ለውጠዋልና፥ የዘለዓለሙንም ቃል ኪዳን አፍርሰዋልና።'),
  ('e967f579-f04a-58a8-af58-197939790912', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 6, 6, 'ስለዚህ ምድር ትውጣቸዋለች፤ በእርስዋ የተቀመጡ በድለዋልና፤ በምድር የሚኖሩ ሰዎችም ይቸገራሉ፤ ጥቂት ሰዎችም ይቀራሉ።'),
  ('c735758d-8418-5dad-a141-f6ed604033d4', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 7, 7, 'የወይን ጠጅ አለቀሰች፤ የወይን ግንድ ደከመች፤ ልባቸው ደስ ያለው ሁሉ ተከዙ።'),
  ('03d55a34-1093-51ce-a1fe-4160fec5e427', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 8, 8, 'የከበሮአቸው ደስታ አልቆአል፤ መታጀራቸውም አልቃለች፤ የኃጥኣን ሀብት አልቆአል፤ የመሰንቆ ድምፅም ቀርቶአል።'),
  ('58198241-e8ef-579c-a571-efb5b32e1c34', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 9, 9, 'ወይንን የሚጠጡት አፈሩ፤ የሚያሰክር መጠጥም ለሚጠጡት መራራ ሆነ።'),
  ('33d1e3f9-b4ea-5bcc-aeed-58ea85047285', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 10, 10, 'ከተሞች ሁሉ ምድረ በዳ ሆኑ፤ ቤቶችም ሁሉ ማንም እንዳይገባባቸው ተዘጉ።'),
  ('0a419fe8-eb37-56e8-a333-3d800f59cb60', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 11, 11, 'ስለ ወይኑም ጠጅ በአደባባይ አልቅሱ፤ የምድር ደስታ ሁሉ ጨልሞአልና፥ የምድርም ሐሤት ፈልሶአልና።'),
  ('d5b342e7-61c2-51bd-a8f2-7c7003d2a3bc', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 12, 12, 'ከተሞችም ባድማ ይሆናሉ፤ ቤቶችም ባዶ ሆነው ይቀራሉ፤ ይጠፋሉም።'),
  ('233ea0ba-1ad5-52eb-a5ab-fc337b1a77e0', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 13, 13, 'ይህ ሁሉ በሀገር ውስጥ በአሕዛብ መካከል ይሆናል። የወይራ ፍሬ ለቀማ ባለቀ ጊዜ በቃርሚያው ውስጥ የወይራ ፍሬ እንደሚለቀም እንዲሁ የእስራኤልን ልጆች ይቃርሟቸዋል።'),
  ('04dee098-dac1-531d-ae81-09da356ed4b5', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 14, 14, 'እነዚህ ድምፃቸውን ያነሣሉ፤ በምድር የቀሩትም ስለ እግዚአብሔር ክብር በአንድነት ደስ ይላቸዋል፤ የባሕርም ውኃ ይናወጣል።'),
  ('03213dc2-b8f9-5db2-ab01-9e35385c0dcd', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 15, 15, 'ስለዚህም የእግዚአብሔር ክብር በባሕር ደሴቶች ይሆናል፤ የእግዚአብሔርም ስም ይከብራል።'),
  ('b5b1dd95-77f2-5daa-a5b1-0f0c620a7fe7', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 16, 16, 'የእስራኤል አምላክ እግዚአብሔር ሆይ፥ የጻድቁን ድንቅ ተስፋ ከምድር ዳርቻ ሰምተናል። እነርሱ ግን፥ “የእግዚአብሔርን ሕግ ለሚያፈርሱ ወንጀለኞች ወዮላቸው!” አሉ።'),
  ('a8f8ffb8-6cd3-522e-ab1a-3d1b5ce7d1f1', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 17, 17, 'በምድር ላይ በሚኖሩ፥ ፍርሀትና ገደል ወጥመድም አሉ።'),
  ('8d31e745-9738-5d6a-a519-bf7337970a96', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 18, 18, 'የሰማይ መስኮቶችም ተከፍተዋልና፥ የምድርም መሠረት ተናውጣለችና ከፍርሀት ድምፅ የሸሸ በገደል ይወድቃል፤ ከገደልም የወጣ በወጥመድ ይያዛል።'),
  ('7cbb23e3-050c-523e-a396-ff847c2164af', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 19, 19, 'ምድር ደነገጠች፤ ታወከችም፤ ምድር ጐሰቈለች፤ ተነዋወጠችም።'),
  ('78686d9b-dd96-5eda-a378-c52c5ced38a1', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 20, 20, 'ምድር በወይን እንደ ሰከረ ሰው ትንገዳገዳለች፤ እንደ ዳስም ትወዛወዛለች፤ ሕግን መተላለፍዋም ይከብድባታል፤ ትወድቅማለች፤ ደግማም አትነሣም።'),
  ('125c06dc-2524-5ba6-a9de-c94de1a2b852', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 21, 21, 'በዚያም ቀን እንደዚህ ይሆናል፤ እግዚአብሔር በሰማይ ሠራዊትና በምድር ነገሥታት ላይ እጁን ይጥላል።'),
  ('f8fef398-00f5-5a78-aac5-242e7b82dd9c', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 22, 22, 'እነርሱም ይሰበሰባሉ፤ ተዘግቶባቸውም በግዞት ቤት ይኖራሉ፤ ከብዙ ትውልድም በኋላ ይጐበኛሉ።'),
  ('7554bb39-f0ff-556d-afee-440a350970bb', '98dc763a-0342-5adf-a36d-6c4bc9760b01', '8c1348ea-ff5d-597b-ad95-dbae789551ff', 23, 23, 'ጣራቸው ይፈርሳል፤ ግድግዳቸውም ይወድቃል፤ የሠራዊት ጌታ እግዚአብሔር በጽዮን ተራራና በኢየሩሳሌም ላይ ይነግሣልና፥ በሽማግሌዎቹም ፊት ይከብራልና።'),
  ('02e31c65-081b-58bf-a9d3-c131b0956132', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 1, 1, 'እግዚአብሔር አምላኬ፥ ድንቅ ነገርን የዱሮ እውነተኛ ምክርን አድርገሃልና አከብርሃለሁ፤ ስምህንም አመሰግናለሁ።'),
  ('3e585c5a-d9d1-55f6-a138-209c9f6a3b57', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 2, 2, 'ከተሞችን ትቢያ አደረግህ፤ የተመሸጉ ከተሞችን፥ የኃጥኣንንም መሠረት አፈረስህ፤ ከተሞቻቸውም ለዘለዓለም አይሠሩም።'),
  ('ba0eb020-f3a0-56a4-aef7-5e568e62b252', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 3, 3, 'ስለዚህ ድሆች ወገኖች ያከብሩሃል፤ የተገፉ ሰዎች ከተሞችም ያከብሩሃል።'),
  ('c0820a31-5709-5ef1-a562-9edc53dfd77e', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 4, 4, 'ለተዋረዱ ሰዎች ከተሞች ረዳት ሆነሃልና፥ በችግራቸው የተጨነቁትን በደስታ ጋረድሃቸው፤ ከክፉዎች ሰዎችም አዳንሃቸው፤ ለተጠሙት ጥላ ሆንሃቸው፤ ለተገፉትም ሕይወት ሆንሃቸው።'),
  ('5159f278-c6e4-59c2-ae71-b36ce438db74', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 5, 5, 'ለእነርሱ አሳልፈህ ከሰጠኸን ከኃጥኣን ሰዎች የተነሣ በጽዮን እንደ ተጠሙ አእምሮአቸውን እንዳጡ ሰዎች ሆነናል።'),
  ('81610bc5-dcff-521f-acda-19b04e2bae82', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 6, 6, 'የሠራዊት ጌታ እግዚአብሔርም ለሕዝቡ ሁሉ ግብዣን ያደርጋል፤ በዚህ ተራራ ላይ ሐሤትን ያደርጋሉ፤ የወይን ጠጅንም ይጠጣሉ፤ ዘይትንም ይቀባሉ።'),
  ('a02f7f2e-62e2-5d33-a2f8-f74e14a2dc69', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 7, 7, 'በዚህም ተራራ ላይ ይህን ሁሉ ለአሕዛብ ሰጠ፤ ምክሩ ለአሕዛብ ሁሉ ናትና።'),
  ('c7de2cad-5373-5c7d-adfc-352e076fb18a', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 8, 8, 'ሞት ሰዎችን ዋጠ፤ በረታም፤ እንደ ገናም ጌታ እግዚአብሔር ከፊት ሁሉ እንባን ያብሳል፤ የሕዝቡንም ስድብ ከምድር ሁሉ ላይ ያስወግዳል፤ እግዚአብሔር በአፉ ተናግሮአልና።'),
  ('7909c311-5402-5a7f-a4bf-e2be499a9455', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 9, 9, 'በዚያም ቀን፥ “እነሆ፥ አምላካችን ይህ ነው፤ ተስፋ አድርገነዋል፤ ያድናልም፤ እግዚአብሔር ይህ ነው፤ ጠብቀነዋል፤ በመዳናችንም ደስ ይለናል፤ ሐሤትም እናደርጋለን” ይላሉ።'),
  ('c73368a2-e892-566b-a963-42447ce9a7a2', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 10, 10, 'እግዚአብሔር በዚህ ተራራ ላይ ዕረፍትን ይሰጠናል፤ እህልም በመንኰራኵር ጭድም በጭቃ እንደሚበራይ እንዲሁ ሞዓብ ይረገጣል።'),
  ('3f3fed88-5d86-5e47-a883-b7702264d410', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 11, 11, 'እርሱ ክፉ እንደ አደረገና እንደ አጠፋ በእርሱ ላይ እጁን ያነሣል፤ በእርሱም ላይ እጁን ያነሣው ስድብን ይሽራል።'),
  ('3249f60d-d42f-562a-ad80-419b90983f63', '53c4f57a-9351-56fc-ac56-d4a1037937eb', '44058381-c6da-5dc2-a411-53960b62b161', 12, 12, 'የተመሸገውንና ከፍ ከፍ ያለውንም ቅጥርህን ዝቅ ያደርገዋል። ያዋርደውማል፤ ወደ መሬትም እስከ አፈር ድረስ ይጥለዋል።'),
  ('9882df32-843f-5c15-a87b-a934e9a9606a', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 1, 1, 'በዚያም ቀን ይህን ቅኔ በይሁዳ ምድር ይዘምራሉ፤ እነሆም፥ የጸናችና የምታድን፥ ቅጥርንና ምሽግንም የምታደርግ ከተማ አለችን።'),
  ('3bdc1f79-80fe-5303-a530-2010ccff8048', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 2, 2, 'ፍትሕን የሚጠብቅና ጽድቅን የሚያደርግ ሕዝብ ይገባ ዘንድ በሮችን ክፈቱ።'),
  ('afebf62d-47b9-5cb9-a5b8-5aecf0995771', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 3, 3, 'በአንተ ላይ ታምናለችና በአንተ የምትደገፍ ነፍስን ፈጽመህ በሰላም ትጠብቃታለህ።'),
  ('be2a1ae1-9991-5437-aea9-e744b42cdcae', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 4, 4, 'ጌታ እግዚአብሔር የዘለዓለም አንባ ነውና ለዘለዓለም በእግዚአብሔር ታመኑ።'),
  ('18ecc250-0ca9-549f-a81e-07498d7a6934', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 5, 5, 'በከፍታ የሚኖሩትን ሰዎች ዝቅ ታደርጋለህ፤ የተመሸጉትንም ከተሞች ትጥላለህ፤ እስከ ምድርም ድረስ ታወርዳቸዋለህ።'),
  ('2cda541b-9b0e-59b3-af6f-97c9524afcea', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 6, 6, 'የየዋሃንና የትሑታን እግሮች ይረግጡአቸዋል።'),
  ('1c489e5b-49a3-5dc4-af97-7ff4998d0420', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 7, 7, 'የጻድቃን መንገድ የቀና ትሆናለች፤ የቅኖችም መንገድ ትጠረጋለች።'),
  ('d20d0c74-1937-54d2-a075-593d6418eba5', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 8, 8, 'የእግዚአብሔር መንገድ የቀና ነው፤ በቅዱስ ስሙም ታመን፤ ነፍሳችን የተመኘችውንም አገኘን።'),
  ('8c4b5f06-8d33-5e66-a88d-e9ebda54306f', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 9, 9, 'አቤቱ፥ አምላኬ ሆይ፥ ትእዛዝህ በምድር ላይ ብርሃን ነውና ነፍሴ በሌሊት ወደ አንተ ትገሠግሣለች። በምድር የምትኖሩም ጽድቅ መሥራትን ተማሩ።'),
  ('68e56bfa-c60b-57d1-ac67-1835d8a0271d', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 10, 10, 'በምድር ጽድቅን የማይማርና መልካምን የማያደርግ ኃጥእ አልቆአልና፥ የእግዚአብሔርን ክብር እንዳያይ ኀጢአተኛን ያስወግዱታል።'),
  ('d2f8d9c9-c991-5de1-aa14-3f115ae898d3', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 11, 11, 'አቤቱ፥ ከፍ ያለች ክንድህን አላወቁም፤ ካወቁ ግን ያፍራሉ። አላዋቆች ሰዎችን ቅንአት ያዛቸው፤ አሁንም እሳት ጠላቶችን ትበላለች።'),
  ('d6db322e-8a62-53eb-a48d-8f0f8a086ca5', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 12, 12, 'አቤቱ፥ አምላካችን ሁሉን ሰጥተኸናልና ሰላምን ስጠን።'),
  ('2dfa9cbb-80df-5462-ac33-f0f0f1c85560', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 13, 13, 'አቤቱ፥ አምላካችን ሆይ፥ አንተ ግዛን፤ ከአንተ በቀር ሌላ አናውቅምና፤ ስምህንም እንጠራለን።'),
  ('0b40e208-3ff8-5b91-a856-eb3aeb9fd0e5', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 14, 14, 'ነገር ግን ሙታን ሕይወትን አያዩአትም፤ ባለ መድኀኒቶችም አያስነሡም፤ ስለዚህም አንተ አምጥተሃቸዋል፤ አጥፍተሃቸውማል፤ ወንዶቻቸውንም ሁሉ አስወግደሃል።'),
  ('e165ebd3-2bd7-58ee-a7e6-e80c9eb38ae2', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 15, 15, 'አቤቱ፥ ክፋትን ጨምርባቸው፤ ለምድር ክቡራን ክፋትን ጨምርባቸው።'),
  ('b20bb416-8dd0-581c-a56a-b0681bb6b86a', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 16, 16, 'አቤቱ፥ በመከራዬ ጊዜ አሰብኹህ፤ በጥቂት መከራም ገሠጽኸኝ።'),
  ('e35def7e-ff57-5f9f-a8eb-ba0e03ca22b1', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 17, 17, 'የፀነሰች ሴት ለመውለድ ስትቀርብ እንደምትጨነቅና በምጥ እንደምትጮህ፥ አቤቱ፥ እንዲሁ በፊትህ ለወዳጅህ ሆነናል።'),
  ('4db3e9e8-a4d1-58b3-ac8c-f036236dae25', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 18, 18, 'አንተን በመፍራት አቤቱ፥ እኛ ፀንሰናል፤ ምጥም ይዞናል፤ በምድርም የማዳንህን መንፈስ ወለድን፤ በዓለምም የሚኖሩ ይወድቃሉ።'),
  ('671c2a1d-0973-54cd-afed-9cdf256714ed', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 19, 19, 'ሙታን ይነሣሉ፤ በመቃብር ያሉም ይድናሉ። በምድርም የሚኖሩ ደስ ይላቸዋል፤ ከአንተ የሚገኝ ጠል መድኀኒታቸው ነውና፤ የኃጥኣንንም ምድር ታጠፋለህ።'),
  ('08cbb4d7-a9e7-5a46-a220-193088126564', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 20, 20, 'ሕዝቤ ሆይ፥ ና፤ ወደ ቤትህም ግባ፤ ደጅህን በኋላህ ዝጋ፤ የእግዚአብሔርም ቍጣ እስኪያልፍ ድረስ ጥቂት ጊዜ ተሸሸግ።'),
  ('ea39f1cf-f026-543e-a4b6-761d3b064e24', '71f69568-0e30-53ce-a6cf-c3212db3be78', '94813276-dc8a-5929-a489-7d93cf54b765', 21, 21, 'እነሆ፥ እግዚአብሔር በምድር በሚኖሩት ላይ ከመቅደሱ መቅሠፍቱን ያመጣል፤ ምድርም ደምዋን ትገልጣለች፤ ሙታኖችዋንም ከእንግዲህ ወዲህ አትከድንም።'),
  ('334474e9-4855-5568-a750-3e61e105fa01', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 1, 1, 'በዚያም ቀን እግዚአብሔር በፈጣኑ እባብ ደራጎን ላይ፥ በክፉውም እባብ ደራጎን ላይ ልዩ፥ ታላቅና ብርቱ ሰይፍን ያመጣል። በባሕርም ውስጥ ያለውን ዘንዶ ይገድለዋል።'),
  ('c5cfb7ef-080f-529f-ad75-1599e3092190', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 2, 2, 'በዚያም ቀን ለተወደደው የወይን ቦታ ተቀኙለት።'),
  ('cfcb7a68-a8f7-50ea-a5b2-1ec759f7e177', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 3, 3, 'እኔ የጸናች ከተማ ነኝ፤ አንድዋን ከተማ ይወጋሉ። በከንቱ አጠጣኋት፤ በሌሊት ትጠመዳለች፤ በቀንም ግድግዳዋ ይወድቃል፤ የሚያነሣትም የለም።'),
  ('7b4d5587-0bbf-5082-a315-9c5943cf8ae0', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 4, 4, 'ስለ ጠቡ በእሳት አቃጥለው ዘንድ ቀርቃሃና ሣርን ማን በሰጠኝ! አሁንም እግዚአብሔር የተናገረውን ሁሉ ዛሬ አደረገ፤ እነርሱ ተቃጥለዋልና።'),
  ('264fadfd-e356-5d08-ac36-1d92a3e1acd3', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 5, 5, 'በውስጧ የሚኖሩ ይጮሃሉ፤ ከእርሱ ጋር ሰላምን እናድርግ፤ ከእርሱ ጋር ሰላምን እናድርግ።'),
  ('86a1654d-ce2a-5287-a441-18c260fbf6b8', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 6, 6, 'በሚመጣው ዘመን የያዕቆብ ልጆች ሥር ይሰድዳሉ፤ እስራኤልም ያብባል፤ በፍሬያቸውም የዓለሙን ፊት ይሞላሉ።'),
  ('7d3316b4-9817-5bd4-a6a9-0eb9dc86809f', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 7, 7, 'በውኑ የመቱትን እንደ መታ እንዲሁ እርሱን መታውን? ወይስ እነርሱ እንደ ተገደሉበት መገደል እርሱ ተገድሎአልን?'),
  ('5adedb1c-a33a-5db0-aa93-f336f4526784', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 8, 8, 'በጠብና በንቀት ይሰዳቸዋል፤ በቍጣና በክፉ መንፈስ ትገሥጻቸው ዘንድ ትጀምራለህን?'),
  ('1a7c779c-1476-59ba-a359-f355281eb976', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 9, 9, 'ስለዚህም የማምለኪያ ዐፀዶችና የፀሐይ ምስሎች ዳግመኛ እንዳይነሡ የመሠዊያውን ድንጋይ ሁሉ እንደ ደቀቀ እንደ ኖራ ድንጋይ ባደረገ ጊዜ ፥ እንዲሁ የያዕቆብ በደል ይሰረያል፤ ይህም ኀጢአትን የማስወገድ ፍሬ ሁሉ ነው።'),
  ('9943c51f-8213-597b-a461-975937d9082b', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 10, 10, 'በዚያም የተሰማራው መንጋ እንደ ተተወ መንጋ ይሆናል፤ ምድሩም ለብዙ ዘመን መሰማሪያ ይሆናል፤ በዚያም መንጋው ይሰማራል፤ ያርፋልም።'),
  ('78a672ce-8183-5c22-ad83-4b5d1c7f458d', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 11, 11, 'ዘግይቶ ይደርቃል፤ በውስጡም ልምላሜ ሁሉ አይገኝም፤ ከቲኣሳ የምትመጡ ሴቶች፥ ኑና ለሕዝቤ አልቅሱ፤ የማያስተውል ሕዝብ ነውና፤ ስለዚህ ፈጣሪው አይራራለትም፤ ሠሪውም ምሕረት አያደርግለትም።'),
  ('d8b1b9ef-b2f5-5dad-a2e7-2034dd7b6998', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 12, 12, 'በዚያ ቀን እንዲህ ይሆናል፤ እግዚአብሔር ከወንዝ ፈሳሽ ጀምሮ እስከ ግብፅ ወንዝ ድረስ ዐጥር ያጥራል፤ እናንተም የእስራኤል ልጆች ሆይ፥ አንድ በአንድ ትሰበሰባላችሁ።'),
  ('f5d71efc-a12d-5a3a-ab0c-9ef915156f50', '8c911086-5d56-5936-a575-ecaeb195a8ec', 'f5c7b78e-de08-5814-a8e2-a472edd686ce', 13, 13, 'በዚያም ቀን እንዲህ ይሆናል፤ ታላቅ መለከት ይነፋል፤ በአሦርም የጠፉ፥ በግብፅ ምድርም የተሰደዱ ይመጣሉ፤ በተቀደሰውም ተራራ በኢየሩሳሌም ለእግዚአብሔር ይሰግዳሉ።'),
  ('0289b60a-9100-55f4-ae46-1e13e96fe12c', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 1, 1, 'ለኤፍሬም ምንደኞች ትዕቢት አክሊል፥ ያለ ወይን ጠጅ ለሰከሩ፥ በወፍራም ተራራ ራስ ላይ ላለችም ለረገፈች ለክብር ጌጥ አበባ ወዮ!'),
  ('7f3bd78b-32d4-5e75-abae-13f89c8bf925', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 2, 2, 'እነሆ፥ ኀያል ብርቱ የሆነ የእግዚአብሔር መቅሠፍት በኀይል እንደሚወርድ የበረዶ ወጨፎ፥ እንደሚያጠፋም ዐውሎ ነፋስ፥ እንደሚያጥለቀልቅም እንደ ብዙ ውኃ ፈሳሽ በጠነከረ እጅ ወደ ምድር ይጥላል።'),
  ('cd09c30c-95c7-5c8a-a114-b3b03a6b4ba8', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 3, 3, 'የኤፍሬም ምንደኞች ትዕቢት አክሊል በእጅና በእግር ይረገጣል፤'),
  ('a038db69-eb7a-5e47-a3e5-7f369e9da692', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 4, 4, 'በረዥም ተራራ ራስ ላይ ያለች የረገፈች የክብሩ ተስፋ አበባ አስቀድማ እንደምትበስል በለስ ትሆናለች፤ ሰውም ባያት ጊዜ በእጁ ሳይቀበላት ይበላት ዘንድ ይፈጥናል።'),
  ('43f7db7a-2e3a-5625-a374-5d45c5421e23', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 5, 5, 'በዚያ ቀን የሠራዊት ጌታ እግዚአብሔር ለተረፉት ሕዝቡ የክብር የተጐነጐነ ዘውድና የተስፋ አክሊል ይሆናል።'),
  ('a08449c0-9e27-596e-a07b-60085fe83514', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 6, 6, 'ለፍርድና ከጥፋት ለሚያድናቸው ኀይል በፍርድ መንፈስ ይቀራሉ።'),
  ('ce84fa9d-6e46-5853-aebe-2bde16b13f4a', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 7, 7, 'እነዚህም ደግሞ ከወይን ጠጅ የተነሣ ይስታሉ፤ ከሚያሰክርም መጠጥ የተነሣ አላዋቆች ይሆናሉ፤ ካህኑና ነቢዩ ከሚያሰክር መጠጥ የተነሣ ይስታሉ፤ በወይን ጠጅም ይዋጣሉ፤ ከሚያሰክርም መጠጥ የተነሣ ይበድላሉ፤ ይህም የዐይን ምትሐት ነው፤ በፍርድ ይሰናከላሉ።'),
  ('d0ca2c35-1547-5eed-a8b1-acbceca7e8bb', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 8, 8, 'ማዕዱም ሁሉ ትፋትንና ርኵሰትን ተሞልቶአል፤ ንጹሕ ስፍራ እንኳን የለም።'),
  ('ef77ab07-66e3-5eb2-a313-6ab25c370d8a', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 9, 9, 'ክፉን ለማን ተናገርን? ወሬን ለማን አወራን? ወተትን ለተዉ ወይስ ጡትን ለጣሉ ነውን?'),
  ('bdc6d69e-fe72-56f0-a242-dcf697807679', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 10, 10, 'ሕማምን በሕማም ላይ፥ ተስፋንም በተስፋ ላይ ተቀበሉ፤ ጥቂት በዚህ ጥቂት በዚያ ነው።'),
  ('610d5f84-61a0-5a2c-a63d-9738e6f50d41', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 11, 11, 'በባዕድ አፍ በልዩም ልሳን ለዚህ ሕዝብ ይናገራል፤'),
  ('c43d5d52-4bfe-5907-a89e-c155cf547260', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 12, 12, 'እርሱም፥ “ይህችም ለደከመ ዕረፍት ናት፤ ይህችም መቅሠፍት ናት፤” አላቸው፤ እነርሱ ግን መስማትን እንቢ አሉ።'),
  ('9498636d-79ca-5e0c-a0b5-930d4db81da7', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', 'aed5d5c5-4191-56d5-acf2-df4b7cfd0822', 13, 13, 'ስለዚህ ሄደው ወደ ኋላ እንዲወድቁ፥ እንዲሰበሩም፥ ተጠምደውም እንዲቸገሩ፥ የግዚአብሔርም ቃሉ በሕማም ላይ ሕማም፥ በተስፋ ላይ ተስፋ፥ ጥቂት በዚህ ጥቂት በዚያ ይሆንላቸዋል።'),
  ('6b1f1964-e96a-5663-a61e-a9f326f546c0', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 1, 14, 'ስለዚህ የተጨነቃችሁ ሰዎችና በኢየሩሳሌም ያለውን ሕዝብ የምትገዙ አለቆች ሆይ፥ የእግዚአብሔርን ቃል ስሙ።'),
  ('4cb895f0-5b55-5963-a477-9cba9aee83c8', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 2, 15, 'እናንተም “ከሲኦል ጋር ተማምለናል፤ ከሞትም ጋር ቃል ኪዳን አድርገናል፤ ሐሰትንም መሸሸጊያን አድርገናልና፥ በሐሰትም ተሰውረናልና፥ ዐውሎ ነፋስም ባለፈ ጊዜ አይደርስብንም” ትላላችሁና፥'),
  ('7939d4ce-72e1-5607-a51b-5b17b49ef59d', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 3, 16, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ በጽዮን ድንጋይን ለመሠረት አስቀምጣለሁ፤ ዋጋው ብዙ የሆነውን፥ የተመረጠውን፥ የከበረውንና መሠረቱ የጸናውን የማዕዘን ድንጋይ አኖራለሁ፤ በእርሱም የሚያምን አያፍርም።'),
  ('b03e7f77-79dd-5cce-aab8-43a998f6063e', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 4, 17, 'ፍርዴን ለተስፋ ይቅርታዬንም ለትክክለኛ ሚዛን አደርጋለሁ፤ በከንቱና በሐሰት የሚታመኑ ከዐውሎ ነፋስ አያመልጡም።'),
  ('689ead8a-24d4-5832-acc3-0d8c0546acee', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 5, 18, 'ከሞትም ጋር ያደረጋችሁት ቃል ኪዳን ይፈርሳል፤ ከኢኦልም ጋር የተማማላችሁት መሐላ አይጸናም፤ የሚያልፍ ዐውሎ ነፋስ በመጣ ጊዜ ይረግጣችኋል፤ ትደክማላችሁም።'),
  ('845a87cd-f062-5fad-a111-d73d64bd6cc6', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 6, 19, 'ባለፈም ጊዜ ይወስዳችኋል፤ ማለዳ ማለዳ በቀን ያልፋል፤ በሌሊት ክፉ ተስፋ ይሆናል፤ እናንተ ያዘናችሁ፥ መስማትን ተማሩ።”'),
  ('072f599f-db56-5d59-a828-1255d7dfbe53', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 7, 20, 'መዋጋትን አንችልም፤ እናንተንም ለመሰብሰብ ደካሞች ነን።'),
  ('c2f8d6fe-dfd9-5c78-a87b-8a940ff40d02', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 8, 21, 'እግዚአብሔርም በኃጥኣን ተራራ እንደ ነበረ ይነሣል፤ በገባዖን ሸለቆም ይኖራል፤ ሥራውን ማለት መራራ ሥራውን በቍጣ ይሠራል፤ ቍጣውም ድንቅን ያደርጋል፤ መርዙም ልዩ ነው።'),
  ('bd269d69-2f1c-53a1-a1c5-0a723a7a5166', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 9, 22, 'አሁንም በምድር ሁሉ ላይ የሚያደርገውን ያለቀና የተቈረጠ ነገርን ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ ሰምቻለሁና እስራታችሁ እንዳይጸናባችሁ እናንተ ደስ አይበላችሁ።'),
  ('7c38bba5-f291-57ed-ab1d-6dd6143cb759', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 10, 23, 'አድምጡ፤ ድምፄንም ስሙ፤ ልብ አድርጉ፤ ንግግሬንም ስሙ።'),
  ('6bb386c3-6b05-5e4c-abe8-c56b08acde78', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 11, 24, 'በውኑ ገበሬ ሊዘራ ሁልጊዜ ያርሳልን? ወይስ ምድሩን ከማረሱ አስቀድሞ ዘርን ይዘራልን? ጓሉንስ ይከሰክሳልን?'),
  ('af08d878-474d-5762-aea2-6555caf5ec82', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 12, 25, 'እርሻውን ባስተካከለ ጊዜ ጥቂት ጥቍሩን አዝሙድ፥ ከሙኑንም፥ ዳግመኛም ስንዴውን፥ ገብሱንም፥ አጃውንም በየስፍራው የሚዘራ አይደለምን?'),
  ('d9ef68ea-c103-5457-a576-0a5eefe7df37', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 13, 26, 'ምድርም የእግዚአብሔርን ፍርድ ተምራ ደስ ይላታል።'),
  ('233bda30-4222-5ec3-a7c7-4fcc90138f26', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 14, 27, 'ጥቍሩን አዝሙድ በተሳለች ማሄጃ አያሄድም፤ የሰረገላም መንኰራኵር በከሙን ላይ አይዞርም፤ ነገር ግን ጥቍሩን አዝሙድ በሽመል፥ ከሙኑንም በበትር ይወቃል።'),
  ('e11ac917-482c-579f-a424-e8f997afcf35', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 15, 28, 'እኔ ለዘለዓለም በእናንተ ላይ አልቈጣም፤ የምሕረቴም ድምፅ አያጠፋችሁም።'),
  ('6000551f-4faf-58f0-ab5f-399b6068522c', '2d9f1d53-c3d6-5b64-a87a-d493528231d5', '38100370-25d8-52bc-a20b-7bd198dbddff', 16, 29, 'ይህም ደግሞ ድንቅ ምክርን ከሚመክር በግብሩም ገናና ከሆነው ከሠራዊት ጌታ ከእግዚአብሔር ወጥቶአል። እናንተ ግን ከንቱ መጽናናትን ታበዙ ዘንድ ትሻላችሁ።'),
  ('14a3a581-4340-5956-afee-37835ea39255', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 1, 1, 'ዳዊት ለሰፈረባት ከተማ ለአርኤል ወዮላት! የዓመቱን አዝመራ ሰብስቡ፤ ከሞዓብ ጋር ትበላላችሁና።'),
  ('98693292-6ed5-5ab0-ab54-557ee87e9567', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 2, 2, 'አርኤልንም አስጨንቃለሁ፤ ይህችም ኀይል፥ ይህችም ብዕል የእኔ ትሆናለች፥'),
  ('51a2af14-96bf-5190-a8b7-f0161b821aba', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 3, 3, 'እንደ ዳዊትም እከብሻለሁ፤ በቅጥርም አጥርሻለሁ፤ አንባም በላይሽ አቆማለሁ።'),
  ('ad61fa32-9655-5033-a517-4a8beb848255', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 4, 4, 'ነገርሽም በምድር ውስጥ ይሰጥማል፤ ቃልሽም ከምድር በታች እንደሚናገር ይሆናል፤ ትደክሚያለሽ፤ ቃልሽም በምድር ውስጥ ዝቅ ይላል።'),
  ('0e14b3e7-4b9a-55d5-a5cc-773c8124938b', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 5, 5, 'ነገር ግን የኃጥአን ብልጽግና እንደ ደቀቀ ትቢያ፥ የጠላቶችሽም ብዛት ነፋስ እንደሚያመጣው ገለባ ይሆናል።'),
  ('30a244cb-353e-5e36-ac12-89c0d3da8f38', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 6, 6, 'ድንገትም ፈጥኖ የሠራዊት ጌታ እግዚአብሔር በነጐድጓድ፥ በምድርም መናወጥ፥ በታላቅ ድምፅ፥ በዐውሎ ነፋስም፥ በወጨፎም፥ በምትበላም በእሳት ነበልባል ይጐበኛታል።'),
  ('2238d604-6c35-5e40-af94-83838f21713a', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 7, 7, 'በአርኤልም ላይ የሚዋጉ፥ ኢየሩሳሌምንም የሚወጉ፥ በእርሻዋም ላይ የሚሰበሰቡ የሚያስጨንቋትም፥ የአሕዛብ ሁሉ ብልጽግና እንደሚያልም ሰው ሕልም ነው።'),
  ('be1b2e42-b703-596b-a53d-3fd0e2c1a1ae', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 8, 8, 'ሰዎች ተርበው ሌሊት በሕልማቸው ይበላሉ፤ ይጠጣሉም፤ በተነሡ ጊዜ ግን ሕልማቸው ከንቱ ነው። የተጠማ ሰውም እንደሚጠጣ ያልማል፤ በነቃም ጊዜ እንደ ተጠማ ነው፤ ነፍሱም በከንቱ ትመኛለች። ደብረ ጽዮንን የሚዋጉ የአሕዛብ ብልጽግናም እንደዚሁ ነው።'),
  ('f562bd33-2c6a-52ca-afd4-5f3967cbb683', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 9, 9, 'ደከሙ፤ ደነገጡም፤ ሰከሩም፤ በወይን አይይደለም፤ በጠጅም አይደለም።'),
  ('17842723-efa9-58b4-ac35-4ffdb4b889d8', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 10, 10, 'እግዚአብሔር የእንቅልፍ መንፈስን አፍስሶባቸዋል፤ ዐይኖቻቸውን፥ የነቢያትንም ዐይን፥ የተሰወረውንም የሚያዩ የአለቆቻቸውን ዐይን ጨፍኖባቸዋል።'),
  ('97af4af0-66e6-5700-a538-49e5cc24dad8', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 11, 11, 'ይህም ሁሉ ነገር እንደ ታተመ መጽሐፍ ቃል ሆኖባቸዋል፤ ማንበብንም ለሚያውቅ፥ “ይህን አንብብ” ብለው በሰጡት ጊዜ እርሱ፥ “ታትሟልና ማንበብ አልችልም” ይላቸዋል፤'),
  ('a40a0845-a40a-54f2-ac42-594fbdfd3ced', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 12, 12, 'ደግሞም መጽሐፉን ማንበብን ለማያውቅ፥ “ይህን አንብብ” ብለው በሰጡት ጊዜ እርሱ፥ “ማንበብ አላውቅም” ይላቸዋል።'),
  ('6679015b-0a23-5f09-aef1-c02841f55251', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 13, 13, 'ጌታም አለ፥ “ይህ ሕዝብ በከንፈሮቹ ያከብረኛልና፥ ልቡ ግን ከእኔ የራቀ ነውና፥ በከንቱ ያመልኩኛል፤ ሰው ሠራሽ ትምህርትም ያስተምራሉ፤'),
  ('e99595c0-70e4-5e5a-a41f-a34a7e0668dc', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 14, 14, 'ስለዚህ፥ እነሆ፥ ይህ ሕዝብ በድጋሚ እንዲፈልስ አደርጋለሁ፤ አፈልሳቸዋለሁም፤ የጥበበኞችንም ጥበብ አጠፋለሁ፤ የአስተዋዮችንም ማስተዋል እሰውራለሁ።”'),
  ('6ccb0315-b4ae-51d5-a8e4-05354d2c2413', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 15, 15, 'ምክራቸውን ጥልቅ አድርገው ከእግዚአብሔር ለሚሰውሩ ወዮላቸው! ሥራቸውንም በጨለማ ውስጥ አድርገው፥ “ማን ያየናል? ወይስ ማን ያውቀናል?” ለሚሉ ወዮላቸው!'),
  ('72999495-8ef4-5642-a6ac-d9530a46f570', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 16, 16, 'ይህ የእናንተ ጠማምነት ነው፤ እንደ ሸክላ ሠሪ ጭቃ የምትቈጠሩ አይደላችሁምን? በውኑ ሥራ ሠሪውን፥ “አልሠራኸኝም” ይለዋልን? ወይስ የተደረገ አድራጊውን፥ “በማስተዋል አላሳመርኸኝም” ይለዋልን?'),
  ('79e30568-eef5-51ef-a315-8352f1d55045', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 17, 17, 'ሊባኖስ እንደ ፍሬያማ እርሻ ሊለወጥ፥ ፍሬያማውም እርሻ እንደ ዱር ሊቈጠር ጥቂት ዘመን የቀረ አይይደለምን?'),
  ('18f3a3a3-f4c4-59e3-a8e1-d76ea471b721', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 18, 18, 'በዚያም ቀን ደንቆሮች የመጽሐፍን ቃል ይሰማሉ፤ በጨለማና በጭጋግ ውስጥም የዕውሮች ዐይኖች ያያሉ።')
